#!/usr/bin/env tsx

/**
 * Complete Database Setup Script
 * 
 * This script:
 * 1. Creates the missing handle_updated_at() function
 * 2. Pushes all remaining migrations via Supabase CLI
 * 3. Can be run on new server setups
 * 
 * Usage: npm run setup-db
 */

import { execSync } from 'child_process';
import { existsSync } from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const SUPABASE_CLI = '/tmp/supabase';

function log(message: string, type: 'info' | 'success' | 'error' | 'warning' = 'info') {
    const icons = {
        info: 'ℹ️ ',
        success: '✅',
        error: '❌',
        warning: '⚠️ '
    };
    console.log(`${icons[type]} ${message}`);
}

function executeCommand(command: string, description: string): boolean {
    try {
        log(description, 'info');
        execSync(command, {
            stdio: 'inherit',
            cwd: path.join(__dirname, '..'),
            encoding: 'utf-8'
        });
        log(`${description} - Complete`, 'success');
        return true;
    } catch (error: any) {
        log(`${description} - Failed: ${error.message}`, 'error');
        return false;
    }
}

async function main() {
    console.log('\n🚀 Kiroxys Database Setup\n');
    console.log('═══════════════════════════════════════\n');

    // Check if Supabase CLI exists
    if (!existsSync(SUPABASE_CLI)) {
        log('Supabase CLI not found at /tmp/supabase', 'error');
        log('Please download it first or install globally', 'info');
        process.exit(1);
    }

    // Step 1: Check if we're linked to a project
    log('Checking Supabase project link...', 'info');
    try {
        execSync(`${SUPABASE_CLI} projects list`, { stdio: 'ignore' });
        log('Supabase CLI authenticated', 'success');
    } catch {
        log('Not logged in to Supabase CLI', 'warning');
        log('Running login process...', 'info');

        if (!executeCommand(`${SUPABASE_CLI} login`, 'Supabase login')) {
            log('Login failed. Please run: /tmp/supabase login', 'error');
            process.exit(1);
        }
    }

    // Step 2: Push all migrations
    log('\nPushing all database migrations...', 'info');
    console.log('This will:');
    console.log('  - Create missing handle_updated_at() function');
    console.log('  - Apply all pending migrations');
    console.log('  - Set up complete database schema\n');

    const success = executeCommand(
        `${SUPABASE_CLI} db push --include-all`,
        'Applying migrations'
    );

    if (!success) {
        log('\nMigration failed. This might be because:', 'warning');
        log('  1. Project not linked - Run: /tmp/supabase link --project-ref YOUR_PROJECT_ID', 'info');
        log('  2. Network issue - Check your connection', 'info');
        log('  3. Permission issue - Verify your Supabase credentials', 'info');
        process.exit(1);
    }

    // Step 3: Success!
    console.log('\n═══════════════════════════════════════\n');
    log('Database setup complete! 🎉', 'success');
    console.log('\nNext steps:');
    console.log('  1. Open your app: http://localhost:8080');
    console.log('  2. Create your first project');
    console.log('  3. Start managing your projects!\n');
}

main().catch((error) => {
    log(`Unexpected error: ${error.message}`, 'error');
    process.exit(1);
});

import React, { useState } from 'react';
import {
  Check,
  ChevronDown,
  Plus,
  X,
  FileText,
  Layout,
  BarChart3,
  Calendar,
  Users,
  AlertTriangle,
  DollarSign,
  Target,
  MessageSquare,
  Folder,
  Flag,
  GitBranch,
  TrendingUp,
  CheckCircle2,
  ListTodo,
  Scale,
  Settings,
  Presentation,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Separator } from '@/components/ui/separator';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible';
import { cn } from '@/lib/utils';

export interface ContextItem {
  id: string;
  type: 'page' | 'text';
  label: string;
  icon?: React.ReactNode;
  description?: string;
}

interface ContextSelectorProps {
  selectedContexts: ContextItem[];
  onContextChange: (contexts: ContextItem[]) => void;
  currentView: string;
  compact?: boolean;
}

// Available pages/modules
const AVAILABLE_PAGES: ContextItem[] = [
  { id: 'dashboard', type: 'page', label: 'Dashboard', icon: <Layout className="h-4 w-4" />, description: 'Project overview and KPIs' },
  { id: 'gantt', type: 'page', label: 'Gantt Chart', icon: <BarChart3 className="h-4 w-4" />, description: 'Schedule and dependencies' },
  { id: 'project-plan', type: 'page', label: 'Project Plan', icon: <ListTodo className="h-4 w-4" />, description: 'Task breakdown and assignments' },
  { id: 'sprints', type: 'page', label: 'Sprint Board', icon: <Target className="h-4 w-4" />, description: 'Agile sprint management' },
  { id: 'risks', type: 'page', label: 'Risk Register', icon: <AlertTriangle className="h-4 w-4" />, description: 'Risks and mitigation' },
  { id: 'issues', type: 'page', label: 'Issues Register', icon: <AlertTriangle className="h-4 w-4" />, description: 'Active issues and blockers' },
  { id: 'financials', type: 'page', label: 'Financials', icon: <DollarSign className="h-4 w-4" />, description: 'Budget and costs' },
  { id: 'evm', type: 'page', label: 'Earned Value', icon: <TrendingUp className="h-4 w-4" />, description: 'EVM metrics and forecasts' },
  { id: 'resources', type: 'page', label: 'Resources', icon: <Users className="h-4 w-4" />, description: 'Team allocation and capacity' },
  { id: 'meetings', type: 'page', label: 'Meetings', icon: <Calendar className="h-4 w-4" />, description: 'Meeting notes and actions' },
  { id: 'calendar', type: 'page', label: 'Calendar', icon: <Calendar className="h-4 w-4" />, description: 'Project calendar' },
  { id: 'communications', type: 'page', label: 'Communications', icon: <MessageSquare className="h-4 w-4" />, description: 'Email and messages' },
  { id: 'documents', type: 'page', label: 'Documents', icon: <Folder className="h-4 w-4" />, description: 'Project files' },
  { id: 'notes', type: 'page', label: 'Notes', icon: <FileText className="h-4 w-4" />, description: 'Project notes' },
  { id: 'presentations', type: 'page', label: 'Presentations', icon: <Presentation className="h-4 w-4" />, description: 'Slides and decks' },
  { id: 'stakeholders', type: 'page', label: 'Stakeholders', icon: <Users className="h-4 w-4" />, description: 'Stakeholder register' },
  { id: 'milestones', type: 'page', label: 'Milestones', icon: <Flag className="h-4 w-4" />, description: 'Key milestones' },
  { id: 'deliverables', type: 'page', label: 'Deliverables', icon: <CheckCircle2 className="h-4 w-4" />, description: 'Project deliverables' },
  { id: 'change-requests', type: 'page', label: 'Change Requests', icon: <GitBranch className="h-4 w-4" />, description: 'Change control' },
  { id: 'tracking', type: 'page', label: 'Tracking', icon: <TrendingUp className="h-4 w-4" />, description: 'Baseline comparison' },
  { id: 'decisions', type: 'page', label: 'Decisions', icon: <Scale className="h-4 w-4" />, description: 'Decision log' },
  { id: 'actions', type: 'page', label: 'Actions', icon: <CheckCircle2 className="h-4 w-4" />, description: 'Action items' },
  { id: 'team-chat', type: 'page', label: 'Team Chat', icon: <MessageSquare className="h-4 w-4" />, description: 'Team collaboration' },
];

export function ContextSelector({ selectedContexts, onContextChange, currentView, compact = false }: ContextSelectorProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [showTextInput, setShowTextInput] = useState(false);
  const [customText, setCustomText] = useState('');
  const [isExpanded, setIsExpanded] = useState(true);

  const selectedPageIds = selectedContexts.filter(c => c.type === 'page').map(c => c.id);
  const customTexts = selectedContexts.filter(c => c.type === 'text');

  const handlePageToggle = (page: ContextItem) => {
    const isSelected = selectedPageIds.includes(page.id);
    if (isSelected) {
      onContextChange(selectedContexts.filter(c => c.id !== page.id));
    } else {
      onContextChange([...selectedContexts, page]);
    }
  };

  const handleAddCustomText = () => {
    if (!customText.trim()) return;

    const newContext: ContextItem = {
      id: `text-${Date.now()}`,
      type: 'text',
      label: customText.trim().slice(0, 50) + (customText.length > 50 ? '...' : ''),
      description: customText.trim(),
    };

    onContextChange([...selectedContexts, newContext]);
    setCustomText('');
    setShowTextInput(false);
  };

  const handleRemoveContext = (contextId: string) => {
    onContextChange(selectedContexts.filter(c => c.id !== contextId));
  };

  const handleSelectAll = () => {
    const allPages = AVAILABLE_PAGES.map(p => ({ ...p }));
    const existingTexts = selectedContexts.filter(c => c.type === 'text');
    onContextChange([...allPages, ...existingTexts]);
  };

  const handleClearPages = () => {
    onContextChange(selectedContexts.filter(c => c.type === 'text'));
  };

  // Track if we've already auto-added to prevent infinite loops
  const hasAutoAddedRef = React.useRef(false);

  // Auto-add current page only once on mount when contexts are empty
  React.useEffect(() => {
    if (!hasAutoAddedRef.current && selectedContexts.length === 0) {
      const currentPage = AVAILABLE_PAGES.find(p => p.id === currentView);
      if (currentPage) {
        hasAutoAddedRef.current = true;
        onContextChange([currentPage]);
      }
    }
  }, [currentView, selectedContexts.length, onContextChange]);

  // Reset ref when view changes to allow re-initialization
  React.useEffect(() => {
    hasAutoAddedRef.current = false;
  }, [currentView]);

  // Compact mode: Just show a button to add more context
  if (compact) {
    return (
      <Popover open={isOpen} onOpenChange={setIsOpen}>
        <PopoverTrigger asChild>
          <Button variant="ghost" size="sm" className="h-5 px-2 text-xs gap-1">
            <Plus className="h-3 w-3" />
            Add
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-72 p-0" align="start">
          <Command>
            <CommandInput placeholder="Search pages..." />
            <div className="flex items-center justify-between px-2 py-1.5 border-b">
              <Button variant="ghost" size="sm" className="text-xs h-6" onClick={handleSelectAll}>
                Select All
              </Button>
              <Button variant="ghost" size="sm" className="text-xs h-6" onClick={handleClearPages}>
                Clear
              </Button>
            </div>
            <CommandList>
              <CommandEmpty>No pages found.</CommandEmpty>
              <CommandGroup heading="Pages">
                <ScrollArea className="h-48">
                  {AVAILABLE_PAGES.map((page) => (
                    <CommandItem
                      key={page.id}
                      onSelect={() => handlePageToggle(page)}
                      className="cursor-pointer"
                    >
                      <div className={cn(
                        "flex items-center justify-center w-4 h-4 mr-2 border rounded",
                        selectedPageIds.includes(page.id)
                          ? "bg-primary border-primary text-primary-foreground"
                          : "border-muted-foreground"
                      )}>
                        {selectedPageIds.includes(page.id) && (
                          <Check className="h-3 w-3" />
                        )}
                      </div>
                      <div className="flex items-center gap-2 flex-1">
                        {page.icon}
                        <span className="text-sm">{page.label}</span>
                      </div>
                    </CommandItem>
                  ))}
                </ScrollArea>
              </CommandGroup>
              <Separator />
              <CommandGroup heading="Custom Text">
                {showTextInput ? (
                  <div className="p-2 space-y-2">
                    <Textarea
                      placeholder="Add custom context..."
                      value={customText}
                      onChange={(e) => setCustomText(e.target.value)}
                      className="min-h-[60px] text-xs resize-none"
                    />
                    <div className="flex gap-2">
                      <Button size="sm" className="flex-1 text-xs" onClick={handleAddCustomText}>
                        Add
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        className="text-xs"
                        onClick={() => {
                          setShowTextInput(false);
                          setCustomText('');
                        }}
                      >
                        Cancel
                      </Button>
                    </div>
                  </div>
                ) : (
                  <CommandItem onSelect={() => setShowTextInput(true)} className="cursor-pointer">
                    <Plus className="h-3 w-3 mr-2" />
                    Add custom text
                  </CommandItem>
                )}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    );
  }

  return (
    <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
      <div className="border rounded-lg bg-muted/30">
        <CollapsibleTrigger asChild>
          <button className="flex items-center justify-between w-full px-3 py-2 text-sm hover:bg-muted/50 transition-colors">
            <div className="flex items-center gap-2">
              <FileText className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium">Context</span>
              <Badge variant="secondary" className="text-xs">
                {selectedContexts.length}
              </Badge>
            </div>
            <ChevronDown className={cn(
              "h-4 w-4 text-muted-foreground transition-transform",
              isExpanded && "rotate-180"
            )} />
          </button>
        </CollapsibleTrigger>

        <CollapsibleContent>
          <div className="px-3 pb-3 space-y-2">
            {/* Selected Contexts Display */}
            {selectedContexts.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {selectedContexts.map((ctx) => (
                  <Badge
                    key={ctx.id}
                    variant="outline"
                    className={cn(
                      "gap-1 pr-1",
                      ctx.type === 'text' ? "bg-primary/10 border-primary/30" : ""
                    )}
                  >
                    {ctx.type === 'page' ? ctx.icon : <FileText className="h-3 w-3" />}
                    <span className="text-xs max-w-[80px] truncate">{ctx.label}</span>
                    <button
                      onClick={() => handleRemoveContext(ctx.id)}
                      className="ml-0.5 hover:bg-muted rounded p-0.5"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            )}

            {/* Page Selector */}
            <Popover open={isOpen} onOpenChange={setIsOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="w-full justify-between">
                  <span className="text-xs">Add pages/modules...</span>
                  <ChevronDown className="h-3 w-3" />
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-72 p-0" align="start">
                <Command>
                  <CommandInput placeholder="Search pages..." />
                  <div className="flex items-center justify-between px-2 py-1.5 border-b">
                    <Button variant="ghost" size="sm" className="text-xs h-6" onClick={handleSelectAll}>
                      Select All
                    </Button>
                    <Button variant="ghost" size="sm" className="text-xs h-6" onClick={handleClearPages}>
                      Clear
                    </Button>
                  </div>
                  <CommandList>
                    <CommandEmpty>No pages found.</CommandEmpty>
                    <CommandGroup>
                      <ScrollArea className="h-64">
                        {AVAILABLE_PAGES.map((page) => (
                          <CommandItem
                            key={page.id}
                            onSelect={() => handlePageToggle(page)}
                            className="cursor-pointer"
                          >
                            <div className={cn(
                              "flex items-center justify-center w-4 h-4 mr-2 border rounded",
                              selectedPageIds.includes(page.id)
                                ? "bg-primary border-primary text-primary-foreground"
                                : "border-muted-foreground"
                            )}>
                              {selectedPageIds.includes(page.id) && (
                                <Check className="h-3 w-3" />
                              )}
                            </div>
                            <div className="flex items-center gap-2 flex-1">
                              {page.icon}
                              <div>
                                <div className="text-sm">{page.label}</div>
                                <div className="text-xs text-muted-foreground">{page.description}</div>
                              </div>
                            </div>
                          </CommandItem>
                        ))}
                      </ScrollArea>
                    </CommandGroup>
                  </CommandList>
                </Command>
              </PopoverContent>
            </Popover>

            <Separator className="my-2" />

            {/* Custom Text Input */}
            {showTextInput ? (
              <div className="space-y-2">
                <Label className="text-xs">Additional Context</Label>
                <Textarea
                  placeholder="Add custom context or instructions..."
                  value={customText}
                  onChange={(e) => setCustomText(e.target.value)}
                  className="min-h-[60px] text-xs resize-none"
                />
                <div className="flex gap-2">
                  <Button size="sm" className="flex-1 text-xs" onClick={handleAddCustomText}>
                    Add
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    className="text-xs"
                    onClick={() => {
                      setShowTextInput(false);
                      setCustomText('');
                    }}
                  >
                    Cancel
                  </Button>
                </div>
              </div>
            ) : (
              <Button
                variant="ghost"
                size="sm"
                className="w-full justify-start text-xs text-muted-foreground"
                onClick={() => setShowTextInput(true)}
              >
                <Plus className="h-3 w-3 mr-2" />
                Add custom text context
              </Button>
            )}

            {/* Custom Text Contexts */}
            {customTexts.length > 0 && (
              <div className="space-y-1 pt-1">
                <Label className="text-xs text-muted-foreground">Custom Context:</Label>
                {customTexts.map((ctx) => (
                  <div
                    key={ctx.id}
                    className="flex items-start gap-2 p-2 rounded bg-muted/50 text-xs"
                  >
                    <FileText className="h-3 w-3 mt-0.5 shrink-0 text-muted-foreground" />
                    <p className="flex-1 line-clamp-2">{ctx.description}</p>
                    <button
                      onClick={() => handleRemoveContext(ctx.id)}
                      className="shrink-0 hover:text-destructive"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </CollapsibleContent>
      </div>
    </Collapsible>
  );
}

// Helper to format contexts for AI message
export function formatContextsForAI(contexts: ContextItem[]): string {
  const pages = contexts.filter(c => c.type === 'page');
  const texts = contexts.filter(c => c.type === 'text');

  let contextString = '';

  if (pages.length > 0) {
    contextString += `[Context Pages: ${pages.map(p => p.label).join(', ')}] `;
  }

  if (texts.length > 0) {
    contextString += `[Additional Context: ${texts.map(t => t.description).join('; ')}] `;
  }

  return contextString;
}

import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import {
  Brain,
  Sparkles,
  MessageSquare,
  AlertTriangle,
  TrendingUp,
  Target,
  BookOpen,
  ChevronRight,
  ChevronLeft,
  Lightbulb,
  GitBranch,
  Clock,
  Users,
  CheckCircle2,
  XCircle,
  ArrowRight,
  Play,
  FileText,
  Video,
  BarChart3,
  HelpCircle,
  Zap,
  Loader2,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Progress } from '@/components/ui/progress';
import { useProjectContext } from '@/contexts/ProjectContext';
import { aiService } from '@/services/aiService';
import { useTasks, useDependencies } from '@/hooks/useTasks';
import { useLessonsLearned } from '@/hooks/useLessonsLearned';
import { useCalculateCriticalPath } from '@/hooks/useCriticalPath';
import { useResourceLeveling } from '@/hooks/useResourceLeveling';
import { useAutoScheduler } from '@/hooks/useAutoScheduler';
import { useResources } from '@/hooks/useResources';
import { useProjectCalendars } from '@/hooks/useCalendars';

interface PMCoachSidebarProps {
  isOpen: boolean;
  onToggle: () => void;
  currentView?: string;
}

export function PMCoachSidebar({ isOpen, onToggle, currentView = 'gantt' }: PMCoachSidebarProps) {
  const { settings: project } = useProjectContext();
  const projectId = project?.id || null;

  const { data: tasks = [] } = useTasks(projectId);
  const { data: dependencies = [] } = useDependencies(projectId);
  const { data: lessons = [] } = useLessonsLearned(projectId);
  const { data: resources = [] } = useResources(projectId);
  const { data: calendars = [] } = useProjectCalendars(projectId);

  const calculateCriticalPath = useCalculateCriticalPath();
  const { levelResources, isLeveling } = useResourceLeveling(projectId);
  const { scheduleProject, applySchedule, isApplying } = useAutoScheduler();

  const [activeTab, setActiveTab] = useState<'insights' | 'patterns' | 'learning'>('insights');
  const [isAsking, setIsAsking] = useState(false);
  const [chatHistory, setChatHistory] = useState<{ role: string, content: string }[]>([]);

  const projectCalendar = useMemo(() => calendars.find(c => c.is_default) || null, [calendars]);

  // Derived Insights
  const criticalTasks = useMemo(() => tasks.filter(t => t.is_critical), [tasks]);

  const slippageRisk = useMemo(() => {
    const laggingTasks = tasks.filter(t => t.total_slack && t.total_slack < 0);
    if (laggingTasks.length > 5) return 'high';
    if (laggingTasks.length > 0) return 'medium';
    return 'low';
  }, [tasks]);

  const bottlenecks = useMemo(() => {
    const successorCounts = new Map<string, number>();
    dependencies.forEach(d => {
      successorCounts.set(d.predecessor_id, (successorCounts.get(d.predecessor_id) || 0) + 1);
    });

    return Array.from(successorCounts.entries())
      .filter(([_, count]) => count >= 3)
      .map(([id, _]) => tasks.find(t => t.id === id)?.name || 'Unknown task')
      .filter(name => name !== 'Unknown task');
  }, [dependencies, tasks]);

  const negativeFloatItems = useMemo(() => {
    return tasks
      .filter(t => t.total_slack && t.total_slack < 0)
      .map(t => ({
        taskId: t.id,
        taskName: t.name,
        floatDays: Math.abs(t.total_slack || 0),
        cause: 'Dependency lag or resource constraint',
      }));
  }, [tasks]);

  const constraintViolations = useMemo(() => {
    return tasks
      .filter(t => {
        if (!t.constraint_type || !t.constraint_date) return false;
        const constraintDate = new Date(t.constraint_date);
        const startDate = new Date(t.start_date);

        if (t.constraint_type === 'MSO' && startDate.getTime() !== constraintDate.getTime()) return true;
        if (t.constraint_type === 'SNET' && startDate < constraintDate) return true;
        return false;
      })
      .map(t => ({
        constraintId: t.id,
        severity: 'warning' as 'warning' | 'critical',
        description: `Constraint violation for "${t.name}": Expected ${t.constraint_type} ${t.constraint_date}`,
        suggestedResolution: 'Run auto-scheduler to re-align dates.',
      }));
  }, [tasks]);

  const handleRecalculateCP = () => {
    if (projectId) calculateCriticalPath.mutate(projectId);
  };

  const handleLevelResources = () => {
    if (projectId && tasks.length > 0) {
      levelResources({
        tasks,
        assignments: [], // Needs proper assignment data if available
        resources,
      });
    }
  };

  const handleOptimizeSchedule = async () => {
    if (projectId && tasks.length > 0) {
      const results = await scheduleProject(
        tasks,
        dependencies,
        projectCalendar,
        [], // Exceptions
        projectId
      );
      if (results.length > 0) {
        applySchedule({ results, projectId });
      }
    }
  };

  const handleAskCoach = async (query?: string) => {
    const message = query || "Tell me how the project is doing given the current view.";
    if (!projectId) return;

    setIsAsking(true);
    toast.info('AI PM Coach is thinking...');

    // Add user message to history
    const userMsg = { role: 'user', content: message };
    const updatedHistory = [...chatHistory, userMsg];
    setChatHistory(updatedHistory);

    const { data, error } = await aiService.chat(projectId, message, chatHistory);
    setIsAsking(false);

    if (error) {
      toast.error('Coach failed: ' + error);
    } else {
      // Add assistant message to history
      setChatHistory([...updatedHistory, { role: 'assistant', content: data?.reply || data || 'No response from coach' }]);
      toast.success('Coach responded');
    }
  };

  const getLevelIcon = (type: string) => {
    switch (type) {
      case 'video':
        return <Video className="h-4 w-4" />;
      case 'article':
        return <FileText className="h-4 w-4" />;
      case 'interactive':
        return <Play className="h-4 w-4" />;
      case 'quiz':
        return <HelpCircle className="h-4 w-4" />;
      default:
        return <BookOpen className="h-4 w-4" />;
    }
  };

  return (
    <>
      {/* Toggle Button */}
      <motion.button
        onClick={onToggle}
        className={cn(
          'fixed right-0 top-1/2 -translate-y-1/2 z-50',
          'flex items-center gap-1 px-2 py-3 rounded-l-lg',
          'bg-primary text-primary-foreground shadow-lg',
          'hover:bg-primary/90 transition-colors',
          isOpen && 'hidden'
        )}
      >
        <Brain className="h-5 w-5" />
        <ChevronLeft className="h-4 w-4" />
      </motion.button>

      {/* Sidebar */}
      <AnimatePresence>
        {isOpen && (
          <motion.aside
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="fixed right-0 top-0 h-full w-96 bg-background border-l shadow-xl z-40 flex flex-col"
          >
            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b">
              <div className="flex items-center gap-2">
                <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center">
