              </div>
            </div>

            {/* Tabs */}
            <div className="flex border-b">
              {[
                { id: 'insights', icon: Lightbulb, label: 'Insights' },
                { id: 'patterns', icon: TrendingUp, label: 'Patterns' },
                { id: 'learning', icon: BookOpen, label: 'Learning' },
