                            slippageRisk === 'high' ? 'destructive' :
                              slippageRisk === 'medium' ? 'warning' : 'success'
                          }>
                            {slippageRisk}
                          </Badge>
                        </div>
                        <div className="text-sm">
                          <span className="font-medium">{criticalTasks.length}</span>
