                                <p className="font-medium">{task.name}</p>
                                <p className="text-muted-foreground mt-1">Due: {task.end_date}</p>
                              </div>
                            ))}
                          </div>
                        )}
                      </CardContent>
                    </Card>

                    {/* Dependency Issues */}
                    <Card className="border-warning/30">
