                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  </>
                )}
              </div>
            </ScrollArea>

            {/* Footer */}
            <div className="p-4 border-t bg-muted/20">
              <Button
                className="w-full gap-2"
                size="sm"
                onClick={() => handleAskCoach()}
