                      </div>
                    </div>

                    {!formData.use_same_credentials && (
                      <div className="grid gap-4 grid-cols-2">
                        <div className="space-y-2">
                          <Label htmlFor="smtpUsername">Username</Label>
                          <Input
                            id="smtpUsername"
                            value={formData.smtp_username}
                            onChange={(e) => setFormData((prev) => ({ ...prev, smtp_username: e.target.value }))}
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="smtpPassword">Password</Label>
                          <Input
                            id="smtpPassword"
                            type={showPasswords ? 'text' : 'password'}
                            value={formData.smtp_password}
                            onChange={(e) => setFormData((prev) => ({ ...prev, smtp_password: e.target.value }))}
                          />
                        </div>
                      </div>
                    )}
                  </TabsContent>
                </Tabs>

                {/* Test Result */}
                <AnimatePresence>
                  {testResult && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      exit={{ opacity: 0, height: 0 }}
                    >
                      <div
                        className={cn(
                          'flex items-center gap-3 p-4 rounded-lg',
                          testResult.success
                            ? 'bg-success/10 border border-success/30'
                            : 'bg-destructive/10 border border-destructive/30'
                        )}
                      >
                        {testResult.success ? (
                          <>
                            <CheckCircle className="h-5 w-5 text-success" />
                            <span className="font-medium text-success">Connection successful!</span>
                          </>
                        ) : (
                          <>
                            <AlertCircle className="h-5 w-5 text-destructive" />
                            <div>
                              <span className="font-medium text-destructive">Connection failed</span>
                              {testResult.error && (
                                <p className="text-sm text-muted-foreground mt-1">{testResult.error}</p>
                              )}
                            </div>
                          </>
                        )}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </>
            )}
          </div>

          <DialogFooter className="gap-2">
            {formData.provider_type === 'imap' ? (
              <>
                <Button variant="outline" onClick={handleTestConnection} disabled={isTesting || !formData.email_address || !formData.imap_password}>
                  {isTesting ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Testing...
                    </>
                  ) : (
                    <>
                      <Check className="h-4 w-4 mr-2" />
                      Test Connection
                    </>
                  )}
                </Button>
                <Button onClick={handleSave} disabled={isSaving || !formData.email_address || !formData.imap_password}>
                  {isSaving ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    'Add Account'
                  )}
                </Button>
              </>
            ) : (
              <Button
                onClick={handleStartOAuth}
                disabled={isOAuthPending || !formData.oauth_client_id || !formData.oauth_client_secret}
                className="w-full"
              >
                {isOAuthPending ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Connecting...
                  </>
                ) : (
                  <>
                    <ExternalLink className="h-4 w-4 mr-2" />
                    Connect with {formData.provider_type === 'gmail' ? 'Google' : 'Microsoft'}
                  </>
                )}
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove Email Account</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to remove "{selectedAccount?.email_address}"? This will delete all synced emails from this account. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Remove Account
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Card>
  );
}

import React from 'react';
import { cn } from '@/lib/utils';
import {
  FileText,
  FileSpreadsheet,
  FileImage,
  File,
  X,
  Star,
  Download,
  Share2,
  Lock,
  Unlock,
  Trash2,
  Edit2,
  Clock,
  User,
  Folder,
  Upload,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { type Document } from '@/hooks/useDocuments';
import { type DocumentVersion, useDocumentVersions } from '@/hooks/useDocumentVersions';
import { type DocumentShare, useDocumentSharing } from '@/hooks/useDocumentSharing';
import { DocumentApprovalWorkflow } from './DocumentApprovalWorkflow';

interface DocumentDetailsPanelProps {
  document: Document | null;
  folderPath: string[];
  onClose: () => void;
  onDownload: () => void;
  onShare: () => void;
  onDelete: () => void;
  onRename: () => void;
  onToggleLock: () => void;
  onUploadNewVersion: () => void;
}

const getFileIcon = (type: string) => {
  const className = 'h-12 w-12';
  switch (type) {
    case 'pdf':
      return <FileText className={cn(className, 'text-destructive')} />;
    case 'doc':
      return <FileText className={cn(className, 'text-primary')} />;
    case 'xls':
      return <FileSpreadsheet className={cn(className, 'text-success')} />;
    case 'ppt':
      return <FileText className={cn(className, 'text-warning')} />;
    case 'image':
      return <FileImage className={cn(className, 'text-info')} />;
    default:
      return <File className={cn(className, 'text-muted-foreground')} />;
  }
};

const formatSize = (bytes: number) => {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
};

const formatDate = (dateString: string) => {
  return new Date(dateString).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
};

const getStatusVariant = (status: string): 'success' | 'secondary' | 'warning' | 'outline' => {
  switch (status) {
    case 'approved':
      return 'success';
    case 'draft':
      return 'secondary';
    case 'review':
      return 'warning';
    case 'archived':
      return 'outline';
    default:
      return 'secondary';
  }
};

export function DocumentDetailsPanel({
  document,
  folderPath,
  onClose,
  onDownload,
  onShare,
  onDelete,
  onRename,
  onToggleLock,
  onUploadNewVersion,
}: DocumentDetailsPanelProps) {
  const { versions } = useDocumentVersions(document?.id);
  const { shares } = useDocumentSharing(document?.id);

  if (!document) {
    return (
      <div className="w-80 border-l bg-card flex flex-col items-center justify-center text-center p-6">
        <File className="h-12 w-12 text-muted-foreground mb-3" />
        <p className="text-muted-foreground">Select a document to view details</p>
      </div>
    );
  }

  return (
    <div className="w-80 border-l bg-card flex flex-col">
      {/* Header */}
      <div className="p-4 border-b flex items-start justify-between">
        <div className="flex-1 min-w-0">
          <h3 className="font-semibold text-sm truncate" title={document.name}>
            {document.name}
          </h3>
          <p className="text-xs text-muted-foreground mt-1">
            v{document.version} • {formatSize(document.file_size)}
          </p>
        </div>
        <Button variant="ghost" size="iconSm" onClick={onClose}>
          <X className="h-4 w-4" />
        </Button>
      </div>

      <ScrollArea className="flex-1">
        <div className="p-4 space-y-6">
          {/* Preview */}
          <div className="flex flex-col items-center py-6 bg-muted/30 rounded-lg">
            {getFileIcon(document.file_type)}
            <Badge
              variant={getStatusVariant(document.status)}
              className="mt-3"
            >
              {document.status}
            </Badge>
          </div>

          {/* Quick Actions */}
          <div className="flex items-center justify-center gap-2">
            <Button variant="outline" size="sm" onClick={onDownload}>
              <Download className="h-4 w-4 mr-1" />
              Download
            </Button>
            <Button variant="outline" size="sm" onClick={onShare}>
              <Share2 className="h-4 w-4 mr-1" />
              Share
            </Button>
          </div>

          <Separator />

          {/* Properties */}
          <Accordion type="multiple" defaultValue={['info', 'versions']}>
            <AccordionItem value="info">
              <AccordionTrigger className="text-sm">
                Properties
              </AccordionTrigger>
              <AccordionContent>
                <dl className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <dt className="text-muted-foreground">Type</dt>
                    <dd className="uppercase">{document.file_type}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-muted-foreground">Size</dt>
                    <dd>{formatSize(document.file_size)}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-muted-foreground">Version</dt>
                    <dd>{document.version}</dd>
                  </div>
                  <Separator className="my-2" />
                  <div className="flex justify-between items-start">
                    <dt className="text-muted-foreground">Location</dt>
                    <dd className="text-right flex items-center gap-1">
                      <Folder className="h-3 w-3" />
                      {folderPath.length > 0 ? folderPath.join(' / ') : 'Root'}
                    </dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-muted-foreground">Created</dt>
                    <dd>{formatDate(document.created_at)}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-muted-foreground">Modified</dt>
                    <dd>{formatDate(document.updated_at)}</dd>
                  </div>
                  <div className="flex justify-between items-start">
                    <dt className="text-muted-foreground">Uploaded by</dt>
                    <dd className="flex items-center gap-1">
                      <User className="h-3 w-3" />
                      {document.uploaded_by_name || 'Unknown'}
