                Approval Workflow
              </AccordionTrigger>
              <AccordionContent>
                <DocumentApprovalWorkflow
                  documentId={document.id}
                  documentName={document.name}
                  currentStatus={document.status === 'review' ? 'in-review' : document.status as any}
