interface SidebarProps {
  activeItem: string;
  onItemClick: (id: string) => void;
  className?: string;
}

export function Sidebar({ activeItem, onItemClick, className }: SidebarProps) {
  const [collapsed, setCollapsed] = useState(true); // Collapsed by default
  const { isModuleVisible } = useProjectContext();

  // Find which group contains the active item
  const findParentGroup = useMemo(() => {
    const allGroups = [...navItems, ...adminItems];
    for (const group of allGroups) {
      if (group.children?.some(child => child.id === activeItem)) {
        return group.id;
      }
    }
    return null;
  }, [activeItem]);

  // Only expand the group containing the active page
  const [expandedGroups, setExpandedGroups] = useState<string[]>(() =>
    findParentGroup ? [findParentGroup] : []
  );

  // Update expanded group when active item changes
  useEffect(() => {
    if (findParentGroup && !expandedGroups.includes(findParentGroup)) {
      setExpandedGroups([findParentGroup]);
    }
  }, [findParentGroup]);

  const toggleGroup = (id: string) => {
    setExpandedGroups((prev) =>
      prev.includes(id) ? prev.filter((g) => g !== id) : [...prev, id]
    );
  };

  const isItemVisible = (item: NavItem): boolean => {
    if (item.alwaysShow) return true;
    if (!item.moduleKey) return true;
    return isModuleVisible(item.moduleKey);
  };

  const filterVisibleChildren = (children?: NavItem[]): NavItem[] | undefined => {
    if (!children) return undefined;
    return children.filter(isItemVisible);
  };

  const renderNavItem = (item: NavItem, depth = 0) => {
    if (!isItemVisible(item)) return null;

    const visibleChildren = filterVisibleChildren(item.children);
    const hasVisibleChildren = visibleChildren && visibleChildren.length > 0;

    // If this is a group and no children are visible, hide the group
    if (item.children && !hasVisibleChildren) return null;

    const isActive = activeItem === item.id;
    const isExpanded = expandedGroups.includes(item.id);
    const Icon = item.icon;

    const itemContent = (
      <motion.button
        whileHover={{ x: 2 }}
        whileTap={{ scale: 0.98 }}
        onClick={() => {
          if (hasVisibleChildren) {
            toggleGroup(item.id);
          } else {
            onItemClick(item.id);
          }
        }}
        className={cn(
          'flex items-center w-full gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all duration-150',
          'text-sidebar-foreground hover:text-sidebar-accent-foreground',
          isActive
            ? 'bg-sidebar-accent text-sidebar-accent-foreground'
            : 'hover:bg-sidebar-accent/50',
          depth > 0 && 'ml-4 pl-6 border-l border-sidebar-border'
        )}
      >
        <Icon className={cn('h-4 w-4 shrink-0', isActive && 'text-primary')} />
        {!collapsed && (
          <>
            <span className="flex-1 text-left truncate">{item.label}</span>
            {item.badge && (
              <span className="flex h-5 min-w-5 items-center justify-center rounded-full bg-primary/20 px-1.5 text-xs font-medium text-primary">
                {item.badge}
              </span>
            )}
            {hasVisibleChildren && (
              <ChevronRight
                className={cn(
                  'h-4 w-4 transition-transform duration-200',
                  isExpanded && 'rotate-90'
                )}
              />
            )}
          </>
        )}
      </motion.button>
    );

    if (collapsed) {
      return (
        <Tooltip key={item.id} delayDuration={0}>
          <TooltipTrigger asChild>{itemContent}</TooltipTrigger>
          <TooltipContent side="right" className="flex items-center gap-2">
            {item.label}
            {item.badge && (
              <span className="rounded-full bg-primary/20 px-1.5 py-0.5 text-xs text-primary">
                {item.badge}
              </span>
            )}
          </TooltipContent>
        </Tooltip>
      );
    }

    return (
      <div key={item.id}>
        {itemContent}
        {hasVisibleChildren && isExpanded && !collapsed && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="mt-1 space-y-1"
          >
            {visibleChildren!.map((child) => renderNavItem(child, depth + 1))}
          </motion.div>
        )}
      </div>
    );
  };

  return (
    <motion.aside
      initial={false}
      animate={{ width: collapsed ? 64 : 256 }}
      transition={{ duration: 0.2, ease: 'easeInOut' }}
      className={cn(
        'flex flex-col h-full bg-sidebar border-r border-sidebar-border',
        className
      )}
    >
      {/* Logo */}
      <div className="flex h-16 items-center justify-between px-4 border-b border-sidebar-border">
        {!collapsed && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex items-center gap-2"
          >
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
              <Sparkles className="h-4 w-4 text-primary-foreground" />
            </div>
            <span className="font-semibold text-foreground">Kiroxys</span>
          </motion.div>
        )}
        <Button
          variant="ghost"
          size="iconSm"
          onClick={() => setCollapsed(!collapsed)}
          className="shrink-0"
        >
          {collapsed ? (
            <ChevronRight className="h-4 w-4" />
          ) : (
            <ChevronLeft className="h-4 w-4" />
          )}
        </Button>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto p-3 space-y-1">
        {navItems.map((item) => renderNavItem(item))}

        {/* Separator */}
        <div className="my-4 border-t border-sidebar-border" />

        {/* Admin Items */}
        {adminItems.map((item) => renderNavItem(item))}
      </nav>
    </motion.aside>
  );
}

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { format } from 'date-fns';
import { CalendarIcon, Plus, X, Users, Clock, Video, MapPin, Repeat, Target, CheckCircle2 } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn } from '@/lib/utils';
import type { CreateMeetingInput, CreateAgendaItemInput, CreateParticipantInput } from '@/hooks/useMeetings';

const meetingSchema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
  date: z.date({ required_error: 'Date is required' }),
  startTime: z.string().min(1, 'Start time is required'),
  endTime: z.string().optional(),
  meetingType: z.enum(['online', 'in-person', 'offline']),
  sourceType: z.enum(['zoom', 'teams', 'meet', 'audio', 'manual']),
  meetingLink: z.string().optional(),
  location: z.string().optional(),
  purposeType: z.string().optional(),
  purposeDescription: z.string().optional(),
  recurringSchedule: z.enum(['none', 'daily', 'weekly', 'bi-weekly', 'monthly']).optional(),
  recurringEndDate: z.date().optional(),
});

type MeetingFormData = z.infer<typeof meetingSchema>;

interface ParticipantInput {
  name: string;
  email: string;
  role: string;
}

interface AgendaItemInput {
  title: string;
  duration: number;
  presenterName: string;
}

interface MeetingCreationDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  projectId?: string | null;
  onCreateMeeting: (
    meeting: CreateMeetingInput,
    participants: CreateParticipantInput[],
    agendaItems: CreateAgendaItemInput[]
  ) => Promise<void>;
}

export function MeetingCreationDialog({
  open,
  onOpenChange,
  projectId,
  onCreateMeeting,
}: MeetingCreationDialogProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [participants, setParticipants] = useState<ParticipantInput[]>([]);
  const [agendaItems, setAgendaItems] = useState<AgendaItemInput[]>([]);
  const [expectedOutcomes, setExpectedOutcomes] = useState<string[]>([]);
  const [successCriteria, setSuccessCriteria] = useState<string[]>([]);
  const [newParticipant, setNewParticipant] = useState({ name: '', email: '', role: 'contributor' });
  const [newAgendaItem, setNewAgendaItem] = useState({ title: '', duration: 15, presenterName: '' });
  const [newOutcome, setNewOutcome] = useState('');
  const [newCriterion, setNewCriterion] = useState('');

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    reset,
    formState: { errors },
  } = useForm<MeetingFormData>({
    resolver: zodResolver(meetingSchema),
    defaultValues: {
      meetingType: 'online',
      sourceType: 'teams',
      purposeType: 'status-update',
      recurringSchedule: 'none',
    },
  });

  const selectedDate = watch('date');
  const meetingType = watch('meetingType');
  const recurringSchedule = watch('recurringSchedule');
  const recurringEndDate = watch('recurringEndDate');

  const addParticipant = () => {
    if (newParticipant.name.trim()) {
      setParticipants([...participants, { ...newParticipant }]);
      setNewParticipant({ name: '', email: '', role: 'contributor' });
    }
  };

  const removeParticipant = (index: number) => {
    setParticipants(participants.filter((_, i) => i !== index));
  };

  const addAgendaItem = () => {
    if (newAgendaItem.title.trim()) {
      setAgendaItems([...agendaItems, { ...newAgendaItem }]);
      setNewAgendaItem({ title: '', duration: 15, presenterName: '' });
    }
  };

  const removeAgendaItem = (index: number) => {
    setAgendaItems(agendaItems.filter((_, i) => i !== index));
  };

  const addOutcome = () => {
    if (newOutcome.trim()) {
      setExpectedOutcomes([...expectedOutcomes, newOutcome.trim()]);
      setNewOutcome('');
    }
  };

  const removeOutcome = (index: number) => {
    setExpectedOutcomes(expectedOutcomes.filter((_, i) => i !== index));
  };

  const addCriterion = () => {
    if (newCriterion.trim()) {
      setSuccessCriteria([...successCriteria, newCriterion.trim()]);
      setNewCriterion('');
    }
  };

  const removeCriterion = (index: number) => {
    setSuccessCriteria(successCriteria.filter((_, i) => i !== index));
  };

  const onSubmit = async (data: MeetingFormData) => {
    setIsSubmitting(true);
    try {
      const meetingInput: CreateMeetingInput = {
        project_id: projectId || undefined,
        title: data.title,
        description: data.description,
        date: format(data.date, 'yyyy-MM-dd'),
        start_time: data.startTime,
        end_time: data.endTime,
        meeting_type: data.meetingType,
        source_type: data.sourceType,
        meeting_link: data.meetingLink,
        location: data.location,
        purpose_type: data.purposeType,
        purpose_description: data.purposeDescription,
        expected_outcomes: expectedOutcomes.length > 0 ? expectedOutcomes : undefined,
        success_criteria: successCriteria.length > 0 ? successCriteria : undefined,
        recurring_schedule: data.recurringSchedule || 'none',
        recurring_end_date: data.recurringEndDate ? format(data.recurringEndDate, 'yyyy-MM-dd') : undefined,
        status: 'scheduled',
      };

      const participantInputs: CreateParticipantInput[] = participants.map((p) => ({
        meeting_id: '', // Will be set after meeting creation
        name: p.name,
        email: p.email || undefined,
        role: p.role,
      }));

      const agendaInputs: CreateAgendaItemInput[] = agendaItems.map((a, index) => ({
        meeting_id: '', // Will be set after meeting creation
        title: a.title,
        duration_minutes: a.duration,
        presenter_name: a.presenterName || undefined,
        sort_order: index,
      }));

      await onCreateMeeting(meetingInput, participantInputs, agendaInputs);

      // Reset form
      reset();
      setParticipants([]);
      setAgendaItems([]);
      setExpectedOutcomes([]);
      setSuccessCriteria([]);
      onOpenChange(false);
    } finally {
      setIsSubmitting(false);
    }
  };

  const purposeTypes = [
    { value: 'status-update', label: 'Status Update' },
    { value: 'decision', label: 'Decision Making' },
    { value: 'review', label: 'Review' },
    { value: 'planning', label: 'Planning' },
    { value: 'brainstorming', label: 'Brainstorming' },
    { value: 'kickoff', label: 'Kickoff' },
    { value: 'retrospective', label: 'Retrospective' },
    { value: 'other', label: 'Other' },
  ];

  const roleOptions = [
    { value: 'decision-maker', label: 'Decision Maker' },
    { value: 'contributor', label: 'Contributor' },
    { value: 'observer', label: 'Observer' },
    { value: 'approver', label: 'Approver' },
    { value: 'subject-matter-expert', label: 'Subject Matter Expert' },
  ];

  const recurringOptions = [
    { value: 'none', label: 'Does not repeat' },
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'bi-weekly', label: 'Bi-weekly' },
    { value: 'monthly', label: 'Monthly' },
  ];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle>Create New Meeting</DialogTitle>
          <DialogDescription>
            Schedule a new meeting with participants and agenda items
          </DialogDescription>
        </DialogHeader>

        <ScrollArea className="flex-1 pr-4">
          <form id="meeting-form" onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {/* Basic Info */}
            <div className="space-y-4">
              <div>
                <Label htmlFor="title">Meeting Title *</Label>
                <Input
                  id="title"
                  {...register('title')}
                  placeholder="e.g., Sprint Planning Meeting"
                  className={cn(errors.title && 'border-destructive')}
                />
                {errors.title && (
                  <p className="text-xs text-destructive mt-1">{errors.title.message}</p>
                )}
              </div>

              <div>
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  {...register('description')}
                  placeholder="Meeting purpose and context..."
                  rows={2}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
