import React, { useMemo } from 'react';
import { format, isSameDay, startOfMonth, endOfMonth, startOfWeek, endOfWeek, eachDayOfInterval, isToday, isSameMonth } from 'date-fns';
import { cn } from '@/lib/utils';
import { ChevronLeft, ChevronRight, CalendarDays } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';

interface MeetingDate {
  date: Date;
  count: number;
}

interface MiniCalendarSidebarProps {
  selectedDate: Date | null;
  onSelectDate: (date: Date) => void;
  meetingDates: MeetingDate[];
  currentMonth: Date;
  onMonthChange: (date: Date) => void;
}

export function MiniCalendarSidebar({
  selectedDate,
  onSelectDate,
  meetingDates,
  currentMonth,
  onMonthChange,
}: MiniCalendarSidebarProps) {
  // Generate calendar days for the current month view
  const calendarDays = useMemo(() => {
    const monthStart = startOfMonth(currentMonth);
    const monthEnd = endOfMonth(currentMonth);
    const calendarStart = startOfWeek(monthStart);
    const calendarEnd = endOfWeek(monthEnd);
    return eachDayOfInterval({ start: calendarStart, end: calendarEnd });
  }, [currentMonth]);

  // Create a map for quick lookup of meeting counts by date
  const meetingCountByDate = useMemo(() => {
    const map = new Map<string, number>();
    meetingDates.forEach((md) => {
      const key = format(md.date, 'yyyy-MM-dd');
      map.set(key, md.count);
    });
    return map;
  }, [meetingDates]);

  const getMeetingCount = (date: Date) => {
    const key = format(date, 'yyyy-MM-dd');
    return meetingCountByDate.get(key) || 0;
  };

  const handlePrevMonth = () => {
    const newDate = new Date(currentMonth);
    newDate.setMonth(newDate.getMonth() - 1);
    onMonthChange(newDate);
  };

  const handleNextMonth = () => {
    const newDate = new Date(currentMonth);
    newDate.setMonth(newDate.getMonth() + 1);
    onMonthChange(newDate);
  };

  const weekDays = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

  // Get upcoming meetings for the sidebar list
  const upcomingDates = useMemo(() => {
    const today = new Date();
    return meetingDates
      .filter((md) => md.date >= today)
      .sort((a, b) => a.date.getTime() - b.date.getTime())
      .slice(0, 5);
  }, [meetingDates]);

  return (
    <div className="w-64 border-l bg-muted/10 flex flex-col h-full">
      {/* Mini Calendar Header */}
      <div className="p-4 border-b">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-semibold flex items-center gap-2">
            <CalendarDays className="h-4 w-4" />
            Quick Navigation
          </h3>
        </div>

        {/* Month Navigation */}
        <div className="flex items-center justify-between mb-3">
          <Button variant="ghost" size="icon" className="h-7 w-7" onClick={handlePrevMonth}>
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <span className="text-sm font-medium">{format(currentMonth, 'MMMM yyyy')}</span>
          <Button variant="ghost" size="icon" className="h-7 w-7" onClick={handleNextMonth}>
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>

        {/* Weekday Headers */}
        <div className="grid grid-cols-7 gap-1 mb-1">
          {weekDays.map((day, i) => (
            <div key={i} className="text-center text-xs text-muted-foreground font-medium">
              {day}
            </div>
          ))}
        </div>

        {/* Calendar Grid */}
        <div className="grid grid-cols-7 gap-1">
          {calendarDays.map((date) => {
            const isCurrentMonth = isSameMonth(date, currentMonth);
            const isSelected = selectedDate && isSameDay(date, selectedDate);
            const isTodayDate = isToday(date);
            const meetingCount = getMeetingCount(date);

            return (
              <button
                key={date.toISOString()}
                onClick={() => onSelectDate(date)}
                className={cn(
                  'relative h-8 w-8 text-xs rounded-full transition-colors flex items-center justify-center',
                  !isCurrentMonth && 'text-muted-foreground/50',
                  isCurrentMonth && 'hover:bg-muted',
                  isTodayDate && 'bg-primary text-primary-foreground hover:bg-primary/90',
                  isSelected && !isTodayDate && 'bg-primary/20 ring-1 ring-primary',
                  meetingCount > 0 && !isTodayDate && !isSelected && 'font-semibold'
                )}
              >
                {format(date, 'd')}
                {meetingCount > 0 && (
                  <span
                    className={cn(
                      'absolute bottom-0.5 left-1/2 -translate-x-1/2 h-1 w-1 rounded-full',
                      isTodayDate ? 'bg-primary-foreground' : 'bg-primary'
                    )}
                  />
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* Quick Actions */}
      <div className="p-4 border-b">
        <Button
          variant="outline"
          size="sm"
          className="w-full mb-2"
          onClick={() => onSelectDate(new Date())}
        >
          Today
        </Button>
        <Button
          variant="ghost"
          size="sm"
          className="w-full"
          onClick={() => onSelectDate(null as any)} // Clear filter
        >
          Show All
        </Button>
      </div>

      {/* Upcoming Meetings */}
      <div className="flex-1 overflow-hidden flex flex-col">
        <div className="px-4 py-2 border-b">
          <span className="text-xs font-medium text-muted-foreground uppercase">
            Upcoming Meetings
          </span>
        </div>
        <ScrollArea className="flex-1">
          <div className="p-2 space-y-1">
            {upcomingDates.length === 0 ? (
              <p className="text-xs text-muted-foreground text-center py-4">
                No upcoming meetings
              </p>
            ) : (
              upcomingDates.map((md, i) => (
                <button
                  key={i}
                  onClick={() => onSelectDate(md.date)}
                  className={cn(
                    'w-full text-left p-2 rounded-lg hover:bg-muted/50 transition-colors',
                    selectedDate && isSameDay(md.date, selectedDate) && 'bg-primary/10'
                  )}
                >
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium">
                      {isToday(md.date) ? 'Today' : format(md.date, 'EEE, MMM d')}
                    </span>
                    <Badge variant="secondary" className="text-xs">
                      {md.count}
                    </Badge>
                  </div>
                </button>
              ))
            )}
          </div>
        </ScrollArea>
      </div>
    </div>
  );
}

import React, { useState, useCallback } from 'react';
import { Upload, FileText, Sparkles, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

interface TranscriptUploadDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  meetingId: string;
  meetingTitle: string;
  onUploadTranscript: (transcript: string) => Promise<void>;
  onProcessWithAI: () => Promise<void>;
}

type UploadStatus = 'idle' | 'uploading' | 'processing' | 'complete' | 'error';

export function TranscriptUploadDialog({
  open,
  onOpenChange,
  meetingId,
  meetingTitle,
  onUploadTranscript,
  onProcessWithAI,
}: TranscriptUploadDialogProps) {
  const [transcript, setTranscript] = useState('');
  const [status, setStatus] = useState<UploadStatus>('idle');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [dragActive, setDragActive] = useState(false);

  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  const handleFile = async (file: File) => {
    // Check file type
    const validTypes = ['text/plain', 'text/vtt', 'text/srt', 'application/json'];
    if (!validTypes.includes(file.type) && !file.name.match(/\.(txt|vtt|srt|json)$/)) {
      setError('Please upload a text file (.txt, .vtt, .srt, or .json)');
      return;
    }

    setStatus('uploading');
    setProgress(0);
    setError(null);

    try {
      const reader = new FileReader();
      reader.onprogress = (e) => {
        if (e.lengthComputable) {
          setProgress((e.loaded / e.total) * 50);
        }
      };
      reader.onload = (e) => {
        const content = e.target?.result as string;
        // Parse VTT/SRT if needed
        const cleanedTranscript = parseTranscript(content, file.name);
        setTranscript(cleanedTranscript);
        setProgress(100);
        setStatus('idle');
      };
      reader.onerror = () => {
        setError('Failed to read file');
        setStatus('error');
      };
      reader.readAsText(file);
    } catch (err) {
      setError('Failed to process file');
      setStatus('error');
    }
  };

  const parseTranscript = (content: string, filename: string): string => {
    // Handle VTT format
    if (filename.endsWith('.vtt')) {
      return content
        .split('\n')
        .filter((line) => !line.match(/^WEBVTT/) && !line.match(/^\d{2}:\d{2}/) && line.trim())
        .join('\n');
    }

    // Handle SRT format
    if (filename.endsWith('.srt')) {
      return content
        .split('\n')
        .filter((line) => !line.match(/^\d+$/) && !line.match(/^\d{2}:\d{2}/) && line.trim())
        .join('\n');
    }

    // Handle JSON (common for Teams/Zoom exports)
    if (filename.endsWith('.json')) {
      try {
        const data = JSON.parse(content);
        if (Array.isArray(data)) {
          return data.map((item) => `${item.speaker || ''}: ${item.text || item.content || ''}`).join('\n');
        }
        return content;
      } catch {
        return content;
      }
    }

    return content;
  };

  const handleUploadAndProcess = async () => {
    if (!transcript.trim()) {
      setError('Please provide a transcript');
      return;
    }

    setStatus('uploading');
    setProgress(0);
    setError(null);

    try {
      // Simulate progress for upload
      setProgress(30);
      await onUploadTranscript(transcript);
      setProgress(50);

      setStatus('processing');
      // Process with AI
      await onProcessWithAI();
      setProgress(100);

      setStatus('complete');

      // Close dialog after short delay
      setTimeout(() => {
        onOpenChange(false);
        setTranscript('');
        setStatus('idle');
        setProgress(0);
      }, 1500);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to process transcript');
      setStatus('error');
    }
  };

  const getStatusMessage = () => {
    switch (status) {
      case 'uploading':
        return 'Uploading transcript...';
      case 'processing':
        return 'AI is extracting insights...';
      case 'complete':
        return 'Processing complete!';
      case 'error':
        return error || 'An error occurred';
      default:
        return null;
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5 text-primary" />
            Upload Transcript
          </DialogTitle>
          <DialogDescription>
            Upload or paste the transcript for "{meetingTitle}" to extract AI insights
          </DialogDescription>
        </DialogHeader>

        <Tabs defaultValue="paste" className="mt-4">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="paste">Paste Text</TabsTrigger>
            <TabsTrigger value="upload">Upload File</TabsTrigger>
          </TabsList>

          <TabsContent value="paste" className="mt-4">
            <div className="space-y-2">
              <Label htmlFor="transcript">Meeting Transcript</Label>
              <Textarea
                id="transcript"
                placeholder="Paste your meeting transcript here...

Example:
John: Let's discuss the project timeline.
Sarah: I think we should push the deadline by two weeks.
John: Agreed. Let's also add more resources to the team.
Sarah: I'll create an action item for that."
                value={transcript}
                onChange={(e) => setTranscript(e.target.value)}
                rows={12}
                className="font-mono text-sm"
              />
              <p className="text-xs text-muted-foreground">
                Include speaker names for better AI extraction (e.g., "Speaker: text")
              </p>
            </div>
          </TabsContent>

          <TabsContent value="upload" className="mt-4">
            <div
              className={cn(
                'border-2 border-dashed rounded-lg p-8 text-center transition-colors',
                dragActive ? 'border-primary bg-primary/5' : 'border-muted-foreground/25',
                status === 'uploading' && 'pointer-events-none opacity-50'
              )}
              onDragEnter={handleDrag}
              onDragLeave={handleDrag}
              onDragOver={handleDrag}
              onDrop={handleDrop}
            >
              <Upload className="h-10 w-10 mx-auto text-muted-foreground mb-4" />
              <p className="font-medium mb-1">
                Drag and drop your transcript file here
              </p>
              <p className="text-sm text-muted-foreground mb-4">
                Supports .txt, .vtt, .srt, and .json files
              </p>
              <input
                type="file"
                id="file-upload"
                className="hidden"
                accept=".txt,.vtt,.srt,.json"
                onChange={handleFileInput}
              />
              <Button variant="outline" asChild>
                <label htmlFor="file-upload" className="cursor-pointer">
                  Choose File
                </label>
              </Button>
            </div>

            {transcript && (
              <div className="mt-4 p-3 rounded-lg bg-muted/50">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium">Transcript loaded</span>
                  <Badge variant="success">
                    {transcript.split('\n').length} lines
                  </Badge>
                </div>
                <p className="text-xs text-muted-foreground line-clamp-2">
                  {transcript.substring(0, 200)}...
                </p>
              </div>
            )}
          </TabsContent>
        </Tabs>

        {/* Status Display */}
        {status !== 'idle' && (
          <div className="mt-4 p-4 rounded-lg bg-muted/50 space-y-3">
            <div className="flex items-center gap-2">
              {status === 'uploading' && <Loader2 className="h-4 w-4 animate-spin text-primary" />}
              {status === 'processing' && <Sparkles className="h-4 w-4 text-primary animate-pulse" />}
              {status === 'complete' && <CheckCircle2 className="h-4 w-4 text-success" />}
              {status === 'error' && <AlertCircle className="h-4 w-4 text-destructive" />}
              <span className={cn(
                'text-sm font-medium',
                status === 'error' && 'text-destructive',
                status === 'complete' && 'text-success'
              )}>
                {getStatusMessage()}
              </span>
            </div>
            {(status === 'uploading' || status === 'processing') && (
              <Progress value={progress} className="h-2" />
            )}
          </div>
        )}

        {/* AI Extraction Preview */}
        {transcript && status === 'idle' && (
          <div className="mt-4 p-4 rounded-lg border border-dashed">
            <div className="flex items-center gap-2 mb-2">
              <Sparkles className="h-4 w-4 text-primary" />
              <span className="text-sm font-medium">AI will extract:</span>
            </div>
            <div className="flex flex-wrap gap-2">
              <Badge variant="secondary">Decisions</Badge>
              <Badge variant="secondary">Action Items</Badge>
              <Badge variant="secondary">Risks</Badge>
              <Badge variant="secondary">Key Topics</Badge>
              <Badge variant="secondary">Sentiment Analysis</Badge>
              <Badge variant="secondary">Scope Changes</Badge>
            </div>
          </div>
        )}

        <DialogFooter className="mt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button
            onClick={handleUploadAndProcess}
            disabled={!transcript.trim() || status === 'uploading' || status === 'processing'}
          >
            {status === 'uploading' || status === 'processing' ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Processing...
              </>
            ) : (
              <>
                <Sparkles className="h-4 w-4 mr-2" />
                Process with AI
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Sparkles,
  Save,
  MoreHorizontal,
  Share2,
  Clock,
  Tag,
  X,
  Plus,
} from 'lucide-react';
import type { NotebookPage } from '@/hooks/useNotebooks';
import { formatDistanceToNow } from 'date-fns';
import { RichTextEditor } from './RichTextEditor';

interface PageEditorProps {
  page: NotebookPage | null;
  onUpdate: (id: string, updates: Partial<NotebookPage>) => void;
  allPages: { id: string; title: string }[];
  onNavigateToPage?: (pageId: string) => void;
}

export function PageEditor({ page, onUpdate, allPages, onNavigateToPage }: PageEditorProps) {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [newTag, setNewTag] = useState('');
  const [showTagInput, setShowTagInput] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const saveTimeoutRef = useRef<NodeJS.Timeout>();

  // Reset state when page changes
  useEffect(() => {
    if (page) {
      setTitle(page.title);
      setContent(page.content || '');
      setTags(page.tags || []);
      setLastSaved(new Date(page.updated_at));
    }
  }, [page?.id]);

  // Auto-save with debounce
  const saveChanges = useCallback(() => {
    if (!page) return;

    setIsSaving(true);
    onUpdate(page.id, {
      title: title || 'Untitled',
      content,
      tags,
    });

    setTimeout(() => {
      setIsSaving(false);
      setLastSaved(new Date());
    }, 500);
  }, [page, title, content, tags, onUpdate]);

  // Debounced save
  useEffect(() => {
    if (!page) return;

    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
    }

    saveTimeoutRef.current = setTimeout(() => {
      if (title !== page.title || content !== page.content || JSON.stringify(tags) !== JSON.stringify(page.tags)) {
        saveChanges();
      }
    }, 1000);

    return () => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current);
      }
    };
  }, [title, content, tags]);

  const handleAddTag = () => {
    if (newTag && !tags.includes(newTag)) {
      setTags([...tags, newTag]);
      setNewTag('');
    }
    setShowTagInput(false);
  };

  const handleRemoveTag = (tag: string) => {
    setTags(tags.filter(t => t !== tag));
  };

  if (!page) {
    return (
      <div className="flex-1 flex items-center justify-center bg-background">
        <div className="text-center text-muted-foreground">
          <Sparkles className="h-12 w-12 mx-auto mb-4 opacity-50" />
          <h3 className="text-lg font-medium mb-2">Select a page to edit</h3>
          <p className="text-sm">Or create a new page to get started</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col bg-background min-w-0 h-full">
      {/* Top Bar */}
      <div className="flex items-center justify-between p-3 border-b border-border shrink-0">
        <div className="flex items-center gap-2">
          {isSaving ? (
            <span className="text-xs text-muted-foreground flex items-center gap-1">
              <Save className="h-3 w-3 animate-pulse" />
              Saving...
            </span>
          ) : lastSaved && (
            <span className="text-xs text-muted-foreground flex items-center gap-1">
              <Clock className="h-3 w-3" />
              Saved {formatDistanceToNow(lastSaved, { addSuffix: true })}
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" className="gap-2">
            <Sparkles className="h-4 w-4 text-primary" />
            AI Assist
          </Button>
          <Button variant="ghost" size="iconSm">
            <Share2 className="h-4 w-4" />
          </Button>
          <Button variant="ghost" size="iconSm">
            <MoreHorizontal className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Editor Content */}
      <ScrollArea className="flex-1">
        <div className="max-w-4xl mx-auto p-6 space-y-4">
          {/* Title */}
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Untitled"
            className="text-3xl font-bold border-none shadow-none px-0 h-auto focus-visible:ring-0 bg-transparent"
          />

          {/* Tags */}
          <div className="flex items-center gap-2 flex-wrap">
            <Tag className="h-4 w-4 text-muted-foreground" />
            {tags.map(tag => (
              <Badge key={tag} variant="secondary" className="gap-1">
                {tag}
                <button onClick={() => handleRemoveTag(tag)}>
                  <X className="h-3 w-3" />
                </button>
              </Badge>
            ))}
            {showTagInput ? (
              <div className="flex items-center gap-1">
                <Input
                  value={newTag}
                  onChange={(e) => setNewTag(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') handleAddTag();
                    if (e.key === 'Escape') setShowTagInput(false);
                  }}
                  placeholder="Add tag..."
                  className="h-6 w-24 text-xs"
                  autoFocus
                />
                <Button size="iconSm" variant="ghost" className="h-6 w-6" onClick={handleAddTag}>
                  <Plus className="h-3 w-3" />
                </Button>
              </div>
            ) : (
              <Button
                variant="ghost"
                size="sm"
                className="h-6 text-xs text-muted-foreground"
                onClick={() => setShowTagInput(true)}
              >
                <Plus className="h-3 w-3 mr-1" />
                Add tag
              </Button>
            )}
          </div>

          {/* Rich Text Editor */}
          <RichTextEditor
            content={content}
            onChange={setContent}
            placeholder="Start writing... Use the toolbar above to format your text."
          />
        </div>
      </ScrollArea>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from '@/components/ui/context-menu';
import {
  Plus,
  MoreHorizontal,
  Pencil,
  Trash2,
  Table2,
  Save,
  Clock,
  ChevronDown,
  Copy,
  Clipboard,
  Scissors,
  ArrowUp,
  ArrowDown,
  Lock,
} from 'lucide-react';
import type { SpreadsheetSheet, NotebookSpreadsheet } from '@/hooks/useSpreadsheets';
import { useSheets } from '@/hooks/useSpreadsheets';
import { useLinkedSpreadsheet } from '@/hooks/useLinkedSpreadsheet';
import { formatDistanceToNow } from 'date-fns';
import {
  SpreadsheetToolbar,
  FormulaBar,
  getCellRefString,
  getCellDisplayValue,
  indexToColumn,
  ConvertToProjectPlanDialog,
  SyncStatusIndicator,
} from './spreadsheet';
import type { CellFormat, Selection, CellData } from './spreadsheet/types';
import { isInSelection, getSelectionRange, createEmptySelection } from './spreadsheet/types';

interface SpreadsheetEditorProps {
  spreadsheet: NotebookSpreadsheet | null;
}

interface CellFormats {
  [key: string]: CellFormat; // key is "row-col"
}

interface HistoryEntry {
  data: any[][];
  formats: CellFormats;
}

export function SpreadsheetEditor({ spreadsheet }: SpreadsheetEditorProps) {
  const { sheets, loading, createSheet, updateSheet, deleteSheet } = useSheets(spreadsheet?.id || null);
  const { 
    linkInfo, 
    isLinked, 
    isSyncing, 
    convertToProjectPlan, 
    syncToProjectPlan, 
    syncToSpreadsheet, 
    unlinkFromProjectPlan,
    debouncedSync,
  } = useLinkedSpreadsheet(spreadsheet?.id || null);

  const [activeSheetId, setActiveSheetId] = useState<string | null>(null);
  const [editingSheetName, setEditingSheetName] = useState<string | null>(null);
  const [newSheetName, setNewSheetName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const saveTimeoutRef = useRef<NodeJS.Timeout>();
  const [showConvertDialog, setShowConvertDialog] = useState(false);

  // Selection state
  const [selection, setSelection] = useState<Selection | null>(null);
  const [isSelecting, setIsSelecting] = useState(false);
  const [editingCell, setEditingCell] = useState<{ row: number; col: number } | null>(null);
  const [editValue, setEditValue] = useState('');

  // Cell formats (stored separately from data)
  const [cellFormats, setCellFormats] = useState<CellFormats>({});

  // Local data state for immediate updates
  const [localData, setLocalData] = useState<any[][] | null>(null);

  // History for undo/redo
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Clipboard
  const [clipboard, setClipboard] = useState<{ data: any[][]; formats: CellFormats } | null>(null);
  const [clipboardSelection, setClipboardSelection] = useState<Selection | null>(null);

  // Column widths
  const [columnWidths, setColumnWidths] = useState<Record<number, number>>({});
  const [resizingCol, setResizingCol] = useState<number | null>(null);
  const resizeStartX = useRef<number>(0);
  const resizeStartWidth = useRef<number>(0);

  const gridRef = useRef<HTMLDivElement>(null);
  const DEFAULT_COL_WIDTH = 100;
  const MIN_COL_WIDTH = 40;
  const ROW_HEIGHT = 28;
  const HEADER_HEIGHT = 32;
  const ROW_HEADER_WIDTH = 48;

  // Select first sheet when sheets load
  useEffect(() => {
    if (sheets.length > 0 && !activeSheetId) {
      setActiveSheetId(sheets[0].id);
    }
  }, [sheets, activeSheetId]);

  // Reset when spreadsheet changes
  useEffect(() => {
    setActiveSheetId(null);
    setSelection(null);
    setEditingCell(null);
    setLocalData(null);
    setCellFormats({});
    setHistory([]);
    setHistoryIndex(-1);
  }, [spreadsheet?.id]);

  const activeSheet = sheets.find(s => s.id === activeSheetId);

  // Sync local data with active sheet
  useEffect(() => {
    if (activeSheet) {
      const data = ensureGridSize(activeSheet.data || [], 100, 26);
      setLocalData(data);
      // Initialize history
      setHistory([{ data: JSON.parse(JSON.stringify(data)), formats: {} }]);
      setHistoryIndex(0);
    }
  }, [activeSheet?.id]);

  // Ensure minimum grid size
  const ensureGridSize = (data: any[][], minRows: number, minCols: number): any[][] => {
    const newData = [...data];
    while (newData.length < minRows) {
      newData.push(Array(minCols).fill(''));
    }
    return newData.map(row => {
      const newRow = [...(row || [])];
      while (newRow.length < minCols) {
        newRow.push('');
      }
      return newRow;
    });
  };

  // Save to database with debounce
  const saveData = useCallback((data: any[][]) => {
    if (!activeSheet) return;

    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
    }

    saveTimeoutRef.current = setTimeout(async () => {
      setIsSaving(true);
      await updateSheet(activeSheet.id, { data });
      setIsSaving(false);
      setLastSaved(new Date());
    }, 1000);
  }, [activeSheet, updateSheet]);

  // Push to history
  const pushHistory = useCallback((data: any[][], formats: CellFormats) => {
    setHistory(prev => {
      const newHistory = prev.slice(0, historyIndex + 1);
      newHistory.push({ data: JSON.parse(JSON.stringify(data)), formats: { ...formats } });
      return newHistory.slice(-50); // Keep last 50 states
    });
    setHistoryIndex(prev => Math.min(prev + 1, 49));
  }, [historyIndex]);

  // Update cell value
  const updateCell = useCallback((row: number, col: number, value: string) => {
    if (!localData) return;

    const newData = localData.map((r, ri) => 
      ri === row ? r.map((c, ci) => ci === col ? value : c) : [...r]
    );

    setLocalData(newData);
    pushHistory(newData, cellFormats);
    saveData(newData);
  }, [localData, cellFormats, pushHistory, saveData]);

  // Handle cell editing
  const startEditing = useCallback((row: number, col: number, initialValue?: string) => {
    setEditingCell({ row, col });
    const currentValue = localData?.[row]?.[col] ?? '';
    setEditValue(initialValue !== undefined ? initialValue : String(currentValue));
  }, [localData]);

  const commitEdit = useCallback(() => {
    if (editingCell && localData) {
      updateCell(editingCell.row, editingCell.col, editValue);
    }
    setEditingCell(null);
  }, [editingCell, editValue, updateCell, localData]);

  const cancelEdit = useCallback(() => {
    setEditingCell(null);
    setEditValue('');
  }, []);

  // Keyboard navigation
  const moveSelection = useCallback((dRow: number, dCol: number, extend: boolean = false) => {
    if (!selection || !localData) return;

    const newRow = Math.max(0, Math.min(localData.length - 1, selection.end.row + dRow));
    const newCol = Math.max(0, Math.min((localData[0]?.length || 26) - 1, selection.end.col + dCol));

    if (extend) {
      setSelection(prev => prev ? { ...prev, end: { row: newRow, col: newCol } } : null);
    } else {
      setSelection(createEmptySelection(newRow, newCol));
    }
  }, [selection, localData]);

  // Handle keyboard events
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (editingCell) {
      if (e.key === 'Enter') {
        e.preventDefault();
        commitEdit();
        moveSelection(1, 0);
      } else if (e.key === 'Tab') {
        e.preventDefault();
        commitEdit();
        moveSelection(0, e.shiftKey ? -1 : 1);
      } else if (e.key === 'Escape') {
        cancelEdit();
      }
      return;
    }

    if (!selection) return;

    const ctrlKey = e.ctrlKey || e.metaKey;

    switch (e.key) {
      case 'ArrowUp':
        e.preventDefault();
        moveSelection(-1, 0, e.shiftKey);
        break;
      case 'ArrowDown':
        e.preventDefault();
        moveSelection(1, 0, e.shiftKey);
        break;
      case 'ArrowLeft':
        e.preventDefault();
        moveSelection(0, -1, e.shiftKey);
        break;
      case 'ArrowRight':
        e.preventDefault();
        moveSelection(0, 1, e.shiftKey);
        break;
      case 'Tab':
        e.preventDefault();
        moveSelection(0, e.shiftKey ? -1 : 1);
        break;
      case 'Enter':
        e.preventDefault();
        if (!e.shiftKey) {
          startEditing(selection.start.row, selection.start.col);
        }
        break;
      case 'Delete':
      case 'Backspace':
        e.preventDefault();
        handleClearContent();
        break;
      case 'c':
        if (ctrlKey) {
          e.preventDefault();
          handleCopy();
        }
        break;
      case 'x':
        if (ctrlKey) {
          e.preventDefault();
          handleCut();
        }
        break;
      case 'v':
        if (ctrlKey) {
          e.preventDefault();
          handlePaste();
        }
        break;
      case 'z':
        if (ctrlKey) {
          e.preventDefault();
          e.shiftKey ? handleRedo() : handleUndo();
        }
        break;
      case 'y':
        if (ctrlKey) {
          e.preventDefault();
          handleRedo();
        }
        break;
      case 'b':
        if (ctrlKey) {
          e.preventDefault();
          handleFormatChange({ bold: !getCurrentFormat().bold });
        }
        break;
      case 'i':
        if (ctrlKey) {
          e.preventDefault();
          handleFormatChange({ italic: !getCurrentFormat().italic });
        }
        break;
      case 'u':
        if (ctrlKey) {
          e.preventDefault();
          handleFormatChange({ underline: !getCurrentFormat().underline });
        }
        break;
      default:
        // Start editing on any printable character
        if (e.key.length === 1 && !ctrlKey) {
          e.preventDefault();
          startEditing(selection.start.row, selection.start.col, e.key);
        }
    }
  }, [editingCell, selection, commitEdit, cancelEdit, moveSelection, startEditing]);

  // Cell click handlers
  const handleCellMouseDown = useCallback((row: number, col: number, e: React.MouseEvent) => {
    if (e.shiftKey && selection) {
      setSelection(prev => prev ? { ...prev, end: { row, col } } : createEmptySelection(row, col));
    } else {
      setSelection(createEmptySelection(row, col));
      setIsSelecting(true);
    }
  }, [selection]);

  const handleCellMouseEnter = useCallback((row: number, col: number) => {
    if (isSelecting) {
      setSelection(prev => prev ? { ...prev, end: { row, col } } : null);
    }
  }, [isSelecting]);

  const handleMouseUp = useCallback(() => {
    setIsSelecting(false);
  }, []);

  useEffect(() => {
    document.addEventListener('mouseup', handleMouseUp);
    return () => document.removeEventListener('mouseup', handleMouseUp);
  }, [handleMouseUp]);

  // Format helpers
  const getFormatKey = (row: number, col: number) => `${row}-${col}`;

  const getCurrentFormat = useCallback((): CellFormat => {
    if (!selection) return {};
    const key = getFormatKey(selection.start.row, selection.start.col);
    return cellFormats[key] || {};
  }, [selection, cellFormats]);

  const handleFormatChange = useCallback((format: Partial<CellFormat>) => {
    if (!selection) return;

    const { minRow, maxRow, minCol, maxCol } = getSelectionRange(selection);
    const newFormats = { ...cellFormats };

    for (let row = minRow; row <= maxRow; row++) {
      for (let col = minCol; col <= maxCol; col++) {
        const key = getFormatKey(row, col);
        newFormats[key] = { ...newFormats[key], ...format };
      }
    }

    setCellFormats(newFormats);
    pushHistory(localData || [], newFormats);
  }, [selection, cellFormats, localData, pushHistory]);

  // Clipboard operations
  const handleCopy = useCallback(() => {
    if (!selection || !localData) return;

    const { minRow, maxRow, minCol, maxCol } = getSelectionRange(selection);
    const data: any[][] = [];
    const formats: CellFormats = {};

    for (let row = minRow; row <= maxRow; row++) {
      const rowData: any[] = [];
      for (let col = minCol; col <= maxCol; col++) {
        rowData.push(localData[row]?.[col] ?? '');
        const key = getFormatKey(row, col);
        const newKey = getFormatKey(row - minRow, col - minCol);
        if (cellFormats[key]) {
          formats[newKey] = { ...cellFormats[key] };
        }
      }
      data.push(rowData);
    }

    setClipboard({ data, formats });
    setClipboardSelection(selection);
  }, [selection, localData, cellFormats]);

  const handleCut = useCallback(() => {
    handleCopy();
    handleClearContent();
  }, [handleCopy]);

  const handlePaste = useCallback(() => {
    if (!clipboard || !selection || !localData) return;

    const startRow = selection.start.row;
    const startCol = selection.start.col;

    const newData = localData.map(row => [...row]);
    const newFormats = { ...cellFormats };

    clipboard.data.forEach((row, ri) => {
      row.forEach((cell, ci) => {
        const targetRow = startRow + ri;
        const targetCol = startCol + ci;
        if (targetRow < newData.length && targetCol < (newData[0]?.length || 0)) {
          newData[targetRow][targetCol] = cell;

          const sourceKey = getFormatKey(ri, ci);
          const targetKey = getFormatKey(targetRow, targetCol);
          if (clipboard.formats[sourceKey]) {
            newFormats[targetKey] = { ...clipboard.formats[sourceKey] };
          }
        }
      });
    });

    setLocalData(newData);
    setCellFormats(newFormats);
    pushHistory(newData, newFormats);
    saveData(newData);
  }, [clipboard, selection, localData, cellFormats, pushHistory, saveData]);

  const handleClearContent = useCallback(() => {
    if (!selection || !localData) return;

    const { minRow, maxRow, minCol, maxCol } = getSelectionRange(selection);
    const newData = localData.map((row, ri) => 
      row.map((cell, ci) => {
        if (ri >= minRow && ri <= maxRow && ci >= minCol && ci <= maxCol) {
          return '';
        }
        return cell;
      })
    );

    setLocalData(newData);
    pushHistory(newData, cellFormats);
    saveData(newData);
  }, [selection, localData, cellFormats, pushHistory, saveData]);

  // Undo/Redo
  const handleUndo = useCallback(() => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      const entry = history[newIndex];
      setLocalData(JSON.parse(JSON.stringify(entry.data)));
      setCellFormats({ ...entry.formats });
      setHistoryIndex(newIndex);
      saveData(entry.data);
    }
  }, [history, historyIndex, saveData]);

  const handleRedo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      const entry = history[newIndex];
      setLocalData(JSON.parse(JSON.stringify(entry.data)));
      setCellFormats({ ...entry.formats });
      setHistoryIndex(newIndex);
      saveData(entry.data);
    }
  }, [history, historyIndex, saveData]);

  // Column resize handlers
  const handleResizeStart = useCallback((col: number, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setResizingCol(col);
    resizeStartX.current = e.clientX;
    resizeStartWidth.current = columnWidths[col] ?? DEFAULT_COL_WIDTH;
  }, [columnWidths]);

  useEffect(() => {
    if (resizingCol === null) return;

    const handleMouseMove = (e: MouseEvent) => {
      const delta = e.clientX - resizeStartX.current;
      const newWidth = Math.max(MIN_COL_WIDTH, resizeStartWidth.current + delta);
      setColumnWidths(prev => ({ ...prev, [resizingCol]: newWidth }));
    };

    const handleMouseUp = () => {
      setResizingCol(null);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [resizingCol]);

  // Sheet management
  const handleAddSheet = async () => {
    const sheet = await createSheet(`Sheet ${sheets.length + 1}`);
    if (sheet) {
      setActiveSheetId(sheet.id);
    }
  };

  const handleRenameSheet = async (sheetId: string, name: string) => {
    await updateSheet(sheetId, { name });
    setEditingSheetName(null);
    setNewSheetName('');
  };

  const handleDeleteSheet = async (sheetId: string) => {
    await deleteSheet(sheetId);
    if (activeSheetId === sheetId && sheets.length > 1) {
      const remainingSheets = sheets.filter(s => s.id !== sheetId);
      setActiveSheetId(remainingSheets[0]?.id || null);
    }
  };

  // Formula bar handlers
  const formulaBarValue = useMemo(() => {
    if (!selection || !localData) return '';
    const { row, col } = selection.start;
    return String(localData[row]?.[col] ?? '');
  }, [selection, localData]);

  const handleFormulaBarChange = useCallback((value: string) => {
    setEditValue(value);
    if (selection && !editingCell) {
      startEditing(selection.start.row, selection.start.col, value);
    }
  }, [selection, editingCell, startEditing]);

  const handleFormulaBarSubmit = useCallback(() => {
    if (selection && editValue !== undefined) {
      updateCell(selection.start.row, selection.start.col, editValue);
    }
    setEditingCell(null);
  }, [selection, editValue, updateCell]);

  if (!spreadsheet) {
    return (
      <div className="flex-1 flex items-center justify-center bg-background">
        <div className="text-center text-muted-foreground">
          <Table2 className="h-12 w-12 mx-auto mb-4 opacity-50" />
          <h3 className="text-lg font-medium mb-2">Select a spreadsheet</h3>
          <p className="text-sm">Or create a new spreadsheet to get started</p>
        </div>
      </div>
    );
  }

  if (loading || !localData) {
    return (
      <div className="flex-1 flex items-center justify-center bg-background">
        <div className="animate-pulse text-muted-foreground">Loading sheets...</div>
      </div>
    );
  }

  const cellRefString = selection ? getCellRefString(selection.start.row, selection.start.col) : '';

  return (
    <div 
      className="flex-1 flex flex-col bg-background min-w-0 h-full"
      onKeyDown={handleKeyDown}
      tabIndex={0}
    >
      {/* Top Bar */}
      <div className="flex items-center justify-between p-2 border-b border-border shrink-0">
        <div className="flex items-center gap-2">
          {isLinked ? (
            <div className="relative">
              <Table2 className="h-5 w-5 text-blue-500" />
              <div className="absolute -bottom-0.5 -right-0.5 h-2.5 w-2.5 rounded-full bg-blue-500 border-2 border-background" />
            </div>
          ) : (
            <Table2 className="h-5 w-5 text-primary" />
          )}
          <span className="font-medium">{spreadsheet.name}</span>
          {isLinked && (
            <span className="text-xs bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 px-2 py-0.5 rounded-full">
              Linked
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {isSaving ? (
            <span className="text-xs text-muted-foreground flex items-center gap-1">
              <Save className="h-3 w-3 animate-pulse" />
              Saving...
            </span>
          ) : lastSaved && (
            <span className="text-xs text-muted-foreground flex items-center gap-1">
              <Clock className="h-3 w-3" />
              Saved {formatDistanceToNow(lastSaved, { addSuffix: true })}
            </span>
          )}
        </div>
      </div>

      {/* Toolbar */}
      <SpreadsheetToolbar
        currentFormat={getCurrentFormat()}
        onFormatChange={handleFormatChange}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onCopy={handleCopy}
        onCut={handleCut}
        onPaste={handlePaste}
        onClearContent={handleClearContent}
        hasSelection={selection !== null}
        isLinked={isLinked}
        onConvertToProjectPlan={() => setShowConvertDialog(true)}
        syncStatusComponent={
          linkInfo ? (
            <SyncStatusIndicator
              linkInfo={linkInfo}
              isSyncing={isSyncing}
              onSyncToProject={() => activeSheet && syncToProjectPlan(activeSheet.id, localData || [])}
              onSyncToSpreadsheet={() => activeSheet && syncToSpreadsheet(activeSheet.id)}
              onUnlink={unlinkFromProjectPlan}
            />
          ) : null
        }
      />

      {/* Formula Bar */}
      <FormulaBar
        cellRef={cellRefString}
        value={editingCell ? editValue : formulaBarValue}
        onChange={handleFormulaBarChange}
        onSubmit={handleFormulaBarSubmit}
        onCancel={cancelEdit}
        disabled={!selection}
      />

      {/* Spreadsheet Grid */}
      <div className="flex-1 overflow-hidden" ref={gridRef}>
        <ScrollArea className="h-full">
          <div className="min-w-max select-none">
            {/* Header Row */}
            <div className="flex sticky top-0 z-20 bg-muted">
              {/* Corner cell */}
              <div 
                className="sticky left-0 z-30 bg-muted border-b border-r border-border flex items-center justify-center"
                style={{ width: ROW_HEADER_WIDTH, height: HEADER_HEIGHT }}
              />
              {/* Column headers */}
              {localData[0]?.map((_, colIndex) => (
                <div
                  key={colIndex}
                  className="relative border-b border-r border-border flex items-center justify-center text-xs font-medium text-muted-foreground bg-muted group"
                  style={{ width: columnWidths[colIndex] ?? DEFAULT_COL_WIDTH, height: HEADER_HEIGHT }}
                >
                  {indexToColumn(colIndex)}
                  {/* Resize handle */}
                  <div
                    className="absolute right-0 top-0 bottom-0 w-1 cursor-col-resize hover:bg-primary/50 group-hover:bg-border"
                    onMouseDown={(e) => handleResizeStart(colIndex, e)}
                  />
                </div>
              ))}
            </div>

            {/* Data Rows */}
            {localData.map((row, rowIndex) => (
              <div key={rowIndex} className="flex">
                {/* Row header */}
                <div 
                  className="sticky left-0 z-10 bg-muted border-b border-r border-border flex items-center justify-center text-xs text-muted-foreground"
                  style={{ width: ROW_HEADER_WIDTH, height: ROW_HEIGHT }}
                >
                  {rowIndex + 1}
                </div>
                {/* Cells */}
                {row.map((cell, colIndex) => {
                  const isEditing = editingCell?.row === rowIndex && editingCell?.col === colIndex;
                  const isSelected = isInSelection(rowIndex, colIndex, selection);
                  const isActiveCell = selection?.start.row === rowIndex && selection?.start.col === colIndex;
                  const format = cellFormats[getFormatKey(rowIndex, colIndex)] || {};
                  const displayValue = getCellDisplayValue(cell, localData);

                  return (
                    <ContextMenu key={`${rowIndex}-${colIndex}`}>
                      <ContextMenuTrigger asChild>
                        <div
                          className={cn(
                            'border-b border-r border-border relative',
                            isSelected && !isLinked && 'bg-primary/10',
                            isSelected && isLinked && 'bg-blue-200/50 dark:bg-blue-900/30',
                            isActiveCell && 'ring-2 ring-primary ring-inset z-10',
                            // Blue tint for linked spreadsheets (only data rows, not header row)
                            isLinked && rowIndex > 0 && !isSelected && 'bg-blue-50/50 dark:bg-blue-950/20'
                          )}
                          style={{ 
                            width: columnWidths[colIndex] ?? DEFAULT_COL_WIDTH, 
                            height: ROW_HEIGHT,
                            backgroundColor: !isLinked && format.bgColor ? format.bgColor : undefined,
                          }}
                          onMouseDown={(e) => handleCellMouseDown(rowIndex, colIndex, e)}
                          onMouseEnter={() => handleCellMouseEnter(rowIndex, colIndex)}
                          onDoubleClick={() => startEditing(rowIndex, colIndex)}
                        >
                          {isEditing ? (
                            <input
                              autoFocus
                              value={editValue}
                              onChange={(e) => setEditValue(e.target.value)}
                              onBlur={commitEdit}
                              className="absolute inset-0 w-full h-full px-1 text-sm bg-background border-2 border-primary outline-none font-mono"
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                  e.preventDefault();
                                  commitEdit();
                                  moveSelection(1, 0);
                                } else if (e.key === 'Tab') {
                                  e.preventDefault();
                                  commitEdit();
                                  moveSelection(0, e.shiftKey ? -1 : 1);
                                } else if (e.key === 'Escape') {
                                  cancelEdit();
                                }
                                e.stopPropagation();
                              }}
                            />
                          ) : (
                            <div 
                              className={cn(
                                'w-full h-full px-1 text-sm flex items-center truncate',
                                format.bold && 'font-bold',
                                format.italic && 'italic',
                                format.underline && 'underline',
                                format.strikethrough && 'line-through',
                                format.align === 'center' && 'justify-center',
                                format.align === 'right' && 'justify-end',
                              )}
                              style={{ color: format.textColor || undefined }}
                            >
                              {displayValue}
                            </div>
                          )}
                        </div>
                      </ContextMenuTrigger>
                      <ContextMenuContent>
                        <ContextMenuItem onClick={handleCut}>
                          <Scissors className="h-4 w-4 mr-2" />
                          Cut
                        </ContextMenuItem>
                        <ContextMenuItem onClick={handleCopy}>
                          <Copy className="h-4 w-4 mr-2" />
                          Copy
                        </ContextMenuItem>
                        <ContextMenuItem onClick={handlePaste}>
                          <Clipboard className="h-4 w-4 mr-2" />
                          Paste
                        </ContextMenuItem>
                        <ContextMenuSeparator />
                        <ContextMenuItem onClick={() => {/* Insert row above */}}>
                          <ArrowUp className="h-4 w-4 mr-2" />
                          Insert Row Above
                        </ContextMenuItem>
                        <ContextMenuItem onClick={() => {/* Insert row below */}}>
                          <ArrowDown className="h-4 w-4 mr-2" />
                          Insert Row Below
                        </ContextMenuItem>
                        <ContextMenuSeparator />
                        <ContextMenuItem onClick={handleClearContent}>
                          <Trash2 className="h-4 w-4 mr-2" />
                          Clear Contents
                        </ContextMenuItem>
                      </ContextMenuContent>
                    </ContextMenu>
                  );
                })}
              </div>
            ))}
          </div>
        </ScrollArea>
      </div>

      {/* Sheet Tabs */}
      <div className="flex items-center gap-1 p-2 border-t border-border bg-muted/50 overflow-x-auto shrink-0">
        {sheets.map(sheet => (
          <div
            key={sheet.id}
            className={cn(
              'flex items-center gap-1 px-3 py-1.5 rounded-md text-sm cursor-pointer group',
              activeSheetId === sheet.id
                ? 'bg-background border border-border shadow-sm'
                : 'hover:bg-background/50'
            )}
            onClick={() => setActiveSheetId(sheet.id)}
          >
            {editingSheetName === sheet.id ? (
              <Input
                value={newSheetName}
                onChange={(e) => setNewSheetName(e.target.value)}
                onBlur={() => handleRenameSheet(sheet.id, newSheetName)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleRenameSheet(sheet.id, newSheetName);
                  if (e.key === 'Escape') setEditingSheetName(null);
                }}
                className="h-5 w-20 text-xs px-1"
                autoFocus
                onClick={(e) => e.stopPropagation()}
              />
            ) : (
              <>
                <span>{sheet.name}</span>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button
                      variant="ghost"
                      size="iconSm"
                      className="h-4 w-4 opacity-0 group-hover:opacity-100 transition-opacity"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <ChevronDown className="h-3 w-3" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="start">
                    <DropdownMenuItem onClick={(e) => {
                      e.stopPropagation();
                      setEditingSheetName(sheet.id);
                      setNewSheetName(sheet.name);
                    }}>
                      <Pencil className="h-4 w-4 mr-2" />
                      Rename
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      className="text-destructive"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteSheet(sheet.id);
                      }}
                      disabled={sheets.length <= 1 || isLinked}
                    >
                      <Trash2 className="h-4 w-4 mr-2" />
                      Delete
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            )}
          </div>
        ))}

        {/* Disable add sheet for linked spreadsheets */}
        {!isLinked && (
          <Button
            variant="ghost"
            size="iconSm"
            className="h-7 w-7"
            onClick={handleAddSheet}
          >
            <Plus className="h-4 w-4" />
          </Button>
        )}
        {isLinked && (
          <div className="flex items-center gap-1 px-2 text-xs text-muted-foreground">
            <Lock className="h-3 w-3" />
            <span>Sheets locked</span>
          </div>
        )}
      </div>

      {/* Convert to Project Plan Dialog */}
      <ConvertToProjectPlanDialog
        open={showConvertDialog}
        onOpenChange={setShowConvertDialog}
        spreadsheetName={spreadsheet?.name || 'Spreadsheet'}
        sheetData={localData || []}
        onConvert={async (projectId) => {
          if (activeSheet) {
            return await convertToProjectPlan(projectId, activeSheet.id, localData || []);
          }
          return false;
        }}
      />
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Table2, Link2, FileSpreadsheet, ArrowRight, CheckCircle2 } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { PROJECT_PLAN_COLUMNS } from '@/hooks/useLinkedSpreadsheet';
import { cn } from '@/lib/utils';

interface Project {
  id: string;
  name: string;
  code: string;
}

interface ConvertToProjectPlanDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  spreadsheetName: string;
  sheetData: any[][];
  onConvert: (projectId: string) => Promise<boolean>;
}

export function ConvertToProjectPlanDialog({
  open,
  onOpenChange,
  spreadsheetName,
  sheetData,
  onConvert,
}: ConvertToProjectPlanDialogProps) {
  const [mode, setMode] = useState<'new' | 'existing'>('new');
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');
  const [newProjectName, setNewProjectName] = useState(spreadsheetName);
  const [newProjectCode, setNewProjectCode] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [step, setStep] = useState<'options' | 'preview' | 'complete'>('options');

  // Count rows with data
  const dataRowCount = sheetData.slice(1).filter(row => row?.[1] && String(row[1]).trim()).length;

  useEffect(() => {
    const fetchProjects = async () => {
      const { data } = await supabase
        .from('projects')
        .select('id, name, code')
        .order('name', { ascending: true });
      setProjects(data || []);
    };

    if (open) {
      fetchProjects();
      setStep('options');
      setNewProjectName(spreadsheetName);
      setNewProjectCode(spreadsheetName.substring(0, 4).toUpperCase());
    }
  }, [open, spreadsheetName]);

  const handleConvert = async () => {
    setIsConverting(true);

    try {
      let projectId = selectedProjectId;

      if (mode === 'new') {
        // Create new project
        const { data: newProject, error } = await supabase
          .from('projects')
          .insert({
            name: newProjectName,
            code: newProjectCode || newProjectName.substring(0, 4).toUpperCase(),
            methodology: 'hybrid',
            status: 'active',
            health: 'green',
          })
          .select()
          .single();

        if (error) throw error;
        projectId = newProject.id;
      }

      const success = await onConvert(projectId);
      if (success) {
        setStep('complete');
        setTimeout(() => {
          onOpenChange(false);
        }, 1500);
      }
    } catch (error) {
      console.error('Error converting:', error);
    } finally {
      setIsConverting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Link2 className="h-5 w-5 text-primary" />
            Convert to Project Plan
          </DialogTitle>
          <DialogDescription>
            Link this spreadsheet to a project plan for bi-directional sync.
          </DialogDescription>
        </DialogHeader>

        {step === 'options' && (
          <div className="space-y-6 py-4">
            <RadioGroup value={mode} onValueChange={(v) => setMode(v as 'new' | 'existing')}>
              <div className="grid grid-cols-2 gap-4">
                <Label
                  htmlFor="new"
                  className={cn(
                    'flex flex-col items-center gap-3 p-4 rounded-lg border-2 cursor-pointer transition-colors',
                    mode === 'new' ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50'
                  )}
                >
                  <RadioGroupItem value="new" id="new" className="sr-only" />
                  <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center">
                    <FileSpreadsheet className="h-6 w-6 text-primary" />
                  </div>
                  <div className="text-center">
                    <p className="font-medium">Create New Project</p>
                    <p className="text-xs text-muted-foreground mt-1">
                      Create a new project from this spreadsheet
                    </p>
                  </div>
                </Label>

                <Label
                  htmlFor="existing"
                  className={cn(
                    'flex flex-col items-center gap-3 p-4 rounded-lg border-2 cursor-pointer transition-colors',
                    mode === 'existing' ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50'
                  )}
                >
                  <RadioGroupItem value="existing" id="existing" className="sr-only" />
                  <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center">
                    <Table2 className="h-6 w-6 text-primary" />
                  </div>
                  <div className="text-center">
                    <p className="font-medium">Link to Existing</p>
                    <p className="text-xs text-muted-foreground mt-1">
                      Connect to an existing project plan
                    </p>
                  </div>
                </Label>
              </div>
            </RadioGroup>

            {mode === 'new' && (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="projectName">Project Name</Label>
                  <Input
                    id="projectName"
                    value={newProjectName}
                    onChange={(e) => setNewProjectName(e.target.value)}
                    placeholder="Enter project name"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="projectCode">Project Code</Label>
                  <Input
                    id="projectCode"
                    value={newProjectCode}
                    onChange={(e) => setNewProjectCode(e.target.value.toUpperCase())}
                    placeholder="PROJ"
                    maxLength={10}
                  />
                </div>
              </div>
            )}

            {mode === 'existing' && (
              <div className="space-y-2">
                <Label>Select Project</Label>
                <Select value={selectedProjectId} onValueChange={setSelectedProjectId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Choose a project..." />
                  </SelectTrigger>
                  <SelectContent>
                    {projects.map((project) => (
                      <SelectItem key={project.id} value={project.id}>
                        [{project.code}] {project.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {projects.length === 0 && (
                  <p className="text-sm text-muted-foreground">
                    No projects available. Create a new one instead.
                  </p>
                )}
              </div>
            )}

            <Button
              className="w-full"
              onClick={() => setStep('preview')}
              disabled={(mode === 'new' && !newProjectName.trim()) || (mode === 'existing' && !selectedProjectId)}
            >
              Preview Column Mapping
              <ArrowRight className="h-4 w-4 ml-2" />
            </Button>
          </div>
        )}

        {step === 'preview' && (
