  'not-started': <Circle className="h-4 w-4 text-muted-foreground" />,
  'in-progress': <Clock className="h-4 w-4 text-primary" />,
  'completed': <CheckCircle2 className="h-4 w-4 text-success" />,
  'blocked': <XCircle className="h-4 w-4 text-destructive" />,
  'on-hold': <Pause className="h-4 w-4 text-warning" />,
};

const statusLabels: Record<TaskStatus, string> = {
  'not-started': 'Not Started',
  'in-progress': 'In Progress',
  'completed': 'Completed',
  'blocked': 'Blocked',
  'on-hold': 'On Hold',
};

const typeIcons: Record<TaskType, React.ReactNode> = {
  task: <CheckCircle2 className="h-3.5 w-3.5 text-primary" />,
  milestone: <Diamond className="h-3.5 w-3.5 text-purple-400" />,
  summary: <Folder className="h-3.5 w-3.5 text-info" />,
};

const priorityColors: Record<Priority, string> = {
  critical: 'bg-destructive',
  high: 'bg-orange-500',
  medium: 'bg-warning',
  low: 'bg-success',
};

interface EditableTaskRowProps {
  task: Task;
  expanded: boolean;
  onToggle: () => void;
  selected: boolean;
  onSelect: (selected: boolean) => void;
  focused: boolean;
  onFocus: () => void;
  onTaskUpdate: (taskId: string, updates: Partial<Task>) => void;
  onTaskDelete: (taskId: string) => void;
  onAddChild: (parentId: string) => void;
  onAddSibling: (taskId: string) => void;
  onIndent: (taskId: string) => void;
  onOutdent: (taskId: string) => void;
}

function EditableTaskRow({
  task,
  expanded,
  onToggle,
  selected,
  onSelect,
  focused,
  onFocus,
  onTaskUpdate,
  onTaskDelete,
  onAddChild,
  onAddSibling,
  onIndent,
  onOutdent,
}: EditableTaskRowProps) {
  const hasChildren = task.children && task.children.length > 0;
  const indent = task.level * 24;
  const [isEditing, setIsEditing] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditing]);

  const startEditing = (field: string, value: string) => {
    setIsEditing(field);
    setEditValue(value);
  };

  const commitEdit = (field: string) => {
    if (editValue.trim()) {
      onTaskUpdate(task.id, { [field]: editValue.trim() });
    }
    setIsEditing(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent, field: string) => {
    if (e.key === 'Enter') {
      commitEdit(field);
    } else if (e.key === 'Escape') {
      setIsEditing(null);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, x: -10 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 10 }}
      onClick={onFocus}
      className={cn(
        'group grid grid-cols-[40px_minmax(300px,2fr)_100px_100px_120px_120px_100px_80px_60px] items-center border-b border-border hover:bg-muted/30 transition-colors cursor-pointer',
        selected && 'bg-primary/5',
        focused && 'ring-1 ring-primary ring-inset',
        task.isCritical && 'border-l-2 border-l-destructive'
      )}
    >
      {/* Selection */}
      <div className="flex items-center justify-center h-10">
        <Checkbox checked={selected} onCheckedChange={onSelect} />
      </div>

      {/* Task Name */}
      <div className="flex items-center gap-1 py-2 pr-4" style={{ paddingLeft: indent }}>
        <GripVertical className="h-3 w-3 text-muted-foreground/50 opacity-0 group-hover:opacity-100 cursor-grab" />
        {hasChildren ? (
          <button
            onClick={(e) => { e.stopPropagation(); onToggle(); }}
            className="p-0.5 rounded hover:bg-muted transition-colors"
          >
            {expanded ? (
              <ChevronDown className="h-4 w-4 text-muted-foreground" />
            ) : (
              <ChevronRight className="h-4 w-4 text-muted-foreground" />
            )}
          </button>
        ) : (
          <div className="w-5" />
        )}
        <div className="flex items-center gap-2 flex-1 min-w-0">
          {typeIcons[task.type]}
          <span className="text-xs text-muted-foreground font-mono shrink-0">{task.wbs}</span>
          {isEditing === 'name' ? (
            <Input
              ref={inputRef}
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              onBlur={() => commitEdit('name')}
              onKeyDown={(e) => handleKeyDown(e, 'name')}
              className="h-6 text-sm py-0"
              onClick={(e) => e.stopPropagation()}
            />
          ) : (
            <span
              className={cn(
                'text-sm truncate cursor-text hover:bg-muted/50 px-1 rounded',
                task.type === 'summary' && 'font-semibold',
                task.type === 'milestone' && 'font-medium italic text-purple-400'
              )}
              onDoubleClick={(e) => {
                e.stopPropagation();
                startEditing('name', task.name);
              }}
            >
              {task.name}
            </span>
          )}
          {task.isCritical && (
            <Badge variant="destructive" className="text-[10px] px-1 py-0 h-4">
              Critical
            </Badge>
          )}
        </div>
      </div>

      {/* Status - Editable */}
      <div className="flex items-center">
        <Select
          value={task.status}
          onValueChange={(value: TaskStatus) => onTaskUpdate(task.id, { status: value })}
        >
          <SelectTrigger className="h-7 text-xs border-0 bg-transparent hover:bg-muted/50 gap-1 px-1">
            {statusIcons[task.status]}
            <span className="sr-only">{statusLabels[task.status]}</span>
          </SelectTrigger>
          <SelectContent>
            {Object.entries(statusLabels).map(([value, label]) => (
              <SelectItem key={value} value={value}>
                <div className="flex items-center gap-2">
                  {statusIcons[value as TaskStatus]}
                  <span>{label}</span>
                </div>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Priority - Editable */}
      <div className="flex items-center">
        <Select
          value={task.priority}
          onValueChange={(value: Priority) => onTaskUpdate(task.id, { priority: value })}
        >
          <SelectTrigger className="h-7 text-xs border-0 bg-transparent hover:bg-muted/50 gap-1.5 px-1">
            <div className={cn('h-2 w-2 rounded-full', priorityColors[task.priority])} />
            <span className="capitalize">{task.priority}</span>
          </SelectTrigger>
          <SelectContent>
            {(['critical', 'high', 'medium', 'low'] as Priority[]).map((p) => (
              <SelectItem key={p} value={p}>
                <div className="flex items-center gap-2">
                  <div className={cn('h-2 w-2 rounded-full', priorityColors[p])} />
                  <span className="capitalize">{p}</span>
                </div>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Start Date - Editable */}
      <Popover>
        <PopoverTrigger asChild>
          <button className="text-xs text-muted-foreground font-mono hover:bg-muted/50 px-2 py-1 rounded text-left">
            {format(new Date(task.startDate), 'MMM d')}
          </button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-0" align="start">
          <CalendarComponent
            mode="single"
            selected={new Date(task.startDate)}
            onSelect={(date) => date && onTaskUpdate(task.id, { startDate: date.toISOString().split('T')[0] })}
          />
        </PopoverContent>
      </Popover>

      {/* End Date - Editable */}
      <Popover>
        <PopoverTrigger asChild>
          <button className="text-xs text-muted-foreground font-mono hover:bg-muted/50 px-2 py-1 rounded text-left">
            {format(new Date(task.endDate), 'MMM d')}
          </button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-0" align="start">
          <CalendarComponent
            mode="single"
            selected={new Date(task.endDate)}
            onSelect={(date) => date && onTaskUpdate(task.id, { endDate: date.toISOString().split('T')[0] })}
          />
        </PopoverContent>
      </Popover>

      {/* Duration */}
      <div className="text-xs text-muted-foreground font-mono">
        {task.duration > 0 ? `${task.duration}d` : '—'}
      </div>

      {/* Progress - Editable slider */}
      <div className="flex items-center gap-2">
        <div
          className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden cursor-pointer"
          onClick={(e) => {
            e.stopPropagation();
            const rect = e.currentTarget.getBoundingClientRect();
            const percent = Math.round(((e.clientX - rect.left) / rect.width) * 100);
            onTaskUpdate(task.id, { progress: Math.max(0, Math.min(100, percent)) });
          }}
        >
          <div
            className={cn(
              'h-full rounded-full transition-all',
              task.progress === 100 ? 'bg-success' : 'bg-primary'
            )}
            style={{ width: `${task.progress}%` }}
          />
        </div>
        <span className="text-xs text-muted-foreground font-mono w-8">
          {task.progress}%
        </span>
      </div>

      {/* Actions */}
      <div className="flex items-center justify-center">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="iconXs" className="opacity-0 group-hover:opacity-100">
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={() => onAddSibling(task.id)}>
              <Plus className="h-4 w-4 mr-2" />
              Add Task Below
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => onAddChild(task.id)}>
              <Plus className="h-4 w-4 mr-2" />
              Add Subtask
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => onIndent(task.id)}>
              <MoveDown className="h-4 w-4 mr-2 rotate-[-90deg]" />
              Indent
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => onOutdent(task.id)}>
              <MoveUp className="h-4 w-4 mr-2 rotate-[-90deg]" />
              Outdent
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem>
              <Copy className="h-4 w-4 mr-2" />
              Duplicate
            </DropdownMenuItem>
            <DropdownMenuItem
              className="text-destructive"
              onClick={() => onTaskDelete(task.id)}
            >
              <Trash2 className="h-4 w-4 mr-2" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </motion.div>
  );
}

interface TaskGridProps {
  tasks: Task[];
  onTasksChange: (tasks: Task[]) => void;
}

export function TaskGrid({ tasks, onTasksChange }: TaskGridProps) {
  const [expandedTasks, setExpandedTasks] = useState<Set<string>>(
    new Set(tasks.filter(t => t.expanded).map(t => t.id))
  );
  const [selectedTasks, setSelectedTasks] = useState<Set<string>>(new Set());
  const [focusedTaskId, setFocusedTaskId] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Flatten tasks for display
  const flattenTasks = useCallback((taskList: Task[]): Task[] => {
    const result: Task[] = [];
    for (const task of taskList) {
      result.push(task);
      if (task.children && expandedTasks.has(task.id)) {
        result.push(...flattenTasks(task.children));
      }
    }
    return result;
  }, [expandedTasks]);

  const visibleTasks = flattenTasks(tasks);

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!focusedTaskId) return;

      const currentIndex = visibleTasks.findIndex(t => t.id === focusedTaskId);
      if (currentIndex === -1) return;

      switch (e.key) {
        case 'ArrowUp':
          e.preventDefault();
          if (currentIndex > 0) {
            setFocusedTaskId(visibleTasks[currentIndex - 1].id);
          }
          break;
        case 'ArrowDown':
          e.preventDefault();
          if (currentIndex < visibleTasks.length - 1) {
            setFocusedTaskId(visibleTasks[currentIndex + 1].id);
          }
          break;
        case 'ArrowRight':
          if (!expandedTasks.has(focusedTaskId)) {
            const task = visibleTasks[currentIndex];
            if (task.children && task.children.length > 0) {
              setExpandedTasks(prev => new Set([...prev, focusedTaskId]));
            }
          }
          break;
        case 'ArrowLeft':
          if (expandedTasks.has(focusedTaskId)) {
            setExpandedTasks(prev => {
              const next = new Set(prev);
              next.delete(focusedTaskId);
              return next;
            });
          }
          break;
        case ' ':
          e.preventDefault();
          setSelectedTasks(prev => {
            const next = new Set(prev);
            if (next.has(focusedTaskId)) {
              next.delete(focusedTaskId);
            } else {
              next.add(focusedTaskId);
            }
            return next;
          });
          break;
        case 'Delete':
        case 'Backspace':
          if (e.metaKey || e.ctrlKey) {
            handleTaskDelete(focusedTaskId);
          }
          break;
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [focusedTaskId, visibleTasks, expandedTasks]);

  const toggleTask = (taskId: string) => {
    setExpandedTasks((prev) => {
      const next = new Set(prev);
      if (next.has(taskId)) {
        next.delete(taskId);
      } else {
        next.add(taskId);
      }
      return next;
    });
  };

  const toggleSelection = (taskId: string, selected: boolean) => {
    setSelectedTasks((prev) => {
      const next = new Set(prev);
      if (selected) {
        next.add(taskId);
      } else {
        next.delete(taskId);
      }
      return next;
    });
  };

  // Deep update tasks
  const updateTaskInTree = (taskList: Task[], taskId: string, updates: Partial<Task>): Task[] => {
    return taskList.map(task => {
      if (task.id === taskId) {
        return { ...task, ...updates };
      }
      if (task.children) {
        return { ...task, children: updateTaskInTree(task.children, taskId, updates) };
      }
      return task;
    });
  };

  const handleTaskUpdate = (taskId: string, updates: Partial<Task>) => {
    onTasksChange(updateTaskInTree(tasks, taskId, updates));
  };

  const deleteTaskFromTree = (taskList: Task[], taskId: string): Task[] => {
    return taskList
      .filter(task => task.id !== taskId)
      .map(task => ({
        ...task,
        children: task.children ? deleteTaskFromTree(task.children, taskId) : undefined,
      }));
  };

  const handleTaskDelete = (taskId: string) => {
    onTasksChange(deleteTaskFromTree(tasks, taskId));
    if (focusedTaskId === taskId) {
      setFocusedTaskId(null);
    }
  };

  const handleAddChild = (parentId: string) => {
    const newTask: Task = {
      id: `T-${Date.now()}`,
      wbs: '',
      name: 'New Task',
      type: 'task',
      status: 'not-started',
      priority: 'medium',
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0],
      duration: 1,
      progress: 0,
      dependencies: [],
      level: 0,
    };

    const addChildToParent = (taskList: Task[]): Task[] => {
      return taskList.map(task => {
        if (task.id === parentId) {
          return {
            ...task,
            type: 'summary' as TaskType,
            children: [...(task.children || []), { ...newTask, level: task.level + 1 }],
          };
        }
        if (task.children) {
          return { ...task, children: addChildToParent(task.children) };
        }
        return task;
      });
    };

    onTasksChange(addChildToParent(tasks));
    setExpandedTasks(prev => new Set([...prev, parentId]));
  };

  const handleAddSibling = (taskId: string) => {
    const newTask: Task = {
      id: `T-${Date.now()}`,
      wbs: '',
      name: 'New Task',
      type: 'task',
      status: 'not-started',
      priority: 'medium',
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0],
      duration: 1,
      progress: 0,
      dependencies: [],
      level: 0,
    };

    const addSiblingAfter = (taskList: Task[], level: number): Task[] => {
      const result: Task[] = [];
      for (const task of taskList) {
        result.push(task);
        if (task.id === taskId) {
          result.push({ ...newTask, level });
        }
        if (task.children) {
          result[result.length - 1] = { ...task, children: addSiblingAfter(task.children, task.level + 1) };
        }
      }
      return result;
    };

    onTasksChange(addSiblingAfter(tasks, 0));
  };

  const handleIndent = (taskId: string) => {
    // TODO: Implement indent logic
    console.log('Indent', taskId);
  };

  const handleOutdent = (taskId: string) => {
    // TODO: Implement outdent logic
    console.log('Outdent', taskId);
  };

  return (
    <div ref={containerRef} className="flex flex-col flex-1 overflow-hidden">
      {/* Table Header */}
      <div className="grid grid-cols-[40px_minmax(300px,2fr)_100px_100px_120px_120px_100px_80px_60px] items-center border-b border-border bg-muted/50 text-xs font-medium text-muted-foreground">
        <div className="flex items-center justify-center h-9">
          <Checkbox
            checked={selectedTasks.size === visibleTasks.length && visibleTasks.length > 0}
            onCheckedChange={(checked) => {
              if (checked) {
                setSelectedTasks(new Set(visibleTasks.map(t => t.id)));
              } else {
                setSelectedTasks(new Set());
              }
            }}
          />
        </div>
        <div className="py-2 px-2">Task Name</div>
        <div className="py-2">Status</div>
        <div className="py-2">Priority</div>
        <div className="py-2 flex items-center gap-1">
          <Calendar className="h-3 w-3" />
          Start
        </div>
        <div className="py-2 flex items-center gap-1">
          <Calendar className="h-3 w-3" />
          End
        </div>
        <div className="py-2">Duration</div>
        <div className="py-2">Progress</div>
        <div className="py-2"></div>
      </div>

      {/* Task List */}
      <div className="flex-1 overflow-auto">
        <AnimatePresence>
          {visibleTasks.map((task) => (
            <EditableTaskRow
              key={task.id}
              task={task}
              expanded={expandedTasks.has(task.id)}
              onToggle={() => toggleTask(task.id)}
              selected={selectedTasks.has(task.id)}
              onSelect={(selected) => toggleSelection(task.id, selected)}
              focused={focusedTaskId === task.id}
              onFocus={() => setFocusedTaskId(task.id)}
              onTaskUpdate={handleTaskUpdate}
              onTaskDelete={handleTaskDelete}
              onAddChild={handleAddChild}
              onAddSibling={handleAddSibling}
              onIndent={handleIndent}
              onOutdent={handleOutdent}
            />
          ))}
        </AnimatePresence>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between p-3 border-t bg-muted/30 text-xs text-muted-foreground">
        <div className="flex items-center gap-4">
          <span>{visibleTasks.length} tasks</span>
          <span>{selectedTasks.size} selected</span>
          <span className="text-muted-foreground/60">
            ↑↓ navigate • ←→ expand/collapse • Space select • ⌘+Delete remove
          </span>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-1">
            <div className="h-2 w-2 rounded-full bg-destructive" />
            <span>Critical: {visibleTasks.filter(t => t.isCritical).length}</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="h-2 w-2 rounded-full bg-primary" />
            <span>In Progress: {visibleTasks.filter(t => t.status === 'in-progress').length}</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="h-2 w-2 rounded-full bg-success" />
            <span>Complete: {visibleTasks.filter(t => t.status === 'completed').length}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Link from '@tiptap/extension-link';
import Placeholder from '@tiptap/extension-placeholder';
import TextAlign from '@tiptap/extension-text-align';
import Underline from '@tiptap/extension-underline';
import { TextStyle } from '@tiptap/extension-text-style';
import Color from '@tiptap/extension-color';
import Highlight from '@tiptap/extension-highlight';
import Image from '@tiptap/extension-image';
import { Table } from '@tiptap/extension-table';
import TableRow from '@tiptap/extension-table-row';
import TableCell from '@tiptap/extension-table-cell';
import TableHeader from '@tiptap/extension-table-header';
import type { PresentationSlide } from '@/hooks/useSlides';
import { cn } from '@/lib/utils';
import { EmbeddedDashboardWidget, EmbeddedComponentData } from './EmbeddedDashboardWidget';

interface SlideEditorProps {
  slide: PresentationSlide | null;
  onContentChange: (content: string) => void;
  onEditorReady: (editor: ReturnType<typeof useEditor>) => void;
  isEditable?: boolean;
  embeddedComponents?: EmbeddedComponentData[];
  isActivePresentation?: boolean;
  onRefreshComponent?: (componentId: string) => void;
  onToggleLive?: (componentId: string, isLive: boolean) => void;
  onRemoveComponent?: (componentId: string) => void;
}

export function SlideEditor({
  slide,
  onContentChange,
  onEditorReady,
  isEditable = true,
  embeddedComponents = [],
  isActivePresentation = false,
  onRefreshComponent,
  onToggleLive,
  onRemoveComponent,
}: SlideEditorProps) {
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: {
          levels: [1, 2, 3],
        },
      }),
      Link.configure({
        openOnClick: false,
        HTMLAttributes: {
          class: 'text-primary underline cursor-pointer',
        },
      }),
      Placeholder.configure({
        placeholder: 'Click to start editing your slide...',
      }),
      TextAlign.configure({
        types: ['heading', 'paragraph'],
      }),
      Underline,
      TextStyle,
      Color,
      Highlight.configure({
        multicolor: true,
      }),
      Image.configure({
        HTMLAttributes: {
          class: 'max-w-full h-auto rounded-lg',
        },
      }),
      Table.configure({
        resizable: true,
        HTMLAttributes: {
          class: 'border-collapse table-auto w-full',
        },
      }),
      TableRow,
      TableCell.configure({
        HTMLAttributes: {
          class: 'border border-border p-2',
        },
      }),
      TableHeader.configure({
        HTMLAttributes: {
          class: 'border border-border p-2 bg-muted font-semibold',
        },
      }),
    ],
    content: slide?.html_content || '',
    editable: isEditable,
    onUpdate: ({ editor }) => {
      onContentChange(editor.getHTML());
    },
    editorProps: {
      attributes: {
        class: cn(
          'prose prose-lg dark:prose-invert max-w-none focus:outline-none min-h-[400px] p-8',
          'prose-headings:text-foreground prose-p:text-foreground prose-strong:text-foreground',
          'prose-h1:text-5xl prose-h1:font-bold prose-h1:mb-6',
          'prose-h2:text-3xl prose-h2:font-semibold prose-h2:mb-4',
          'prose-h3:text-2xl prose-h3:font-medium prose-h3:mb-3',
          'prose-ul:list-disc prose-ol:list-decimal',
          'prose-li:text-foreground prose-li:my-1',
          'prose-a:text-primary prose-a:no-underline hover:prose-a:underline'
        ),
      },
    },
  });

  useEffect(() => {
    if (editor) {
      onEditorReady(editor);
    }
  }, [editor, onEditorReady]);

  useEffect(() => {
    if (editor && slide?.html_content !== undefined) {
      const currentContent = editor.getHTML();
      if (currentContent !== slide.html_content) {
        editor.commands.setContent(slide.html_content || '');
      }
    }
  }, [editor, slide?.id]); // Only update when slide changes

  const getBackgroundStyle = () => {
    if (!slide?.background) return {};

    switch (slide.background.type) {
      case 'solid':
        return { backgroundColor: slide.background.color || '#ffffff' };
      case 'gradient':
        return { background: slide.background.gradient };
      case 'image':
        return {
          backgroundImage: `url(${slide.background.imageUrl})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
        };
      default:
        return {};
    }
  };

  if (!slide) {
    return (
      <div className="h-full flex items-center justify-center bg-muted/30">
        <p className="text-muted-foreground">Select a slide to edit</p>
      </div>
    );
  }

  return (
    <div
      className="h-full overflow-auto bg-card rounded-lg shadow-lg border border-border relative"
      style={getBackgroundStyle()}
    >
      <EditorContent editor={editor} className="h-full" />

      {/* Embedded Dashboard Components Layer */}
      {embeddedComponents.length > 0 && (
        <div className="absolute inset-0 pointer-events-none p-4">
          <div className="flex flex-wrap gap-4 pointer-events-auto">
            {embeddedComponents.map((component) => (
              <EmbeddedDashboardWidget
                key={component.id}
                data={component}
                isActive={isActivePresentation}
                isEditable={isEditable}
                onRefresh={onRefreshComponent || (() => {})}
                onToggleLive={onToggleLive || (() => {})}
                onRemove={onRemoveComponent || (() => {})}
              />
            ))}
          </div>
        </div>
      )}

      {/* Shapes Layer */}
      {slide.shapes && slide.shapes.length > 0 && (
        <div className="absolute inset-0 pointer-events-none">
          {slide.shapes.map((shape) => (
            <div
              key={shape.id}
              className="absolute pointer-events-auto cursor-move"
              style={{
                left: shape.x,
                top: shape.y,
                width: shape.width,
                height: shape.height,
                transform: `rotate(${shape.rotation}deg)`,
                zIndex: shape.zIndex,
              }}
            >
              <svg width="100%" height="100%">
                {shape.type === 'rectangle' && (
                  <rect
                    width="100%"
                    height="100%"
                    fill={shape.fill}
                    stroke={shape.stroke}
                    strokeWidth={shape.strokeWidth}
                    rx="4"
                  />
                )}
                {shape.type === 'circle' && (
                  <ellipse
                    cx="50%"
                    cy="50%"
                    rx="50%"
                    ry="50%"
                    fill={shape.fill}
                    stroke={shape.stroke}
                    strokeWidth={shape.strokeWidth}
                  />
                )}
                {shape.type === 'triangle' && (
                  <polygon
                    points={`${shape.width / 2},0 ${shape.width},${shape.height} 0,${shape.height}`}
                    fill={shape.fill}
                    stroke={shape.stroke}
                    strokeWidth={shape.strokeWidth}
                  />
                )}
              </svg>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

