import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { templateCategories, methodologyOptions } from '@/data/templateData';
import type { ProjectTemplate, TemplateCategory, Methodology } from '@/types/templates';

const iconMap: Record<string, React.ElementType> = {
  Rocket,
  Palette,
  TrendingUp,
  Code,
  Building,
  GitMerge,
  Database,
  Layers,
  ArrowUpCircle,
  Users,
  RefreshCw,
  Zap,
  Shield,
  Cloud,
  Server,
};

interface TemplateGalleryProps {
  templates: ProjectTemplate[];
  selectedTemplate: ProjectTemplate | null;
  onSelect: (template: ProjectTemplate) => void;
  onPreview: (template: ProjectTemplate) => void;
}

export function TemplateGallery({
  templates,
  selectedTemplate,
  onSelect,
  onPreview,
}: TemplateGalleryProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<TemplateCategory | 'all'>('all');
  const [methodologyFilter, setMethodologyFilter] = useState<Methodology | 'all'>('all');
  const [complexityFilter, setComplexityFilter] = useState<string>('all');

  const filteredTemplates = useMemo(() => {
    return templates.filter((template) => {
      const matchesSearch =
        searchQuery === '' ||
        template.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        template.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        template.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase()));

      const matchesCategory = categoryFilter === 'all' || template.category === categoryFilter;
      const matchesMethodology = methodologyFilter === 'all' || template.methodology === methodologyFilter;
      const matchesComplexity = complexityFilter === 'all' || template.complexity === complexityFilter;

      return matchesSearch && matchesCategory && matchesMethodology && matchesComplexity;
    });
  }, [templates, searchQuery, categoryFilter, methodologyFilter, complexityFilter]);

  const getMethodologyLabel = (methodology: Methodology) => {
    const option = methodologyOptions.find((m) => m.id === methodology);
    return option?.name || methodology;
  };

  const getComplexityColor = (complexity: string) => {
    switch (complexity) {
      case 'low':
        return 'bg-green-500/10 text-green-500';
      case 'medium':
        return 'bg-yellow-500/10 text-yellow-500';
      case 'high':
        return 'bg-orange-500/10 text-orange-500';
      case 'enterprise':
        return 'bg-red-500/10 text-red-500';
      default:
        return 'bg-muted text-muted-foreground';
    }
  };

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search templates..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9"
          />
        </div>
        <div className="flex gap-2">
          <Select value={categoryFilter} onValueChange={(v: any) => setCategoryFilter(v)}>
            <SelectTrigger className="w-[160px]">
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              {templateCategories.map((cat) => (
                <SelectItem key={cat.id} value={cat.id}>
                  {cat.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={methodologyFilter} onValueChange={(v: any) => setMethodologyFilter(v)}>
            <SelectTrigger className="w-[160px]">
              <SelectValue placeholder="Methodology" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Methodologies</SelectItem>
              {methodologyOptions.map((m) => (
                <SelectItem key={m.id} value={m.id}>
                  {m.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={complexityFilter} onValueChange={setComplexityFilter}>
            <SelectTrigger className="w-[140px]">
              <SelectValue placeholder="Complexity" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Levels</SelectItem>
              <SelectItem value="low">Low</SelectItem>
              <SelectItem value="medium">Medium</SelectItem>
              <SelectItem value="high">High</SelectItem>
              <SelectItem value="enterprise">Enterprise</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Category Tabs */}
      <Tabs value={categoryFilter} onValueChange={(v: any) => setCategoryFilter(v)}>
        <TabsList className="flex-wrap h-auto gap-1">
          <TabsTrigger value="all" className="text-xs">
            All ({templates.length})
          </TabsTrigger>
          {templateCategories.map((cat) => (
            <TabsTrigger key={cat.id} value={cat.id} className="text-xs">
              {cat.name} ({cat.count})
            </TabsTrigger>
          ))}
        </TabsList>
      </Tabs>

      {/* Templates Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredTemplates.map((template) => {
          const Icon = iconMap[template.icon] || Layers;
          const isSelected = selectedTemplate?.id === template.id;

          return (
            <motion.div
              key={template.id}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
            >
              <Card
                className={`cursor-pointer transition-all h-full ${
                  isSelected
                    ? 'ring-2 ring-primary border-primary'
                    : 'hover:border-primary/50'
                }`}
                onClick={() => onSelect(template)}
              >
                <CardContent className="p-4">
                  <div className="flex items-start gap-3 mb-3">
                    <div
                      className="p-2.5 rounded-lg shrink-0"
                      style={{ backgroundColor: `${template.color}20` }}
                    >
                      <Icon className="h-5 w-5" style={{ color: template.color }} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <h3 className="font-semibold text-sm truncate">{template.name}</h3>
                        {isSelected && (
                          <Check className="h-4 w-4 text-primary shrink-0" />
                        )}
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                        <Badge variant="outline" className="text-xs">
                          {getMethodologyLabel(template.methodology)}
                        </Badge>
                        <Badge className={`text-xs ${getComplexityColor(template.complexity)}`}>
                          {template.complexity}
                        </Badge>
                      </div>
                    </div>
                  </div>

                  <p className="text-xs text-muted-foreground line-clamp-2 mb-3">
                    {template.description}
                  </p>

                  <div className="flex items-center justify-between text-xs text-muted-foreground">
                    <div className="flex items-center gap-3">
                      <span className="flex items-center gap-1">
                        <Target className="h-3 w-3" />
                        {template.phases.length} phases
                      </span>
                      <span className="flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        {template.aiMetadata.typicalDuration.min}-{template.aiMetadata.typicalDuration.max}{' '}
                        {template.aiMetadata.typicalDuration.unit.charAt(0)}
                      </span>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-6 text-xs px-2"
                      onClick={(e) => {
                        e.stopPropagation();
                        onPreview(template);
                      }}
                    >
                      <Eye className="h-3 w-3 mr-1" />
                      Preview
                    </Button>
                  </div>

                  {template.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-3 pt-3 border-t">
                      {template.tags.slice(0, 4).map((tag) => (
                        <Badge key={tag} variant="secondary" className="text-xs px-1.5 py-0">
                          {tag}
                        </Badge>
                      ))}
                      {template.tags.length > 4 && (
                        <Badge variant="secondary" className="text-xs px-1.5 py-0">
                          +{template.tags.length - 4}
                        </Badge>
                      )}
                    </div>
                  )}
                </CardContent>
              </Card>
            </motion.div>
          );
        })}
      </div>

      {filteredTemplates.length === 0 && (
        <div className="text-center py-12">
          <Filter className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
          <h3 className="font-semibold mb-2">No templates found</h3>
          <p className="text-muted-foreground text-sm">
            Try adjusting your filters or search query.
          </p>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Plus, Trash2, Edit2, Save, X, Users, Calendar as CalendarIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  useResources,
  useCreateResource,
  useUpdateResource,
  useDeleteResource,
  Resource,
} from '@/hooks/useResources';
import { useProjectCalendars } from '@/hooks/useCalendars';
import { toast } from 'sonner';

interface ResourceSheetProps {
  projectId: string;
}

export function ResourceSheet({ projectId }: ResourceSheetProps) {
  const { data: resources = [], isLoading } = useResources(projectId);
  const { data: calendars = [] } = useProjectCalendars(projectId);
  const createResource = useCreateResource();
  const updateResource = useUpdateResource();
  const deleteResource = useDeleteResource();

  const [showAddDialog, setShowAddDialog] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    type: 'work' as 'work' | 'material' | 'cost',
    max_units: 1,
    standard_rate: 0,
    overtime_rate: 0,
    cost_per_use: 0,
    notes: '',
    calendar_id: null as string | null,
  });

  const resetForm = () => {
    setFormData({
      name: '',
      email: '',
      type: 'work',
      max_units: 1,
      standard_rate: 0,
      overtime_rate: 0,
      cost_per_use: 0,
      notes: '',
      calendar_id: null,
    });
  };

  const getCalendarName = (calendarId: string | null) => {
    if (!calendarId) return 'Project Default';
    const cal = calendars.find((c) => c.id === calendarId);
    return cal?.name || 'Unknown';
  };

  const handleAdd = async () => {
    if (!formData.name.trim()) {
      toast.error('Resource name is required');
      return;
    }

    await createResource.mutateAsync({
      project_id: projectId,
      name: formData.name,
      email: formData.email || null,
      type: formData.type,
      max_units: formData.max_units,
      standard_rate: formData.standard_rate,
      overtime_rate: formData.overtime_rate,
      cost_per_use: formData.cost_per_use,
      notes: formData.notes || null,
      calendar_id: formData.calendar_id,
    });

    resetForm();
    setShowAddDialog(false);
  };

  const handleEdit = (resource: Resource) => {
    setEditingId(resource.id);
    setFormData({
      name: resource.name,
      email: resource.email || '',
      type: resource.type,
      max_units: resource.max_units,
      standard_rate: resource.standard_rate,
      overtime_rate: resource.overtime_rate,
      cost_per_use: resource.cost_per_use,
      notes: resource.notes || '',
      calendar_id: resource.calendar_id,
    });
  };

  const handleSaveEdit = async (resourceId: string) => {
    await updateResource.mutateAsync({
      id: resourceId,
      name: formData.name,
      email: formData.email || null,
      type: formData.type,
      max_units: formData.max_units,
      standard_rate: formData.standard_rate,
      overtime_rate: formData.overtime_rate,
      cost_per_use: formData.cost_per_use,
      notes: formData.notes || null,
      calendar_id: formData.calendar_id,
    });

    setEditingId(null);
    resetForm();
  };

  const handleDelete = async (resource: Resource) => {
    if (confirm(`Delete resource "${resource.name}"?`)) {
      await deleteResource.mutateAsync({ id: resource.id, projectId });
    }
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'work':
        return 'bg-primary/20 text-primary';
      case 'material':
        return 'bg-amber-500/20 text-amber-600';
      case 'cost':
        return 'bg-green-500/20 text-green-600';
      default:
        return 'bg-muted text-muted-foreground';
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Toolbar */}
      <div className="flex items-center justify-between p-4 border-b bg-card">
        <div className="flex items-center gap-2">
          <Users className="h-5 w-5 text-muted-foreground" />
          <h2 className="font-semibold">Resource Sheet</h2>
          <Badge variant="secondary">{resources.length} resources</Badge>
        </div>
        <Button size="sm" onClick={() => setShowAddDialog(true)}>
          <Plus className="h-4 w-4 mr-1" />
          Add Resource
        </Button>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[200px]">Resource Name</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Email</TableHead>
              <TableHead>Calendar</TableHead>
              <TableHead className="text-right">Max Units</TableHead>
              <TableHead className="text-right">Std. Rate ($/hr)</TableHead>
              <TableHead className="text-right">OT Rate ($/hr)</TableHead>
              <TableHead className="text-right">Cost/Use</TableHead>
              <TableHead className="w-[100px]">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {resources.length === 0 ? (
              <TableRow>
                <TableCell colSpan={9} className="text-center text-muted-foreground py-8">
                  No resources yet. Click "Add Resource" to create one.
                </TableCell>
              </TableRow>
            ) : (
              resources.map((resource) => (
                <TableRow key={resource.id}>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Input
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        className="h-8"
                      />
                    ) : (
                      <span className="font-medium">{resource.name}</span>
                    )}
                  </TableCell>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Select
                        value={formData.type}
                        onValueChange={(v) => setFormData({ ...formData, type: v as any })}
                      >
                        <SelectTrigger className="h-8 w-24">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="work">Work</SelectItem>
                          <SelectItem value="material">Material</SelectItem>
                          <SelectItem value="cost">Cost</SelectItem>
                        </SelectContent>
                      </Select>
                    ) : (
                      <Badge className={getTypeColor(resource.type)} variant="secondary">
                        {resource.type}
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Input
                        type="email"
                        value={formData.email}
                        onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                        className="h-8"
                      />
                    ) : (
                      <span className="text-muted-foreground">{resource.email || '—'}</span>
                    )}
                  </TableCell>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Select
                        value={formData.calendar_id || '__default__'}
                        onValueChange={(v) =>
                          setFormData({ ...formData, calendar_id: v === '__default__' ? null : v })
                        }
                      >
                        <SelectTrigger className="h-8 w-32">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="__default__">Project Default</SelectItem>
                          {calendars.map((cal) => (
                            <SelectItem key={cal.id} value={cal.id}>
                              {cal.name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : (
                      <div className="flex items-center gap-1.5">
                        <CalendarIcon className="h-3 w-3 text-muted-foreground" />
                        <span className="text-sm">{getCalendarName(resource.calendar_id)}</span>
                      </div>
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    {editingId === resource.id ? (
                      <Input
                        type="number"
                        step="0.1"
                        min="0"
                        value={formData.max_units}
                        onChange={(e) => setFormData({ ...formData, max_units: parseFloat(e.target.value) })}
                        className="h-8 w-20 text-right"
                      />
                    ) : (
                      `${(resource.max_units * 100).toFixed(0)}%`
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    {editingId === resource.id ? (
                      <Input
                        type="number"
                        step="0.01"
                        min="0"
                        value={formData.standard_rate}
                        onChange={(e) => setFormData({ ...formData, standard_rate: parseFloat(e.target.value) })}
                        className="h-8 w-24 text-right"
                      />
                    ) : (
                      `$${resource.standard_rate.toFixed(2)}`
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    {editingId === resource.id ? (
                      <Input
                        type="number"
                        step="0.01"
                        min="0"
                        value={formData.overtime_rate}
                        onChange={(e) => setFormData({ ...formData, overtime_rate: parseFloat(e.target.value) })}
                        className="h-8 w-24 text-right"
                      />
                    ) : (
                      `$${resource.overtime_rate.toFixed(2)}`
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    {editingId === resource.id ? (
                      <Input
                        type="number"
                        step="0.01"
                        min="0"
                        value={formData.cost_per_use}
                        onChange={(e) => setFormData({ ...formData, cost_per_use: parseFloat(e.target.value) })}
                        className="h-8 w-24 text-right"
                      />
                    ) : (
                      `$${resource.cost_per_use.toFixed(2)}`
                    )}
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      {editingId === resource.id ? (
                        <>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => handleSaveEdit(resource.id)}
                          >
                            <Save className="h-4 w-4 text-primary" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => {
                              setEditingId(null);
                              resetForm();
                            }}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </>
                      ) : (
                        <>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => handleEdit(resource)}
                          >
                            <Edit2 className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 text-destructive hover:text-destructive"
                            onClick={() => handleDelete(resource)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* Add Resource Dialog */}
      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Add Resource</DialogTitle>
            <DialogDescription>
              Create a new resource for this project.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="col-span-2">
                <Label htmlFor="name">Resource Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g., John Smith"
                />
              </div>
              <div>
                <Label htmlFor="type">Type</Label>
                <Select
                  value={formData.type}
                  onValueChange={(v) => setFormData({ ...formData, type: v as any })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="work">Work</SelectItem>
                    <SelectItem value="material">Material</SelectItem>
                    <SelectItem value="cost">Cost</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  placeholder="john@example.com"
                />
              </div>
              <div>
                <Label htmlFor="max_units">Max Units (%)</Label>
                <Input
                  id="max_units"
                  type="number"
                  step="0.1"
                  min="0"
                  value={formData.max_units * 100}
                  onChange={(e) => setFormData({ ...formData, max_units: parseFloat(e.target.value) / 100 })}
                />
              </div>
              <div>
                <Label htmlFor="standard_rate">Std. Rate ($/hr)</Label>
                <Input
                  id="standard_rate"
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.standard_rate}
                  onChange={(e) => setFormData({ ...formData, standard_rate: parseFloat(e.target.value) })}
                />
              </div>
              <div>
                <Label htmlFor="overtime_rate">OT Rate ($/hr)</Label>
                <Input
                  id="overtime_rate"
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.overtime_rate}
                  onChange={(e) => setFormData({ ...formData, overtime_rate: parseFloat(e.target.value) })}
                />
              </div>
              <div>
                <Label htmlFor="cost_per_use">Cost/Use ($)</Label>
                <Input
                  id="cost_per_use"
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.cost_per_use}
                  onChange={(e) => setFormData({ ...formData, cost_per_use: parseFloat(e.target.value) })}
                />
              </div>
              <div>
                <Label htmlFor="calendar">Calendar</Label>
                <Select
                  value={formData.calendar_id || '__default__'}
                  onValueChange={(v) =>
                    setFormData({ ...formData, calendar_id: v === '__default__' ? null : v })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="__default__">Project Default</SelectItem>
                    {calendars.map((cal) => (
                      <SelectItem key={cal.id} value={cal.id}>
                        {cal.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <Label htmlFor="notes">Notes</Label>
              <Textarea
                id="notes"
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                rows={2}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAddDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleAdd} disabled={createResource.isPending}>
              Add Resource
            </Button>
          </DialogFooter>
