            </h1>
            <p className="text-muted-foreground">AI-powered analysis of project communications</p>
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              className="gap-2"
              onClick={() => toast.success('Communications imported from linked sources')}
