                  {items.map((comm) => (
                    <motion.div
                      key={comm.id}
                      whileHover={{ scale: 1.01 }}
                      onClick={() => setSelectedId(comm.id)}
                      className={cn(
                        'p-3 rounded-lg border cursor-pointer transition-all',
