                      <div className="flex items-center gap-2 flex-wrap mb-4">
                        <span className="text-sm text-muted-foreground">Participants:</span>
                        {selectedComm.participants.map((p, i) => (
                          <Badge key={i} variant="secondary">{p}</Badge>
