interface Adjustment {
  id: string;
  type: 'acceleration' | 'delay' | 'resource' | 'scope';
  taskId: string;
  taskName: string;
  field: string;
  originalValue: any;
  newValue: any;
  unit: string;
}

interface Scenario {
  id: string;
  name: string;
  description: string;
  status: 'active' | 'draft' | 'archived';
  createdDate: string;
  modifiedDate: string;
  author: string;
  adjustments: Adjustment[];
  impact: {
    endDateChange: number;
    costChange: number;
    riskLevel: 'low' | 'medium' | 'high';
    criticalPathAffected: boolean;
    tasksAffected: number;
  };
}

const mockTasks = [
  { id: 'T-010', name: 'System Architecture' },
  { id: 'T-011', name: 'Database Design' },
  { id: 'T-012', name: 'Wave 2 Migration' },
  { id: 'T-013', name: 'Data Migration' },
  { id: 'T-014', name: 'API Integration' },
  { id: 'T-015', name: 'Testing & Validation' },
];

export function ScenariosView() {
  const { settings } = useProjectContext();
  const {
    data: fetchedScenarios = [],
    isLoading,
    createScenario,
    updateScenario,
    deleteScenario,
    promoteScenario,
    isPromoting
  } = useScenarios(settings.id);

  /* State */
  const [scenarios, setScenarios] = useState<any[]>([]);
  const [selectedScenario, setSelectedScenario] = useState<any | null>(null);
  const [compareMode, setCompareMode] = useState(false);
  const [compareScenarioId, setCompareScenarioId] = useState<string | null>(null);
  const [showAdjustmentDialog, setShowAdjustmentDialog] = useState(false);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [newScenarioName, setNewScenarioName] = useState('');
  const [newScenarioDesc, setNewScenarioDesc] = useState('');
  const [isSimulating, setIsSimulating] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  /* Data Fetching */
  // Fetch all tasks for diffing (Base Plan)
  const { data: allTasks = [] } = useTasks(settings.id, null);
  // Fetch Scenario Plan tasks (only if selected)
  const { data: scenarioTasks = [] } = useTasks(settings.id, selectedScenario?.id || 'skip');

  /* Derived State */
  const compareScenario = scenarios.find(s => s.id === compareScenarioId);
  // Pseudo-baseline for visualization (defaults to 100% metrics)
  const baselineScenario = { name: 'Plan Baseline', impact: { endDateChange: 0, costChange: 0 } };

  /* User Profile for Author field */
  const { data: profile } = useProfile();

  // Sync state with fetched data
  useEffect(() => {
    if (fetchedScenarios) {
      const formatted = fetchedScenarios.map(s => {
        // Parse data field if it exists, otherwise default
        const meta = s.data || {};
        return {
          id: s.id,
          name: s.name,
          description: s.description,
          status: s.status,
          createdDate: new Date(s.created_at).toLocaleDateString(),
          modifiedDate: new Date(s.updated_at).toLocaleDateString(),
          author: profile?.full_name || 'User', // Wired to profile
          adjustments: meta.adjustments || [],
          impact: meta.impact || {
            endDateChange: 0,
            costChange: 0,
            riskLevel: 'low',
            criticalPathAffected: false,
            tasksAffected: 0
          }
        };
      });
      setScenarios(formatted);

      // Select first if none selected
      if (!selectedScenario && formatted.length > 0) {
        setSelectedScenario(formatted[0]);
      }
      // Update selected if it exists in new data
      else if (selectedScenario) {
        const found = formatted.find(s => s.id === selectedScenario.id);
        if (found) setSelectedScenario(found);
      }
    }
  }, [fetchedScenarios, profile]);

  const handleCreateScenario = async () => {
    if (!newScenarioName.trim()) return;

    setIsCreating(true);
    try {
      await createScenario({
        name: newScenarioName,
        description: newScenarioDesc
      });
      setShowCreateDialog(false);
      setNewScenarioName('');
      setNewScenarioDesc('');
    } catch (error) {
      toast.error("Failed to create scenario");
    } finally {
      setIsCreating(false);
    }
  };

  const handleDuplicateScenario = (scenario: Scenario) => {
    const duplicated: Scenario = {
      ...JSON.parse(JSON.stringify(scenario)),
      id: `S-${Date.now()}`,
      name: `${scenario.name} (Copy)`,
      status: 'draft',
      createdDate: new Date().toISOString().split('T')[0],
      modifiedDate: new Date().toISOString().split('T')[0]
    };
    setScenarios([...scenarios, duplicated]);
    setSelectedScenario(duplicated);
  };

  const generateAdjustments = (): Adjustment[] => {
    if (!selectedScenario || !allTasks.length || !scenarioTasks.length) return [];

    const adjustments: Adjustment[] = [];
    const baseMap = new Map(allTasks.map(t => [t.wbs, t])); // Match by WBS for now

    scenarioTasks.forEach(sTask => {
      const baseTask = baseMap.get(sTask.wbs);
      if (baseTask) {
        // Check for Duration/End Date Change
        if (sTask.duration !== baseTask.duration) {
          adjustments.push({
            id: `adj-${sTask.id}-dur`,
            type: sTask.duration > baseTask.duration ? 'delay' : 'acceleration',
            taskId: sTask.id,
            taskName: sTask.name,
            field: 'Duration',
            originalValue: baseTask.duration,
            newValue: sTask.duration,
            unit: 'days'
          });
        }
        // Check for Cost Change (Budget)
        if (sTask.budget !== baseTask.budget) {
          adjustments.push({
            id: `adj-${sTask.id}-cost`,
            type: 'resource', // prioritizing simple types
            taskId: sTask.id,
            taskName: sTask.name,
            field: 'Budget',
            originalValue: baseTask.budget || 0,
            newValue: sTask.budget,
            unit: 'USD'
          });
        }
      }
    });
    return adjustments;
  };

  const handleRunSimulation = async () => {
    if (!selectedScenario || !settings?.id) return;

    setIsSimulating(true);
    toast.info('Calculating impacts from your plan changes...');

    // 1. Calculate Adjustments from Diffs
    const calculatedAdjustments = generateAdjustments();

    // 2. Update Scenario with these adjustments (so they persist)
    // We update the 'data' field which holds adjustments and impact
    const updatedMetadata = {
      ...selectedScenario.data, // Preserve other possible metadata
      adjustments: calculatedAdjustments
    };

    const { data: impactData, error } = await aiService.simulateScenarios(settings.id, calculatedAdjustments);
    setIsSimulating(false);

    if (error) {
      toast.error('Simulation failed: ' + error);
    } else {
      const finalImpact = impactData || { endDateChange: 0, costChange: 0, riskLevel: 'low' };

      // Persist to DB
      try {
        await updateScenario({
          id: selectedScenario.id,
          updates: {
            data: {
              ...updatedMetadata,
              impact: finalImpact
            }
          }
        });

        toast.success('Simulation complete and saved!');

        // Optimistic UI update (though query invalidation in hook handles it)
        const updatedScenarioObj = {
          ...selectedScenario,
          adjustments: calculatedAdjustments,
          impact: finalImpact,
          modifiedDate: new Date().toISOString().split('T')[0]
        };
        setScenarios(scenarios.map(s => s.id === selectedScenario.id ? updatedScenarioObj : s));
        setSelectedScenario(updatedScenarioObj);

      } catch (err) {
        console.error("Failed to save simulation results", err);
        toast.warning("Simulation complete but failed to save results.");
      }
    }
  };

  return (
    <div className="p-6 h-full flex flex-col gap-6 overflow-hidden">
      <div className="flex items-center justify-between shrink-0">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Settings2 className="h-6 w-6 text-primary" />
            AI Scenario Builder
          </h1>
          <p className="text-muted-foreground italic">Project "What-If" Analysis & Impact Simulator</p>
        </div>
        <div className="flex items-center gap-3">
          <Button
            variant={compareMode ? "default" : "outline"}
            onClick={() => setCompareMode(!compareMode)}
            className="gap-2"
          >
            <BarChart3 className="h-4 w-4" />
            {compareMode ? "Disable Comparison" : "Compare Scenarios"}
          </Button>
          <Button onClick={() => setShowCreateDialog(true)} className="gap-2">
            <Plus className="h-4 w-4" />
            New Scenario
          </Button>
        </div>
      </div>

      <div className="flex-1 overflow-hidden">
        <Tabs defaultValue="simulation" className="h-full flex flex-col">
          <TabsList className="bg-muted/50 border-b rounded-none px-6 h-12 shrink-0">
            <TabsTrigger value="simulation" className="gap-2">
              <Sparkles className="h-4 w-4" />
              Impact Simulation
            </TabsTrigger>
            <TabsTrigger value="planning" className="gap-2">
              <Layout className="h-4 w-4" />
              Scenario Planner
            </TabsTrigger>
          </TabsList>

          <TabsContent value="simulation" className="flex-1 overflow-hidden m-0 p-6 pt-0">
            <div className="grid grid-cols-12 gap-6 h-full overflow-hidden mt-6">
              {/* Scenario List */}
              <Card className="col-span-12 lg:col-span-3 flex flex-col overflow-hidden">
                <CardHeader className="py-4 shrink-0 border-b">
                  <CardTitle className="text-base flex items-center justify-between">
                    Scenarios
                    <Badge variant="outline" className="font-normal">{scenarios.length}</Badge>
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-0 flex-1 overflow-hidden">
                  <ScrollArea className="h-full">
                    <div className="p-3 space-y-2">
                      {scenarios.map((scenario) => (
                        <div
                          key={scenario.id}
                          onClick={() => setSelectedScenario(scenario)}
                          className={cn(
                            "group p-3 rounded-lg border cursor-pointer transition-all hover:border-primary/50",
                            selectedScenario?.id === scenario.id ? "border-primary bg-primary/5 shadow-sm" : "bg-card"
                          )}
                        >
                          <div className="flex items-start justify-between mb-1">
                            <h3 className="text-sm font-semibold truncate">{scenario.name}</h3>
                            <Badge
                              variant={(scenario.status === 'active' ? 'success' : 'secondary') as any}
                              className="text-[10px] h-4 px-1"
                            >
                              {scenario.status}
                            </Badge>
                          </div>
                          <p className="text-[11px] text-muted-foreground line-clamp-2 mb-2">
                            {scenario.description}
                          </p>
                          <div className="flex items-center justify-between text-[10px] text-muted-foreground">
                            <span className="flex items-center gap-1">
                              <Calendar className="h-3 w-3" /> {scenario.modifiedDate}
                            </span>
                            <span className="flex items-center gap-1">
                              <Clock className="h-3 w-3" /> {scenario.adjustments.length} adjs
                            </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </ScrollArea>
                </CardContent>
              </Card>

              {/* Workspace */}
              <div className="col-span-12 lg:col-span-9 flex flex-col gap-6 overflow-hidden">
                {selectedScenario ? (
                  <>
                    {/* Scenario Detail Header */}
                    <div className="flex items-start justify-between shrink-0 bg-card p-4 rounded-xl border">
                      <div className="space-y-1">
                        <div className="flex items-center gap-3">
                          <h2 className="text-xl font-bold">{selectedScenario.name}</h2>
                          <Badge variant={(selectedScenario.status === 'active' ? 'success' : 'secondary') as any}>
                            {selectedScenario.status}
                          </Badge>
                        </div>
                        <p className="text-sm text-muted-foreground">{selectedScenario.description}</p>
                        <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground">
                          <span className="flex items-center gap-1.5"><Calendar className="h-3.5 w-3.5" /> Created: {selectedScenario.createdDate}</span>
                          <span className="flex items-center gap-1.5"><Clock className="h-3.5 w-3.5" /> Modified: {selectedScenario.modifiedDate}</span>
                          <span className="flex items-center gap-1.5"><Info className="h-3.5 w-3.5" /> Author: {selectedScenario.author}</span>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Button variant="outline" size="sm" onClick={() => handleDuplicateScenario(selectedScenario)} className="gap-2">
                          <Copy className="h-4 w-4" /> Duplicate
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          className="text-destructive hover:bg-destructive/10 gap-2 border-destructive/20"
                          onClick={() => {
                            if (confirm(`Delete scenario "${selectedScenario.name}"?`)) {
                              setScenarios(scenarios.filter(s => s.id !== selectedScenario.id));
                              setSelectedScenario(scenarios.find(s => s.id !== selectedScenario.id) || null);
                              toast.success('Scenario deleted');
                            }
                          }}
                        >
                          <Trash2 className="h-4 w-4" /> Delete
                        </Button>
                        <Button
                          variant="outline"
