import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { supabase } from '@/integrations/supabase/client';

export type Methodology = 'waterfall' | 'scrum' | 'kanban' | 'hybrid';

export interface ModuleVisibility {
  // Planning
  projectPlan: boolean;
  childPlans: boolean;
  gantt: boolean;
  childGantt: boolean;
  milestones: boolean;
  programTimeline: boolean;
  // Execution
  sprints: boolean;
  backlog: boolean;
  actions: boolean;
  issues: boolean;
  // Core
  dashboard: boolean;
  executiveDashboard: boolean;
  strategic: boolean;
  portfolio: boolean;
  traceability: boolean;
  meetings: boolean;
  communications: boolean;
  resources: boolean;
  risks: boolean;
  decisions: boolean;
  financials: boolean;
  notes: boolean;
  reports: boolean;
  presentations: boolean;
}

export interface ProjectSettings {
  id: string | null;
  name: string;
  code: string;
  startDate?: string;
  endDate?: string;
  methodology: Methodology;
  modules: ModuleVisibility;
  defaultView: string;
}

// ... (keep GlobalPanelType and ProjectContextType)



// ... (ProjectProvider logic)



export type GlobalPanelType = 'chat' | 'ai' | 'settings' | null;

interface ProjectContextType {
  settings: ProjectSettings;
  updateMethodology: (methodology: Methodology) => void;
  updateModuleVisibility: (module: keyof ModuleVisibility, visible: boolean) => void;
  updateSettings: (settings: Partial<ProjectSettings>) => void;
  isModuleVisible: (module: keyof ModuleVisibility) => boolean;
  getDefaultModules: (methodology: Methodology) => ModuleVisibility;
  loading: boolean;
  selectProject: (projectId: string) => void;
  activeGlobalPanel: GlobalPanelType;
  setActiveGlobalPanel: (panel: GlobalPanelType) => void;
}

const defaultModules: ModuleVisibility = {
  projectPlan: true,
  childPlans: true,
  gantt: true,
  childGantt: true,
  milestones: true,
  programTimeline: true,
  sprints: true,
  backlog: true,
  actions: true,
  issues: true,
  dashboard: true,
  executiveDashboard: true,
  strategic: true,
  portfolio: true,
  traceability: true,
  meetings: true,
  communications: true,
  resources: true,
  risks: true,
  decisions: true,
  financials: true,
  notes: true,
  reports: true,
  presentations: true,
};

const methodologyDefaults: Record<Methodology, Partial<ModuleVisibility>> = {
  waterfall: {
    sprints: false,
    backlog: false,
    gantt: true,
    projectPlan: true,
    milestones: true,
  },
  scrum: {
    sprints: true,
    backlog: true,
    gantt: false,
    projectPlan: true,
    milestones: true,
  },
  kanban: {
    sprints: false,
    backlog: true,
    gantt: false,
    projectPlan: true,
    milestones: false,
  },
  hybrid: {
    sprints: true,
    backlog: true,
    gantt: true,
    projectPlan: true,
    milestones: true,
  },
};

const defaultSettings: ProjectSettings = {
  id: null,
  name: 'No Project Selected',
  code: '',
  methodology: 'hybrid',
  modules: { ...defaultModules },
  defaultView: 'dashboard',
};



const ProjectContext = createContext<ProjectContextType | undefined>(undefined);

const STORAGE_KEY = 'kiroxys-settings';
const SELECTED_PROJECT_KEY = 'kiroxys-selected-project';

export function ProjectProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<ProjectSettings>(defaultSettings);
  const [loading, setLoading] = useState(true);
  const [activeGlobalPanel, setActiveGlobalPanel] = useState<GlobalPanelType>(null);

  // Load selected project on mount
  useEffect(() => {
    const loadProject = async () => {
      console.log('[ProjectContext] Starting to load project...');
      try {
        // First try to get stored project ID
        const storedProjectId = localStorage.getItem(SELECTED_PROJECT_KEY);
        console.log('[ProjectContext] Stored project ID:', storedProjectId);

        // Get the first available project or the stored one
        let query = supabase.from('projects').select('*');

        if (storedProjectId) {
          // Try to load the stored project first
          const { data: storedProject } = await supabase
            .from('projects')
            .select('*')
            .eq('id', storedProjectId)
            .maybeSingle();

          console.log('[ProjectContext] Stored project query result:', storedProject);

          if (storedProject) {
            const methodology = (storedProject.methodology || 'hybrid') as Methodology;
            setSettings({
              id: storedProject.id,
              name: storedProject.name,
              code: storedProject.code,
              startDate: storedProject.start_date,
              endDate: storedProject.end_date,
              methodology,
              modules: getDefaultModulesInternal(methodology),
              defaultView: methodology === 'waterfall' ? 'gantt' : methodology === 'scrum' ? 'sprints' : 'dashboard',
            });
            setLoading(false);
            console.log('[ProjectContext] Loaded stored project successfully');
            return;
          }
        }

        // Fall back to first available project
        const { data: projects } = await query.order('created_at', { ascending: false }).limit(1);
        console.log('[ProjectContext] First available project query result:', projects);

        if (projects && projects.length > 0) {
          const project = projects[0];
          const methodology = (project.methodology || 'hybrid') as Methodology;
          localStorage.setItem(SELECTED_PROJECT_KEY, project.id);
          setSettings({
            id: project.id,
            name: project.name,
            code: project.code,
            startDate: project.start_date,
            endDate: project.end_date,
            methodology,
            modules: getDefaultModulesInternal(methodology),
            defaultView: methodology === 'waterfall' ? 'gantt' : methodology === 'scrum' ? 'sprints' : 'dashboard',
          });
          console.log('[ProjectContext] Loaded first available project');
        } else {
          console.log('[ProjectContext] No projects found in database');
        }
      } catch (error) {
        console.error('[ProjectContext] Failed to load project:', error);
      } finally {
        setLoading(false);
        console.log('[ProjectContext] Loading complete');
      }
    };

    loadProject();
  }, []);

  const getDefaultModulesInternal = (methodology: Methodology): ModuleVisibility => {
    return {
      ...defaultModules,
      ...methodologyDefaults[methodology],
    };
  };

  const getDefaultModules = (methodology: Methodology): ModuleVisibility => {
    return getDefaultModulesInternal(methodology);
  };

  const selectProject = async (projectId: string) => {
    try {
      const { data: project, error } = await supabase
        .from('projects')
        .select('*')
        .eq('id', projectId)
        .single();

      if (error) throw error;

      const methodology = (project.methodology || 'hybrid') as Methodology;
      localStorage.setItem(SELECTED_PROJECT_KEY, project.id);
      setSettings({
        id: project.id,
        name: project.name,
        code: project.code,
        startDate: project.start_date,
        endDate: project.end_date,
        methodology,
        modules: getDefaultModulesInternal(methodology),
        defaultView: methodology === 'waterfall' ? 'gantt' : methodology === 'scrum' ? 'sprints' : 'dashboard',
      });
    } catch (error) {
      console.error('Failed to select project:', error);
    }
  };

  const updateMethodology = (methodology: Methodology) => {
    const newModules = getDefaultModulesInternal(methodology);
    setSettings((prev) => ({
      ...prev,
      methodology,
      modules: newModules,
      defaultView: methodology === 'waterfall' ? 'gantt' : methodology === 'scrum' ? 'sprints' : 'dashboard',
    }));
  };

  const updateModuleVisibility = (module: keyof ModuleVisibility, visible: boolean) => {
    setSettings((prev) => ({
      ...prev,
      modules: {
        ...prev.modules,
        [module]: visible,
      },
    }));
  };

  const updateSettings = (newSettings: Partial<ProjectSettings>) => {
    setSettings((prev) => ({
      ...prev,
      ...newSettings,
    }));
  };

  const isModuleVisible = (module: keyof ModuleVisibility): boolean => {
    return settings.modules[module] ?? true;
  };

  return (
    <ProjectContext.Provider
      value={{
        settings,
        updateMethodology,
        updateModuleVisibility,
        updateSettings,
        isModuleVisible,
        getDefaultModules,
        loading,
        selectProject,
        activeGlobalPanel,
        setActiveGlobalPanel,
      }}
    >
      {children}
    </ProjectContext.Provider>
  );
}

export function useProjectContext() {
  const context = useContext(ProjectContext);
  if (!context) {
    throw new Error('useProjectContext must be used within a ProjectProvider');
  }
  return context;
}

import { useState, useCallback, useEffect, useRef } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from './useAuth';
import { toast } from 'sonner';
import type {
  AIMessage,
  AIConversation,
  AIOrchestratorResponse,
  AgentType,
  ClarifyingQuestion,
} from '@/types/ai-agents';

export type IntentMode = 'plan' | 'action';

interface UseAIChatOptions {
  projectId: string | null;
  currentView?: string;
  intentMode?: IntentMode;
  onNewMessage?: (message: AIMessage) => void;
}

interface UseAIChatReturn {
  messages: AIMessage[];
  conversations: AIConversation[];
  activeConversationId: string | null;
  isLoading: boolean;
  isSending: boolean;
  currentAgent: AgentType | null;
  pendingClarification: ClarifyingQuestion | null;

  // Actions
  sendMessage: (content: string) => Promise<void>;
  createConversation: () => Promise<string | null>;
  selectConversation: (conversationId: string) => void;
  deleteConversation: (conversationId: string) => Promise<void>;
  clearMessages: () => void;
  clearClarification: () => void;
}

export function useAIChat({ 
  projectId, 
  currentView = 'dashboard', 
  intentMode = 'plan',
  onNewMessage 
}: UseAIChatOptions): UseAIChatReturn {
  const { user } = useAuth();
  const [messages, setMessages] = useState<AIMessage[]>([]);
  const [conversations, setConversations] = useState<AIConversation[]>([]);
  const [activeConversationId, setActiveConversationId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [currentAgent, setCurrentAgent] = useState<AgentType | null>(null);
  const [pendingClarification, setPendingClarification] = useState<ClarifyingQuestion | null>(null);
  const onNewMessageRef = useRef(onNewMessage);
  onNewMessageRef.current = onNewMessage;

  // Fetch conversations for the project
  useEffect(() => {
    if (!projectId) {
      setConversations([]);
      return;
    }

    const fetchConversations = async () => {
      // Check if user is authenticated
      const { data: { user: currentUser } } = await supabase.auth.getUser();
      if (!currentUser) {
        setConversations([]);
        return;
      }

      const { data, error } = await supabase
        .from('ai_conversations')
        .select('*')
        .eq('project_id', projectId)
        .eq('user_id', currentUser.id)
        .order('updated_at', { ascending: false });

      if (error) {
        console.error('Error fetching conversations:', error);
      } else {
        setConversations((data || []) as AIConversation[]);

        // Auto-select most recent conversation or create new one
        if (data && data.length > 0 && !activeConversationId) {
          setActiveConversationId(data[0].id);
        }
      }
    };

    fetchConversations();
  }, [projectId, user?.id]);

  // Fetch messages when conversation changes
  useEffect(() => {
    if (!activeConversationId) {
      setMessages([]);
      return;
    }

    const fetchMessages = async () => {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('ai_messages')
        .select('*')
        .eq('conversation_id', activeConversationId)
        .order('created_at', { ascending: true });

      if (error) {
        console.error('Error fetching messages:', error);
      } else {
        setMessages((data || []) as AIMessage[]);
      }
      setIsLoading(false);
    };

    fetchMessages();
  }, [activeConversationId]);

  // Subscribe to realtime message updates
  useEffect(() => {
    if (!activeConversationId) return;

    const channel = supabase
      .channel(`ai_messages:${activeConversationId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'ai_messages',
          filter: `conversation_id=eq.${activeConversationId}`,
        },
        (payload) => {
          const newMsg = payload.new as AIMessage;
          setMessages((prev) => {
            // Avoid duplicates
            if (prev.some((m) => m.id === newMsg.id)) return prev;
            return [...prev, newMsg];
          });
          onNewMessageRef.current?.(newMsg);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [activeConversationId]);

  // Create a new conversation
  const createConversation = useCallback(async (): Promise<string | null> => {
    if (!projectId) return null;

    // Get current user
    const { data: { user: currentUser } } = await supabase.auth.getUser();
    if (!currentUser) {
      toast.error('Please sign in to use AI Assistant');
      return null;
    }

    const { data, error } = await supabase
      .from('ai_conversations')
      .insert({
        project_id: projectId,
        user_id: currentUser.id,
        title: 'New Conversation',
      })
      .select()
      .single();

    if (error) {
      console.error('Error creating conversation:', error);
      toast.error('Failed to create conversation');
      return null;
    }

    const newConversation = data as AIConversation;
    setConversations((prev) => [newConversation, ...prev]);
    setActiveConversationId(newConversation.id);
    setMessages([]);

    return newConversation.id;
  }, [projectId]);

  // Select a conversation
  const selectConversation = useCallback((conversationId: string) => {
    setActiveConversationId(conversationId);
  }, []);

  // Delete a conversation
  const deleteConversation = useCallback(async (conversationId: string) => {
    const { error } = await supabase
      .from('ai_conversations')
      .delete()
      .eq('id', conversationId);

    if (error) {
      console.error('Error deleting conversation:', error);
      toast.error('Failed to delete conversation');
      return;
    }

    setConversations((prev) => prev.filter((c) => c.id !== conversationId));

    if (activeConversationId === conversationId) {
      setActiveConversationId(null);
      setMessages([]);
    }

    toast.success('Conversation deleted');
  }, [activeConversationId]);

  // Send a message
  const sendMessage = useCallback(async (content: string) => {
    if (!content.trim() || !projectId) return;

    let conversationId = activeConversationId;

    // Create conversation if none exists
    if (!conversationId) {
      conversationId = await createConversation();
      if (!conversationId) return;
    }

    setIsSending(true);
    setCurrentAgent(null);

    // Optimistically add user message
    const tempUserMessage: AIMessage = {
      id: `temp-${Date.now()}`,
      conversation_id: conversationId,
      role: 'user',
      content,
      created_at: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, tempUserMessage]);

    try {
      // Insert user message to DB
      const { data: userMsgData, error: userMsgError } = await supabase
        .from('ai_messages')
        .insert({
          conversation_id: conversationId,
          role: 'user',
          content,
        })
        .select()
        .single();

      if (userMsgError) throw userMsgError;

      // Replace temp message with real one
      setMessages((prev) => 
        prev.map((m) => m.id === tempUserMessage.id ? (userMsgData as AIMessage) : m)
      );

      // Build conversation history for context
      const conversationHistory = messages
        .filter((m) => m.role !== 'system')
        .slice(-10)
        .map((m) => ({ role: m.role as 'user' | 'assistant', content: m.content }));

      // Call the orchestrator with context and intent mode
      const response = await supabase.functions.invoke('ai-orchestrator', {
        body: {
          message: content,
          projectId,
          conversationId,
          conversationHistory,
          currentView,
          intentMode,
        },
      });

      if (response.error) {
        throw new Error(response.error.message || 'Failed to get AI response');
      }

      const aiResponse = response.data as AIOrchestratorResponse;
      setCurrentAgent(aiResponse.agentType);

      // Check if AI needs clarification
      if (aiResponse.needsClarification && aiResponse.clarifyingQuestion) {
        setPendingClarification(aiResponse.clarifyingQuestion);
      }

      // Insert assistant message
      const { error: assistantError } = await supabase
        .from('ai_messages')
        .insert({
          conversation_id: conversationId,
          role: 'assistant' as const,
          content: aiResponse.response,
          agent_type: aiResponse.agentType,
          metadata: {
            intent: aiResponse.intent,
            confidence: aiResponse.confidence,
            executionTime: aiResponse.executionTime,
            agentsUsed: aiResponse.agentsUsed,
            actions: aiResponse.actions,
            permissionDenied: aiResponse.permissionDenied,
            needsClarification: aiResponse.needsClarification,
            clarifyingQuestion: aiResponse.clarifyingQuestion,
          } as unknown as Record<string, unknown>,
        } as any);

      if (assistantError) {
        console.error('Error saving assistant message:', assistantError);
      }

      // Update conversation title based on first message
      if (messages.length === 0) {
        const title = content.length > 50 ? content.substring(0, 47) + '...' : content;
        await supabase
          .from('ai_conversations')
          .update({ title, updated_at: new Date().toISOString() })
          .eq('id', conversationId);

        setConversations((prev) =>
          prev.map((c) => c.id === conversationId ? { ...c, title } : c)
        );
      }

    } catch (error) {
      console.error('Error sending message:', error);
      toast.error('Failed to get AI response');

      // Remove optimistic message on error
      setMessages((prev) => prev.filter((m) => m.id !== tempUserMessage.id));
    } finally {
      setIsSending(false);
    }
  }, [projectId, activeConversationId, messages, createConversation]);

  // Clear messages (for UI reset)
  const clearMessages = useCallback(() => {
    setMessages([]);
    setActiveConversationId(null);
    setPendingClarification(null);
  }, []);

  // Clear pending clarification
  const clearClarification = useCallback(() => {
    setPendingClarification(null);
  }, []);

  return {
    messages,
    conversations,
    activeConversationId,
    isLoading,
    isSending,
    currentAgent,
    pendingClarification,
    sendMessage,
    createConversation,
    selectConversation,
    deleteConversation,
    clearMessages,
    clearClarification,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type ActionStatus = 'pending' | 'in-progress' | 'completed' | 'deferred' | 'cancelled';
export type ActionPriority = 'critical' | 'high' | 'medium' | 'low';

export interface Action { id: string; project_id: string | null; title: string; description: string | null; priority: ActionPriority; status: ActionStatus; owner_id: string | null; owner_name: string | null; created_by_id: string | null; created_by_name: string | null; due_date: string | null; completed_at: string | null; progress: number; notes: string | null; source_type: string | null; source_id: string | null; source_title: string | null; linked_items: any[]; dependencies: any[]; blocked_by: string | null; tags: string[]; sla_target_hours: number | null; sla_started_at: string | null; sla_breached: boolean; sla_breached_at: string | null; history: any[]; created_at: string; updated_at: string; }
export interface ActionInput { title: string; description?: string; priority?: ActionPriority; status?: ActionStatus; owner_name?: string; created_by_name?: string; due_date?: string; progress?: number; notes?: string; source_type?: string; source_id?: string; source_title?: string; tags?: string[]; sla_target_hours?: number; }

export function useActions() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [actions, setActions] = useState<Action[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchActions = useCallback(async () => {
    if (!projectId) { setActions([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('actions').select('*').eq('project_id', projectId).order('created_at', { ascending: false });
      if (e) throw e;
      setActions((data || []).map((a: any) => ({ ...a, priority: a.priority as ActionPriority, status: a.status as ActionStatus, linked_items: Array.isArray(a.linked_items) ? a.linked_items : [], dependencies: Array.isArray(a.dependencies) ? a.dependencies : [], tags: Array.isArray(a.tags) ? a.tags : [], history: Array.isArray(a.history) ? a.history : [] })));
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchActions(); }, [fetchActions]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('actions-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'actions', filter: `project_id=eq.${projectId}` }, () => fetchActions()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchActions]);

  const createAction = async (input: ActionInput): Promise<Action | null> => {
    if (!projectId) { toast.error('No project selected'); return null; }
    try {
      const now = new Date().toISOString();
      const { data, error: e } = await supabase.from('actions').insert({ project_id: projectId, title: input.title, description: input.description || null, priority: input.priority || 'medium', status: input.status || 'pending', owner_name: input.owner_name || null, created_by_name: input.created_by_name || null, due_date: input.due_date || null, progress: input.progress || 0, notes: input.notes || null, source_type: input.source_type || 'manual', source_id: input.source_id || null, source_title: input.source_title || null, tags: input.tags || [], sla_target_hours: input.sla_target_hours || null, sla_started_at: input.sla_target_hours ? now : null, history: [{ timestamp: now, user: input.created_by_name || 'System', action: 'Created action' }] }).select().single();
      if (e) throw e;
      const action: Action = { ...data, priority: data.priority as ActionPriority, status: data.status as ActionStatus, linked_items: Array.isArray(data.linked_items) ? data.linked_items : [], dependencies: Array.isArray(data.dependencies) ? data.dependencies : [], tags: (Array.isArray(data.tags) ? data.tags : []).map(String), history: Array.isArray(data.history) ? data.history : [] };
      toast.success('Action created'); return action;
    } catch { toast.error('Failed to create action'); return null; }
  };

  const updateAction = async (id: string, updates: Partial<ActionInput & { blocked_by?: string }>) => {
    try {
      const action = actions.find(a => a.id === id);
      const updateData: any = { ...updates };
      if (updates.status === 'completed' && action?.status !== 'completed') { updateData.completed_at = new Date().toISOString(); updateData.progress = 100; }
      if (updates.sla_target_hours && !action?.sla_started_at) updateData.sla_started_at = new Date().toISOString();
      const { error: e } = await supabase.from('actions').update(updateData).eq('id', id);
      if (e) throw e; toast.success('Action updated'); return true;
    } catch { toast.error('Failed to update action'); return false; }
  };

  const deleteAction = async (id: string) => { try { await supabase.from('actions').delete().eq('id', id); toast.success('Action deleted'); return true; } catch { toast.error('Failed'); return false; } };

  const pendingActions = actions.filter(a => a.status === 'pending');
  const inProgressActions = actions.filter(a => a.status === 'in-progress');
  const completedActions = actions.filter(a => a.status === 'completed');
  const slaBreachedActions = actions.filter(a => a.sla_breached);
  const overdueActions = actions.filter(a => a.due_date && new Date(a.due_date) < new Date() && a.status !== 'completed' && a.status !== 'cancelled');

  return { actions, loading, error, refetch: fetchActions, createAction, updateAction, deleteAction, pendingActions, inProgressActions, completedActions, slaBreachedActions, overdueActions };
}

