      if (error) throw error;
    } catch (error) {
      console.error('Error updating section:', error);
      toast({ title: 'Error', description: 'Failed to update section', variant: 'destructive' });
    }
  };

  const deleteSection = async (id: string) => {
    try {
      const { error } = await supabase
        .from('notebook_sections')
        .delete()
        .eq('id', id);

      if (error) throw error;
      toast({ title: 'Section deleted' });
    } catch (error) {
      console.error('Error deleting section:', error);
      toast({ title: 'Error', description: 'Failed to delete section', variant: 'destructive' });
    }
  };

  useEffect(() => {
    fetchSections();
  }, [notebookId]);

  // Subscribe to realtime updates
  useEffect(() => {
    if (!notebookId || !isValidUuid(notebookId)) return;

    const channel = supabase
      .channel(`sections-${notebookId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'notebook_sections',
          filter: `notebook_id=eq.${notebookId}`,
        },
        () => {
          fetchSections();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [notebookId]);

  return {
    sections,
    loading,
    createSection,
    updateSection,
    deleteSection,
    refetch: fetchSections,
  };
}

export function usePages(sectionId: string | null) {
  const [pages, setPages] = useState<NotebookPage[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  const isValidUuid = (id: string | null | undefined): boolean => {
    if (!id) return false;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id);
  };

  const fetchPages = async () => {
    if (!sectionId || !isValidUuid(sectionId)) {
      setPages([]);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('notebook_pages')
        .select('*')
        .eq('section_id', sectionId)
        .order('is_pinned', { ascending: false })
        .order('sort_order', { ascending: true });

      if (error) throw error;
      setPages(data || []);
    } catch (error) {
      console.error('Error fetching pages:', error);
    } finally {
      setLoading(false);
    }
  };

  const createPage = async (title = 'Untitled') => {
    if (!sectionId || !isValidUuid(sectionId)) return null;

    try {
      const { data, error } = await supabase
        .from('notebook_pages')
        .insert({
          section_id: sectionId,
          title,
          content: '',
          sort_order: pages.length,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    } catch (error) {
      console.error('Error creating page:', error);
      toast({ title: 'Error', description: 'Failed to create page', variant: 'destructive' });
      return null;
    }
  };

  const updatePage = async (id: string, updates: Partial<NotebookPage>) => {
    try {
      const { error } = await supabase
        .from('notebook_pages')
        .update(updates)
        .eq('id', id);

      if (error) throw error;
    } catch (error) {
      console.error('Error updating page:', error);
      toast({ title: 'Error', description: 'Failed to save page', variant: 'destructive' });
    }
  };

  const deletePage = async (id: string) => {
    try {
      const { error } = await supabase
        .from('notebook_pages')
        .delete()
        .eq('id', id);

      if (error) throw error;
      toast({ title: 'Page deleted' });
    } catch (error) {
      console.error('Error deleting page:', error);
      toast({ title: 'Error', description: 'Failed to delete page', variant: 'destructive' });
    }
  };

  useEffect(() => {
    fetchPages();
  }, [sectionId]);

  // Subscribe to realtime updates
  useEffect(() => {
    if (!sectionId || !isValidUuid(sectionId)) return;

    const channel = supabase
      .channel(`pages-${sectionId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'notebook_pages',
          filter: `section_id=eq.${sectionId}`,
        },
        () => {
          fetchPages();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [sectionId]);

  return {
    pages,
    loading,
    createPage,
    updatePage,
    deletePage,
    refetch: fetchPages,
  };
}

export function useAllPages(projectId: string | null) {
  const [allPages, setAllPages] = useState<(NotebookPage & { section_name?: string; notebook_name?: string })[]>([]);
  const [loading, setLoading] = useState(true);

  const isValidUuid = (id: string | null | undefined): boolean => {
    if (!id) return false;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id);
  };

  const fetchAllPages = async () => {
    if (!projectId || !isValidUuid(projectId)) {
      setAllPages([]);
      setLoading(false);
      return;
    }

    try {
      // First get all notebooks for this project
      const { data: notebooks, error: nbError } = await supabase
        .from('notebooks')
        .select('id, name')
        .eq('project_id', projectId);

      if (nbError) throw nbError;

      if (!notebooks || notebooks.length === 0) {
        setAllPages([]);
        setLoading(false);
        return;
      }

      // Get all sections for these notebooks
      const { data: sections, error: secError } = await supabase
        .from('notebook_sections')
        .select('id, name, notebook_id')
        .in('notebook_id', notebooks.map(n => n.id));

      if (secError) throw secError;

      if (!sections || sections.length === 0) {
        setAllPages([]);
        setLoading(false);
        return;
      }

      // Get all pages for these sections
      const { data: pages, error: pageError } = await supabase
        .from('notebook_pages')
        .select('*')
        .in('section_id', sections.map(s => s.id))
        .order('updated_at', { ascending: false });

      if (pageError) throw pageError;

      // Enrich pages with section and notebook names
      const enrichedPages = (pages || []).map(page => {
        const section = sections.find(s => s.id === page.section_id);
        const notebook = notebooks.find(n => n.id === section?.notebook_id);
        return {
          ...page,
          section_name: section?.name,
          notebook_name: notebook?.name,
        };
      });

      setAllPages(enrichedPages);
    } catch (error) {
      console.error('Error fetching all pages:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAllPages();
  }, [projectId]);

  return { allPages, loading, refetch: fetchAllPages };
}

export function usePageLinks(pageId: string | null) {
  const [outgoingLinks, setOutgoingLinks] = useState<PageLink[]>([]);
  const [incomingLinks, setIncomingLinks] = useState<PageLink[]>([]);
  const [loading, setLoading] = useState(true);

  const isValidUuid = (id: string | null | undefined): boolean => {
    if (!id) return false;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id);
  };

  const fetchLinks = async () => {
    if (!pageId || !isValidUuid(pageId)) {
      setOutgoingLinks([]);
      setIncomingLinks([]);
      setLoading(false);
      return;
    }

    try {
      const [outgoing, incoming] = await Promise.all([
        supabase
          .from('notebook_page_links')
          .select('*')
          .eq('source_page_id', pageId),
        supabase
          .from('notebook_page_links')
          .select('*')
          .eq('target_page_id', pageId),
      ]);

      if (outgoing.error) throw outgoing.error;
      if (incoming.error) throw incoming.error;

      setOutgoingLinks(outgoing.data || []);
      setIncomingLinks(incoming.data || []);
    } catch (error) {
      console.error('Error fetching page links:', error);
    } finally {
      setLoading(false);
    }
  };

  const createLink = async (targetPageId: string, linkText?: string) => {
    if (!pageId || !isValidUuid(pageId)) return;

    try {
      const { error } = await supabase
        .from('notebook_page_links')
        .insert({
          source_page_id: pageId,
          target_page_id: targetPageId,
          link_text: linkText,
        });

      if (error && !error.message.includes('duplicate')) throw error;
      fetchLinks();
    } catch (error) {
      console.error('Error creating link:', error);
    }
  };

  const deleteLink = async (linkId: string) => {
    try {
      const { error } = await supabase
        .from('notebook_page_links')
        .delete()
        .eq('id', linkId);

      if (error) throw error;
      fetchLinks();
    } catch (error) {
      console.error('Error deleting link:', error);
    }
  };

  useEffect(() => {
    fetchLinks();
  }, [pageId]);

  return { outgoingLinks, incomingLinks, loading, createLink, deleteLink };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

export type ReportType = 'status' | 'financial' | 'resource' | 'risk' | 'custom';
export type ReportCategory = 'Status' | 'Financial' | 'Resource' | 'Risk' | 'Custom';
export type ReportFrequency = 'daily' | 'weekly' | 'monthly' | 'on-demand';

export interface Report {
    id: string;
    project_id: string;
    name: string;
    description: string | null;
    type: ReportType;
    category: ReportCategory;
    frequency: ReportFrequency | null;
    last_generated: string | null;
    next_run: string | null;
    is_scheduled: boolean;
    config: any;
    created_at: string;
    updated_at: string;
}

export function useReports(projectId: string | null) {
    const queryClient = useQueryClient();

    const query = useQuery({
        queryKey: ['reports', projectId],
        queryFn: async () => {
            if (!projectId) return [];

            const { data, error } = await supabase
                .from('reports')
                .select('*')
                .eq('project_id', projectId)
                .order('name');

            if (error) {
                toast.error('Failed to fetch reports');
                throw error;
            }

            return data as Report[];
        },
        enabled: !!projectId,
    });

    const createReport = useMutation({
        mutationFn: async (newReport: Partial<Report>) => {
            if (!projectId) throw new Error('Project ID is required');

            const { data, error } = await supabase
                .from('reports')
                .insert([{ ...newReport, project_id: projectId }])
                .select()
                .single();

            if (error) throw error;
            return data;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['reports', projectId] });
            toast.success('Report created successfully');
        },
        onError: (error) => {
            toast.error(`Failed to create report: ${error.message}`);
        },
    });

    const updateReport = useMutation({
        mutationFn: async ({ id, updates }: { id: string; updates: Partial<Report> }) => {
            const { data, error } = await supabase
                .from('reports')
                .update(updates)
                .eq('id', id)
                .select()
                .single();

            if (error) throw error;
            return data;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['reports', projectId] });
            toast.success('Report updated successfully');
        },
        onError: (error) => {
            toast.error(`Failed to update report: ${error.message}`);
        },
    });

    const deleteReport = useMutation({
        mutationFn: async (id: string) => {
            const { error } = await supabase
                .from('reports')
                .delete()
                .eq('id', id);

            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['reports', projectId] });
            toast.success('Report deleted successfully');
        },
        onError: (error) => {
            toast.error(`Failed to delete report: ${error.message}`);
        },
    });

    return {
        ...query,
        createReport,
        updateReport,
        deleteReport,
    };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type RiskLevel = 'low' | 'medium' | 'high' | 'critical';
export type RiskStatus = 'identified' | 'analyzing' | 'mitigating' | 'closed' | 'accepted';

export interface Risk { id: string; project_id: string | null; title: string; description: string | null; category: string | null; probability: RiskLevel; impact: RiskLevel; status: RiskStatus; owner_id: string | null; owner_name: string | null; mitigation_plan: string | null; contingency_plan: string | null; triggers: string | null; linked_items: any[]; due_date: string | null; created_at: string; updated_at: string; closed_at: string | null; }
export interface RiskInput { title: string; description?: string; category?: string; probability?: RiskLevel; impact?: RiskLevel; status?: RiskStatus; owner_name?: string; mitigation_plan?: string; contingency_plan?: string; triggers?: string; due_date?: string; }

export function useRisks() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [risks, setRisks] = useState<Risk[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchRisks = useCallback(async () => {
    if (!projectId) { setRisks([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('risks').select('*').eq('project_id', projectId).order('created_at', { ascending: false });
      if (e) throw e;
      setRisks((data || []).map((r: any) => ({ ...r, probability: r.probability as RiskLevel, impact: r.impact as RiskLevel, status: r.status as RiskStatus, linked_items: Array.isArray(r.linked_items) ? r.linked_items : [] })));
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchRisks(); }, [fetchRisks]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('risks-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'risks', filter: `project_id=eq.${projectId}` }, () => fetchRisks()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchRisks]);

  const createRisk = async (input: RiskInput): Promise<Risk | null> => {
    if (!projectId) { toast.error('No project selected'); return null; }
    try {
      const { data, error: e } = await supabase.from('risks').insert({ project_id: projectId, title: input.title, description: input.description || null, category: input.category || null, probability: input.probability || 'medium', impact: input.impact || 'medium', status: input.status || 'identified', owner_name: input.owner_name || null, mitigation_plan: input.mitigation_plan || null, contingency_plan: input.contingency_plan || null, triggers: input.triggers || null, due_date: input.due_date || null }).select().single();
      if (e) throw e;
      const risk: Risk = { ...data, probability: data.probability as RiskLevel, impact: data.impact as RiskLevel, status: data.status as RiskStatus, linked_items: Array.isArray(data.linked_items) ? data.linked_items : [] };
      toast.success('Risk created'); return risk;
    } catch { toast.error('Failed to create risk'); return null; }
  };

  const updateRisk = async (id: string, updates: Partial<RiskInput>) => {
    try {
      const updateData: any = { ...updates };
      if (updates.status === 'closed') updateData.closed_at = new Date().toISOString();
      const { error: e } = await supabase.from('risks').update(updateData).eq('id', id);
      if (e) throw e; toast.success('Risk updated'); return true;
    } catch { toast.error('Failed to update risk'); return false; }
  };

  const deleteRisk = async (id: string) => { try { await supabase.from('risks').delete().eq('id', id); toast.success('Risk deleted'); return true; } catch { toast.error('Failed'); return false; } };

  const criticalRisks = risks.filter(r => r.impact === 'critical' || r.probability === 'critical');
  const openRisks = risks.filter(r => r.status !== 'closed');
  const mitigatingRisks = risks.filter(r => r.status === 'mitigating');

  return { risks, loading, error, refetch: fetchRisks, createRisk, updateRisk, deleteRisk, criticalRisks, openRisks, mitigatingRisks };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import type { Json } from '@/integrations/supabase/types';

export interface SlideShape {
  id: string;
  type: 'rectangle' | 'circle' | 'triangle' | 'arrow' | 'line' | 'star' | 'callout';
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  fill: string;
  stroke: string;
  strokeWidth: number;
  zIndex: number;
}

export interface SlideImage {
  id: string;
  url: string;
  x: number;
  y: number;
  width: number;
  height: number;
  alt: string;
}

export interface SlideChart {
  id: string;
  type: 'bar' | 'line' | 'pie' | 'donut' | 'area';
  dataSource: string;
  title: string;
}

export interface PresentationSlide {
  id: string;
  presentation_id: string;
  title: string;
  template: string;
  content: Record<string, unknown>;
  html_content: string;
  speaker_notes: string;
  transition: {
    type: string;
    duration: number;
    direction?: string;
  };
  background: {
    type: 'solid' | 'gradient' | 'image';
    color?: string;
    gradient?: string;
    imageUrl?: string;
  };
  shapes: SlideShape[];
  images: SlideImage[];
  charts: SlideChart[];
  embedded_components?: Array<{
    id: string;
    componentId: string;
    componentType: string;
    sourceModule: string;
    position: { x: number; y: number; width: number; height: number };
    dataSnapshot: Record<string, unknown> | null;
    snapshotAt: string | null;
    isLive: boolean;
  }>;
  sort_order: number;
  created_at: string;
  updated_at: string;
}

interface RawSlide {
  id: string;
  presentation_id: string;
  title: string;
  template: string;
  content: Json;
  html_content: string;
  speaker_notes: string;
  transition: Json;
  background: Json;
  shapes: Json;
  images: Json;
  charts: Json;
  embedded_components: Json;
  sort_order: number;
  created_at: string;
  updated_at: string;
}

const parseSlide = (raw: RawSlide): PresentationSlide => ({
  ...raw,
  content: (raw.content as Record<string, unknown>) || {},
  transition: (raw.transition as PresentationSlide['transition']) || { type: 'fade', duration: 0.5 },
  background: (raw.background as PresentationSlide['background']) || { type: 'solid', color: '#ffffff' },
  shapes: (Array.isArray(raw.shapes) ? raw.shapes : []) as unknown as SlideShape[],
  images: (Array.isArray(raw.images) ? raw.images : []) as unknown as SlideImage[],
  charts: (Array.isArray(raw.charts) ? raw.charts : []) as unknown as SlideChart[],
  embedded_components: (Array.isArray(raw.embedded_components) ? raw.embedded_components : []) as unknown as PresentationSlide['embedded_components'],
});

export function useSlides(presentationId: string | undefined) {
  const [slides, setSlides] = useState<PresentationSlide[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();
  const saveTimeoutRef = useRef<NodeJS.Timeout>();

  const fetchSlides = useCallback(async () => {
    if (!presentationId) return;

    try {
      const { data, error } = await supabase
        .from('presentation_slides')
        .select('*')
        .eq('presentation_id', presentationId)
        .order('sort_order', { ascending: true });

      if (error) throw error;
      setSlides((data as RawSlide[]).map(parseSlide));
    } catch (error) {
      console.error('Error fetching slides:', error);
      toast({
        title: 'Error',
        description: 'Failed to load slides',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  }, [presentationId, toast]);

  useEffect(() => {
    fetchSlides();

    if (!presentationId) return;

    const channel = supabase
      .channel(`slides-${presentationId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'presentation_slides',
          filter: `presentation_id=eq.${presentationId}`,
        },
        () => {
          fetchSlides();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [presentationId, fetchSlides]);

  const createSlide = async (
    template: string = 'blank',
    title: string = 'New Slide',
    content: Record<string, unknown> = {}
  ): Promise<PresentationSlide | null> => {
    if (!presentationId) return null;

    try {
      const maxOrder = slides.reduce((max, s) => Math.max(max, s.sort_order), -1);

      const insertData = {
        presentation_id: presentationId,
        title,
        template,
        content: content as unknown as Json,
        sort_order: maxOrder + 1,
      };

      const { data, error } = await supabase
        .from('presentation_slides')
        .insert(insertData)
        .select()
        .single();

      if (error) throw error;

      return parseSlide(data as RawSlide);
    } catch (error) {
      console.error('Error creating slide:', error);
      toast({
        title: 'Error',
        description: 'Failed to create slide',
        variant: 'destructive',
      });
      return null;
    }
  };

  const updateSlide = async (
    id: string,
    updates: Partial<Omit<PresentationSlide, 'id' | 'presentation_id' | 'created_at'>>
  ): Promise<boolean> => {
    try {
      const dbUpdates: Record<string, unknown> = {
        updated_at: new Date().toISOString(),
      };

      if (updates.title !== undefined) dbUpdates.title = updates.title;
      if (updates.template !== undefined) dbUpdates.template = updates.template;
      if (updates.content !== undefined) dbUpdates.content = updates.content as unknown as Json;
      if (updates.html_content !== undefined) dbUpdates.html_content = updates.html_content;
      if (updates.speaker_notes !== undefined) dbUpdates.speaker_notes = updates.speaker_notes;
      if (updates.transition !== undefined) dbUpdates.transition = updates.transition as unknown as Json;
      if (updates.background !== undefined) dbUpdates.background = updates.background as unknown as Json;
      if (updates.shapes !== undefined) dbUpdates.shapes = updates.shapes as unknown as Json;
      if (updates.images !== undefined) dbUpdates.images = updates.images as unknown as Json;
      if (updates.charts !== undefined) dbUpdates.charts = updates.charts as unknown as Json;
      if (updates.sort_order !== undefined) dbUpdates.sort_order = updates.sort_order;

      const { error } = await supabase
        .from('presentation_slides')
        .update(dbUpdates)
        .eq('id', id);

      if (error) throw error;

      return true;
    } catch (error) {
      console.error('Error updating slide:', error);
      toast({
        title: 'Error',
        description: 'Failed to update slide',
        variant: 'destructive',
      });
      return false;
    }
  };

  // Debounced save for auto-save functionality
  const saveSlideDebounced = useCallback((id: string, updates: Partial<PresentationSlide>) => {
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
    }

    saveTimeoutRef.current = setTimeout(() => {
      updateSlide(id, updates);
    }, 1000);
  }, []);

  const deleteSlide = async (id: string): Promise<boolean> => {
    try {
      const slideToDelete = slides.find(s => s.id === id);
      if (!slideToDelete) return false;

      const { error } = await supabase
        .from('presentation_slides')
        .delete()
        .eq('id', id);

      if (error) throw error;

      // Reorder remaining slides
      const remainingSlides = slides.filter(s => s.id !== id);
      for (let i = 0; i < remainingSlides.length; i++) {
        if (remainingSlides[i].sort_order !== i) {
          await supabase
            .from('presentation_slides')
            .update({ sort_order: i })
            .eq('id', remainingSlides[i].id);
        }
      }

      return true;
    } catch (error) {
      console.error('Error deleting slide:', error);
      toast({
        title: 'Error',
        description: 'Failed to delete slide',
        variant: 'destructive',
      });
      return false;
    }
  };

  const duplicateSlide = async (id: string): Promise<PresentationSlide | null> => {
    const original = slides.find(s => s.id === id);
    if (!original || !presentationId) return null;

    try {
      const insertData = {
        presentation_id: presentationId,
        title: `${original.title} (Copy)`,
        template: original.template,
        content: original.content as unknown as Json,
        html_content: original.html_content,
        speaker_notes: original.speaker_notes,
        transition: original.transition as unknown as Json,
        background: original.background as unknown as Json,
        shapes: original.shapes as unknown as Json,
        images: original.images as unknown as Json,
        charts: original.charts as unknown as Json,
        sort_order: original.sort_order + 1,
      };

      const { data, error } = await supabase
        .from('presentation_slides')
        .insert(insertData)
        .select()
        .single();

      if (error) throw error;

      // Shift subsequent slides down
      const slidesToShift = slides.filter(s => s.sort_order > original.sort_order);
      for (const slide of slidesToShift) {
        await supabase
          .from('presentation_slides')
          .update({ sort_order: slide.sort_order + 1 })
          .eq('id', slide.id);
      }

      return parseSlide(data as RawSlide);
    } catch (error) {
      console.error('Error duplicating slide:', error);
      toast({
        title: 'Error',
        description: 'Failed to duplicate slide',
        variant: 'destructive',
      });
      return null;
    }
  };

  const reorderSlides = async (slideIds: string[]): Promise<boolean> => {
    try {
      for (let i = 0; i < slideIds.length; i++) {
        await supabase
          .from('presentation_slides')
          .update({ sort_order: i })
          .eq('id', slideIds[i]);
      }

      return true;
    } catch (error) {
      console.error('Error reordering slides:', error);
      toast({
        title: 'Error',
        description: 'Failed to reorder slides',
        variant: 'destructive',
      });
      return false;
    }
  };

  const uploadImage = async (file: File): Promise<string | null> => {
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
      const filePath = `${presentationId}/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('presentation-assets')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from('presentation-assets')
        .getPublicUrl(filePath);

      return publicUrl;
    } catch (error) {
      console.error('Error uploading image:', error);
      toast({
        title: 'Error',
        description: 'Failed to upload image',
        variant: 'destructive',
      });
      return null;
    }
  };

  const addShape = async (slideId: string, shape: Omit<SlideShape, 'id'>): Promise<boolean> => {
    const slide = slides.find(s => s.id === slideId);
    if (!slide) return false;

    const newShape: SlideShape = {
      ...shape,
      id: `shape-${Date.now()}`,
    };

    return updateSlide(slideId, {
      shapes: [...slide.shapes, newShape],
    });
  };

  const updateShape = async (slideId: string, shapeId: string, updates: Partial<SlideShape>): Promise<boolean> => {
    const slide = slides.find(s => s.id === slideId);
    if (!slide) return false;

    const updatedShapes = slide.shapes.map(s =>
      s.id === shapeId ? { ...s, ...updates } : s
    );

    return updateSlide(slideId, { shapes: updatedShapes });
  };

  const deleteShape = async (slideId: string, shapeId: string): Promise<boolean> => {
    const slide = slides.find(s => s.id === slideId);
    if (!slide) return false;

    const updatedShapes = slide.shapes.filter(s => s.id !== shapeId);
    return updateSlide(slideId, { shapes: updatedShapes });
  };

  return {
    slides,
    loading,
    createSlide,
    updateSlide,
    saveSlideDebounced,
    deleteSlide,
    duplicateSlide,
    reorderSlides,
    uploadImage,
    addShape,
    updateShape,
    deleteShape,
    refetch: fetchSlides,
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';

export interface NotebookSpreadsheet {
  id: string;
  notebook_id: string;
  name: string;
  color: string | null;
  sort_order: number;
  created_at: string;
  updated_at: string;
  // Linked project plan fields
  linked_project_id: string | null;
  linked_at: string | null;
  last_synced_at: string | null;
  sync_status: 'synced' | 'syncing' | 'error' | null;
  sync_direction: 'spreadsheet' | 'project' | 'both' | null;
}

export interface SpreadsheetSheet {
  id: string;
  spreadsheet_id: string;
  name: string;
  data: any[][]; // Array of rows, each row is an array of cell values
  column_widths: Record<string, number>;
  row_heights: Record<string, number>;
  frozen_rows: number;
  frozen_cols: number;
  sort_order: number;
  created_at: string;
  updated_at: string;
}

export function useSpreadsheets(notebookId: string | null) {
  const [spreadsheets, setSpreadsheets] = useState<NotebookSpreadsheet[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  const isValidUuid = (id: string | null | undefined): boolean => {
    if (!id) return false;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id);
  };

  const fetchSpreadsheets = async () => {
    if (!notebookId || !isValidUuid(notebookId)) {
      setSpreadsheets([]);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('notebook_spreadsheets')
        .select('*')
        .eq('notebook_id', notebookId)
        .order('sort_order', { ascending: true });

      if (error) throw error;
      // Cast the data to our interface type
      setSpreadsheets((data || []) as unknown as NotebookSpreadsheet[]);
    } catch (error) {
      console.error('Error fetching spreadsheets:', error);
    } finally {
      setLoading(false);
    }
  };

  const createSpreadsheet = async (name: string, color?: string) => {
    if (!notebookId || !isValidUuid(notebookId)) return null;

    try {
      const { data: spreadsheet, error } = await supabase
        .from('notebook_spreadsheets')
        .insert({
          notebook_id: notebookId,
          name,
          color,
          sort_order: spreadsheets.length,
        })
        .select()
        .single();

      if (error) throw error;

      // Create default first sheet
      await supabase
        .from('spreadsheet_sheets')
        .insert({
          spreadsheet_id: spreadsheet.id,
          name: 'Sheet 1',
          data: createEmptyGrid(20, 10),
          sort_order: 0,
        });

      toast({ title: 'Spreadsheet created' });
      return spreadsheet as unknown as NotebookSpreadsheet;
    } catch (error) {
      console.error('Error creating spreadsheet:', error);
      toast({ title: 'Error', description: 'Failed to create spreadsheet', variant: 'destructive' });
      return null;
    }
  };

  const updateSpreadsheet = async (id: string, updates: Partial<NotebookSpreadsheet>) => {
    try {
      const { error } = await supabase
        .from('notebook_spreadsheets')
        .update(updates)
        .eq('id', id);

      if (error) throw error;
    } catch (error) {
      console.error('Error updating spreadsheet:', error);
      toast({ title: 'Error', description: 'Failed to update spreadsheet', variant: 'destructive' });
    }
  };

  const deleteSpreadsheet = async (id: string) => {
    try {
      const { error } = await supabase
        .from('notebook_spreadsheets')
        .delete()
        .eq('id', id);

      if (error) throw error;
      toast({ title: 'Spreadsheet deleted' });
    } catch (error) {
      console.error('Error deleting spreadsheet:', error);
      toast({ title: 'Error', description: 'Failed to delete spreadsheet', variant: 'destructive' });
    }
  };

  useEffect(() => {
    fetchSpreadsheets();
  }, [notebookId]);

  // Subscribe to realtime updates
  useEffect(() => {
    if (!notebookId || !isValidUuid(notebookId)) return;

    const channel = supabase
      .channel(`spreadsheets-${notebookId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'notebook_spreadsheets',
          filter: `notebook_id=eq.${notebookId}`,
        },
        () => {
          fetchSpreadsheets();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [notebookId]);

  return {
    spreadsheets,
    loading,
    createSpreadsheet,
    updateSpreadsheet,
    deleteSpreadsheet,
    refetch: fetchSpreadsheets,
  };
}

export function useSheets(spreadsheetId: string | null) {
  const [sheets, setSheets] = useState<SpreadsheetSheet[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  const isValidUuid = (id: string | null | undefined): boolean => {
    if (!id) return false;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id);
  };

  const fetchSheets = async () => {
    if (!spreadsheetId || !isValidUuid(spreadsheetId)) {
      setSheets([]);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('spreadsheet_sheets')
        .select('*')
        .eq('spreadsheet_id', spreadsheetId)
        .order('sort_order', { ascending: true });

      if (error) throw error;

      // Parse JSON data with proper typing
      const parsedData: SpreadsheetSheet[] = (data || []).map(sheet => ({
        id: sheet.id,
        spreadsheet_id: sheet.spreadsheet_id,
        name: sheet.name,
        data: Array.isArray(sheet.data) ? sheet.data as any[][] : [],
        column_widths: (typeof sheet.column_widths === 'object' && sheet.column_widths !== null && !Array.isArray(sheet.column_widths))
          ? sheet.column_widths as Record<string, number>
          : {},
        row_heights: (typeof sheet.row_heights === 'object' && sheet.row_heights !== null && !Array.isArray(sheet.row_heights))
          ? sheet.row_heights as Record<string, number>
          : {},
        frozen_rows: sheet.frozen_rows ?? 0,
        frozen_cols: sheet.frozen_cols ?? 0,
        sort_order: sheet.sort_order ?? 0,
        created_at: sheet.created_at,
        updated_at: sheet.updated_at,
      }));

      setSheets(parsedData);
    } catch (error) {
      console.error('Error fetching sheets:', error);
    } finally {
      setLoading(false);
    }
  };

  const createSheet = async (name: string = 'New Sheet') => {
    if (!spreadsheetId || !isValidUuid(spreadsheetId)) return null;

    try {
      const { data, error } = await supabase
        .from('spreadsheet_sheets')
        .insert({
          spreadsheet_id: spreadsheetId,
          name,
          data: createEmptyGrid(20, 10),
          sort_order: sheets.length,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    } catch (error) {
      console.error('Error creating sheet:', error);
      toast({ title: 'Error', description: 'Failed to create sheet', variant: 'destructive' });
      return null;
    }
  };

  const updateSheet = async (id: string, updates: Partial<SpreadsheetSheet>) => {
    try {
      const { error } = await supabase
        .from('spreadsheet_sheets')
        .update(updates)
        .eq('id', id);

      if (error) throw error;
    } catch (error) {
      console.error('Error updating sheet:', error);
      toast({ title: 'Error', description: 'Failed to save sheet', variant: 'destructive' });
    }
  };

  const deleteSheet = async (id: string) => {
    if (sheets.length <= 1) {
      toast({ title: 'Cannot delete', description: 'Spreadsheet must have at least one sheet', variant: 'destructive' });
      return;
    }

    try {
      const { error } = await supabase
        .from('spreadsheet_sheets')
        .delete()
        .eq('id', id);

      if (error) throw error;
      toast({ title: 'Sheet deleted' });
    } catch (error) {
      console.error('Error deleting sheet:', error);
      toast({ title: 'Error', description: 'Failed to delete sheet', variant: 'destructive' });
    }
  };

  useEffect(() => {
    fetchSheets();
  }, [spreadsheetId]);

  // Subscribe to realtime updates
  useEffect(() => {
    if (!spreadsheetId || !isValidUuid(spreadsheetId)) return;

    const channel = supabase
      .channel(`sheets-${spreadsheetId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'spreadsheet_sheets',
          filter: `spreadsheet_id=eq.${spreadsheetId}`,
        },
        () => {
          fetchSheets();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [spreadsheetId]);

  return {
    sheets,
    loading,
    createSheet,
    updateSheet,
    deleteSheet,
    refetch: fetchSheets,
  };
}

// Helper function to create an empty grid
function createEmptyGrid(rows: number, cols: number): any[][] {
  return Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () => '')
  );
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type SprintStatus = 'planning' | 'active' | 'completed' | 'cancelled';

export interface Sprint { id: string; project_id: string | null; name: string; start_date: string; end_date: string; goal: string | null; velocity: number; capacity: number; status: SprintStatus; created_at: string; updated_at: string; }
export interface SprintInput { name: string; start_date: string; end_date: string; goal?: string; capacity?: number; status?: SprintStatus; }

export function useSprints() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [sprints, setSprints] = useState<Sprint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchSprints = useCallback(async () => {
    if (!projectId) { setSprints([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('sprints').select('*').eq('project_id', projectId).order('start_date', { ascending: false });
      if (e) throw e;
      setSprints((data || []).map((s: any) => ({ ...s, status: s.status as SprintStatus })));
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchSprints(); }, [fetchSprints]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('sprints-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'sprints', filter: `project_id=eq.${projectId}` }, () => fetchSprints()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchSprints]);

  const createSprint = async (input: SprintInput) => {
    if (!projectId) { toast.error('No project selected'); return null; }
    try {
      const { data, error: e } = await supabase.from('sprints').insert({ project_id: projectId, name: input.name, start_date: input.start_date, end_date: input.end_date, goal: input.goal || null, capacity: input.capacity || 0, status: input.status || 'planning' }).select().single();
      if (e) throw e;
      toast.success('Sprint created'); return data;
    } catch { toast.error('Failed to create sprint'); return null; }
  };

  const updateSprint = async (id: string, updates: Partial<SprintInput & { velocity?: number }>) => {
    try { const { error: e } = await supabase.from('sprints').update(updates).eq('id', id); if (e) throw e; toast.success('Sprint updated'); return true; } catch { toast.error('Failed to update sprint'); return false; }
  };

  const startSprint = async (id: string) => { const active = sprints.find(s => s.status === 'active'); if (active) await updateSprint(active.id, { status: 'completed' }); return updateSprint(id, { status: 'active' }); };
  const completeSprint = async (id: string, velocity: number) => updateSprint(id, { status: 'completed', velocity });
  const deleteSprint = async (id: string) => { try { await supabase.from('sprints').delete().eq('id', id); toast.success('Sprint deleted'); return true; } catch { toast.error('Failed'); return false; } };

  const activeSprint = sprints.find(s => s.status === 'active');
  const planningSprints = sprints.filter(s => s.status === 'planning');
  const completedSprints = sprints.filter(s => s.status === 'completed');
  const averageVelocity = completedSprints.length > 0 ? Math.round(completedSprints.reduce((sum, s) => sum + s.velocity, 0) / completedSprints.length) : 0;

  return { sprints, loading, error, refetch: fetchSprints, createSprint, updateSprint, startSprint, completeSprint, deleteSprint, activeSprint, planningSprints, completedSprints, averageVelocity };
}

