  return useMutation({
    mutationFn: async ({ projectId, name, description }: {
      projectId: string;
      name: string;
      description?: string
    }) => {
      // Get all tasks for the project
      const { data: tasks, error: tasksError } = await supabase
        .from('tasks')
        .select('*')
        .eq('project_id', projectId);

      if (tasksError) throw tasksError;

      // Create project baseline record
      const { data: baseline, error: baselineError } = await supabase
        .from('project_baselines')
        .insert({ project_id: projectId, name, description })
        .select()
        .single();

      if (baselineError) throw baselineError;

      // Create task baselines for all tasks
      const taskBaselines = tasks.map(task => ({
        task_id: task.id,
        baseline_name: name,
        baseline_start: task.start_date,
        baseline_end: task.end_date,
        baseline_duration: task.duration,
        baseline_cost: 0,
      }));

      if (taskBaselines.length > 0) {
        const { error: taskBaselineError } = await supabase
          .from('task_baselines')
          .insert(taskBaselines);

        if (taskBaselineError) throw taskBaselineError;
      }

      return { projectId, baseline };
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ['project-baselines', data.projectId] });
      toast.success('Project baseline saved');
    },
    onError: (error) => {
      toast.error('Failed to save baseline: ' + error.message);
    },
  });
}

import { useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { useQueryClient } from '@tanstack/react-query';
import { Database } from '@/integrations/supabase/types';

type TaskType = Database['public']['Enums']['task_type'];
type TaskStatus = Database['public']['Enums']['task_status'];
type PriorityLevel = Database['public']['Enums']['priority_level'];

interface TimelineData {
    swimlanes: any[];
    milestones: any[];
}

export function useTimelineGenerator() {
    const [isGenerating, setIsGenerating] = useState(false);
    const queryClient = useQueryClient();

    const generatePlan = async (projectId: string, data: TimelineData) => {
        setIsGenerating(true);
        try {
            if (!projectId) throw new Error("Project ID is required");

            const { swimlanes } = data;
            // We map manually to types acceptable by Supabase

            const activityIdMap = new Map<string, string>(); // OldActivityId -> NewTaskId

            for (let sIndex = 0; sIndex < swimlanes.length; sIndex++) {
                const swimlane = swimlanes[sIndex];

                // 1. Create Phase Task
                const phaseTask = {
                    project_id: projectId,
                    wbs: `${sIndex + 1}.0`,
                    name: swimlane.label,
                    type: 'phase' as TaskType,
                    status: 'not-started' as TaskStatus,
                    priority: 'medium' as PriorityLevel,
                    start_date: new Date().toISOString().split('T')[0],
                    end_date: new Date().toISOString().split('T')[0],
                    duration: 0,
                    progress: 0,
                    level: 0,
                    sort_order: sIndex * 1000,
                    expanded: true,
                    parent_id: null
                };

                const { data: insertedPhase, error: phaseError } = await supabase
                    .from('tasks')
                    .insert(phaseTask)
                    .select()
                    .single();

                if (phaseError) throw phaseError;
                const phaseId = insertedPhase.id;

                // 2. Process Activities
                if (swimlane.activities && swimlane.activities.length > 0) {
                    const sortedActivities = [...swimlane.activities].sort((a: any, b: any) => a.start - b.start);

                    for (let aIndex = 0; aIndex < sortedActivities.length; aIndex++) {
                        const activity = sortedActivities[aIndex];
                        // Date calc
                        const baseDate = new Date();
                        const startOffsetDays = activity.start * 30;
                        const durationDays = activity.duration * 30;

                        const startDate = new Date(baseDate);
                        startDate.setDate(startDate.getDate() + startOffsetDays);

                        const endDate = new Date(startDate);
                        endDate.setDate(startDate.getDate() + durationDays);

                        const task = {
                            project_id: projectId,
                            parent_id: phaseId,
                            wbs: `${sIndex + 1}.${aIndex + 1}`,
                            name: activity.name,
                            type: 'task' as TaskType,
                            status: 'not-started' as TaskStatus,
                            priority: 'medium' as PriorityLevel,
                            start_date: startDate.toISOString().split('T')[0],
                            end_date: endDate.toISOString().split('T')[0],
                            duration: durationDays,
                            progress: 0,
                            level: 1,
                            sort_order: (sIndex * 1000) + (aIndex + 1) * 100,
                            expanded: true,
                            notes: activity.notes
                        };

                        const { data: insertedTask, error: taskError } = await supabase
                            .from('tasks')
                            .insert(task)
                            .select()
                            .single();

                        if (taskError) throw taskError;

                        activityIdMap.set(activity.id, insertedTask.id);
                    }
                }
            }

            // 3. Process Dependencies
            const newDependencies: any[] = [];

            data.swimlanes.forEach(swimlane => {
                swimlane.activities?.forEach((activity: any) => {
                    if (activity.dependencies) {
                        activity.dependencies.forEach((dep: any) => {
                            const successorId = activityIdMap.get(activity.id);
                            const predecessorId = activityIdMap.get(dep.targetId);

                            if (successorId && predecessorId) {
                                newDependencies.push({
                                    task_id: successorId,
                                    predecessor_id: predecessorId,
                                    type: dep.type || 'FS',
                                    lag: 0
                                });
                            }
                        });
                    }
                });
            });

            if (newDependencies.length > 0) {
                const { error: depError } = await supabase
                    .from('task_dependencies')
                    .insert(newDependencies);

                if (depError) throw depError;
            }

            toast.success(`Project Plan Generated with ${activityIdMap.size} tasks!`);
            queryClient.invalidateQueries({ queryKey: ['tasks', projectId] });
            queryClient.invalidateQueries({ queryKey: ['dependencies', projectId] });

        } catch (error: any) {
            console.error("Error generating plan:", error);
            toast.error(`Failed to generate plan: ${error.message}`);
        } finally {
            setIsGenerating(false);
        }
    };

    return { generatePlan, isGenerating };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Database } from "@/integrations/supabase/types";

export interface TraceabilityLink {
    id: string;
    projectId: string;
    sourceId: string;
    sourceType: string;
    targetId: string;
    targetType: string;
    relationshipType: string;
}

export interface TraceabilityItem {
    id: string;
    type: 'sprint' | 'issue' | 'action' | 'decision' | 'risk' | 'meeting' | 'task';
    title: string;
    status: string;
    linkedTo: { type: string; id: string; title: string }[];
}

export const useTraceability = (projectId?: string) => {
    return useQuery({
        queryKey: ["traceability", projectId],
        queryFn: async () => {
            if (!projectId) return [];

            // Fetch links
            const { data: links, error: linksError } = await supabase
                .from("traceability_matrix")
                .select("*")
                .eq("project_id", projectId);

            if (linksError) throw linksError;

            // Fetch all potential entities
            const [
                { data: sprints },
                { data: issues },
                { data: actions },
                { data: decisions },
                { data: risks },
                { data: meetings },
                { data: tasks },
            ] = await Promise.all([
                supabase.from("sprints").select("id, name, status").eq("project_id", projectId),
                supabase.from("issues").select("id, title, status").eq("project_id", projectId),
                supabase.from("actions").select("id, title, status, project_id").eq("project_id", projectId),
                supabase.from("decisions").select("id, title, status, project_id").eq("project_id", projectId),
                supabase.from("risks").select("id, title, status").eq("project_id", projectId),
                supabase.from("meetings").select("id, title, status").eq("project_id", projectId),
                supabase.from("tasks").select("id, name, status").eq("project_id", projectId),
            ]);

            // Helper to find title and status
            const getEntityInfo = (id: string, type: string) => {
                switch (type) {
                    case 'sprint': return { title: sprints?.find(s => s.id === id)?.name || id, status: sprints?.find(s => s.id === id)?.status || 'unknown' };
                    case 'issue': return { title: issues?.find(i => i.id === id)?.title || id, status: issues?.find(i => i.id === id)?.status || 'unknown' };
                    case 'action': return { title: actions?.find(a => a.id === id)?.title || id, status: actions?.find(a => a.id === id)?.status || 'unknown' };
                    case 'decision': return { title: decisions?.find(d => d.id === id)?.title || id, status: decisions?.find(d => d.id === id)?.status || 'unknown' };
                    case 'risk': return { title: risks?.find(r => r.id === id)?.title || id, status: risks?.find(r => r.id === id)?.status || 'unknown' };
                    case 'meeting': return { title: meetings?.find(m => m.id === id)?.title || id, status: meetings?.find(m => m.id === id)?.status || 'unknown' };
                    case 'task': return { title: tasks?.find(t => t.id === id)?.name || id, status: tasks?.find(t => t.id === id)?.status || 'unknown' };
                    default: return { title: id, status: 'unknown' };
                }
            };

            // Collect all entities that have links
            const entityIds = new Set<string>();
            links.forEach(link => {
                entityIds.add(`${link.source_type}:${link.source_id}`);
                entityIds.add(`${link.target_type}:${link.target_id}`);
            });

            const result: TraceabilityItem[] = [];

            entityIds.forEach(compositeId => {
                const [type, id] = compositeId.split(':');
                const info = getEntityInfo(id, type);

                const linkedTo = links
                    .filter(link =>
                        (link.source_id === id && link.source_type === type) ||
                        (link.target_id === id && link.target_type === type)
                    )
                    .map(link => {
                        const isSource = link.source_id === id && link.source_type === type;
                        const targetId = isSource ? link.target_id : link.source_id;
                        const targetType = isSource ? link.target_type : link.source_type;
                        const targetInfo = getEntityInfo(targetId, targetType);

                        return {
                            type: targetType,
                            id: targetId,
                            title: targetInfo.title
                        };
                    });

                result.push({
                    id,
                    type: type as any,
                    title: info.title,
                    status: info.status,
                    linkedTo
                });
            });

            return result;
        },
    });
};

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { useAuth } from './useAuth';

export interface UserPreference {
    id: string;
    user_id: string;
    project_id: string;
    preference_key: string;
    preference_value: any;
    updated_at: string;
}

export function useUserPreferences(projectId: string | null) {
    const { user } = useAuth();
    const queryClient = useQueryClient();

    // Fetch all preferences for this project/user
    const query = useQuery({
        queryKey: ['user-preferences', projectId, user?.id],
        queryFn: async () => {
            if (!projectId || !user) return [];
            const { data, error } = await supabase
                .from('user_preferences')
                .select('*')
                .eq('project_id', projectId)
                .eq('user_id', user.id);

            if (error) {
                // Return empty if table doesn't exist yet (for smooth dev experience)
                if (error.code === '42P01') return [];
                throw error;
            }
            return data as UserPreference[];
        },
        enabled: !!projectId && !!user,
    });

    const updatePreference = useMutation({
        mutationFn: async ({ key, value }: { key: string; value: any }) => {
            if (!projectId || !user) throw new Error('No project or user');

            const { data, error } = await supabase
                .from('user_preferences')
                .upsert({
                    user_id: user.id,
                    project_id: projectId,
                    preference_key: key,
                    preference_value: value,
                    updated_at: new Date().toISOString(),
                }, { onConflict: 'user_id, project_id, preference_key' })
                .select()
                .single();

            if (error) throw error;
            return data;
        },
        onSuccess: (data) => {
            queryClient.setQueryData(
                ['user-preferences', projectId, user?.id],
                (old: UserPreference[] | undefined) => {
                    if (!old) return [data];
                    const index = old.findIndex(p => p.preference_key === data.preference_key);
                    if (index >= 0) {
                        return [...old.slice(0, index), data, ...old.slice(index + 1)];
                    }
                    return [...old, data];
                }
            );
        },
        onError: (error) => {
            console.error('Failed to save preference:', error);
            // toast.error('Failed to save settings'); // Optional: Too noisy for auto-save
        }
    });

    const getPreference = (key: string) => {
        return query.data?.find(p => p.preference_key === key)?.preference_value;
    };

    return {
        preferences: query.data || [],
        isLoading: query.isLoading,
        updatePreference,
        getPreference,
    };
}

