    );
  }
});

function buildMeetingContext(meeting: any): string {
  const parts: string[] = [];

  parts.push(`# Meeting: ${meeting.title}`);
  parts.push(`Date: ${meeting.date}`);
  parts.push(`Time: ${meeting.start_time} - ${meeting.end_time || "ongoing"}`);
  parts.push(`Type: ${meeting.purpose_type}`);

  if (meeting.purpose_description) {
    parts.push(`\n## Purpose\n${meeting.purpose_description}`);
  }

  if (meeting.expected_outcomes?.length > 0) {
    parts.push(`\n## Expected Outcomes\n${meeting.expected_outcomes.map((o: string) => `- ${o}`).join("\n")}`);
  }

  if (meeting.meeting_participants?.length > 0) {
    parts.push(`\n## Participants`);
    meeting.meeting_participants.forEach((p: any) => {
      parts.push(`- ${p.name} (${p.role})`);
    });
  }

  if (meeting.meeting_agenda_items?.length > 0) {
    parts.push(`\n## Agenda`);
    meeting.meeting_agenda_items.forEach((a: any, i: number) => {
      parts.push(`${i + 1}. ${a.title}${a.description ? `: ${a.description}` : ""}`);
    });
  }

  if (meeting.transcript_text) {
    parts.push(`\n## Transcript\n${meeting.transcript_text}`);
  }

  if (meeting.meeting_notes?.length > 0) {
    parts.push(`\n## Meeting Notes`);
    meeting.meeting_notes.forEach((n: any) => {
      const timestamp = n.timestamp_in_meeting ? `[${n.timestamp_in_meeting}] ` : "";
      const type = n.note_type !== "note" ? `[${n.note_type.toUpperCase()}] ` : "";
      parts.push(`${timestamp}${type}${n.content}`);
    });
  }

  return parts.join("\n");
}

async function saveExtractedData(supabase: any, meetingId: string, extracted: any) {
  // Save decisions
  if (extracted.decisions?.length > 0) {
    const decisions = extracted.decisions.map((d: any) => ({
      meeting_id: meetingId,
      description: d.description,
      decision_type: d.decision_type,
      made_by: d.made_by,
      impact: d.impact || "medium",
      timestamp_in_meeting: d.timestamp_in_meeting,
      source: "inferred",
      ai_confidence: d.confidence,
    }));
    await supabase.from("meeting_decisions").insert(decisions);
  }

  // Save action items
  if (extracted.action_items?.length > 0) {
    const actions = extracted.action_items.map((a: any) => ({
      meeting_id: meetingId,
      title: a.title,
      description: a.description,
      owner_name: a.owner_name,
      due_date: a.due_date,
      priority: a.priority || "medium",
      source: a.source || "inferred",
      ai_confidence: a.confidence,
    }));
    await supabase.from("meeting_action_items").insert(actions);
  }

  // Save risks
  if (extracted.risks?.length > 0) {
    const risks = extracted.risks.map((r: any) => ({
      meeting_id: meetingId,
      title: r.title,
      description: r.description,
      probability: r.probability || "medium",
      impact: r.impact || "medium",
      category: r.category,
      suggested_mitigation: r.suggested_mitigation,
      source: r.source || "inferred",
      ai_confidence: r.confidence,
    }));
    await supabase.from("meeting_risks").insert(risks);
  }

  // Save scope changes
  if (extracted.scope_changes?.length > 0) {
    const scopeChanges = extracted.scope_changes.map((s: any) => ({
      meeting_id: meetingId,
      description: s.description,
      change_type: s.change_type,
      impact_area: s.impact_area,
      magnitude: s.magnitude,
      requires_approval: s.requires_approval ?? true,
      ai_confidence: s.confidence,
    }));
    await supabase.from("meeting_scope_changes").insert(scopeChanges);
  }

  // Save conflicts
  if (extracted.conflicts?.length > 0) {
    const conflicts = extracted.conflicts.map((c: any) => ({
      meeting_id: meetingId,
      description: c.description,
      parties: c.parties || [],
      severity: c.severity || "medium",
      conflict_type: c.conflict_type,
      suggested_resolution: c.suggested_resolution,
      ai_confidence: c.confidence,
    }));
    await supabase.from("meeting_conflicts").insert(conflicts);
  }
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { meetingId, templateId } = await req.json();

    if (!meetingId) {
      return new Response(
        JSON.stringify({ error: "meetingId is required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Initialize Supabase client
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    // Fetch meeting with all related data
    const { data: meeting, error: meetingError } = await supabase
      .from("meetings")
      .select(`
        *,
        meeting_participants (*),
        meeting_agenda_items (*),
        meeting_decisions (*),
        meeting_action_items (*),
        meeting_risks (*),
        meeting_notes (*)
      `)
      .eq("id", meetingId)
      .single();

    if (meetingError || !meeting) {
      return new Response(
        JSON.stringify({ error: "Meeting not found" }),
        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Fetch template if specified
    let template = null;
    if (templateId) {
      const { data: templateData } = await supabase
        .from("mom_templates")
        .select("*")
        .eq("id", templateId)
        .single();
      template = templateData;
    }

    // Build MoM content
    const momContent = generateMoMContent(meeting, template);

    // Call AI to polish and format the MoM
    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");

    let finalContent = momContent;

    if (LOVABLE_API_KEY) {
      const aiResponse = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${LOVABLE_API_KEY}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: "google/gemini-3-flash-preview",
          messages: [
            {
              role: "system",
              content: `You are an expert at writing professional Minutes of Meeting (MoM) documents. 
Your task is to polish and format the provided meeting content into a clear, professional document.

Guidelines:
- Use clear, professional language
- Maintain consistent formatting
- Ensure all action items have clear owners and due dates
- Highlight key decisions prominently
- Keep the document concise but complete
- Use bullet points for clarity
- Include section headers

Output the polished MoM in Markdown format.`,
            },
            {
              role: "user",
              content: `Please polish and format these meeting minutes:\n\n${momContent}`,
            },
          ],
        }),
      });

      if (aiResponse.ok) {
        const aiResult = await aiResponse.json();
        finalContent = aiResult.choices?.[0]?.message?.content || momContent;
      }
    }

    // Update meeting with MoM content
    await supabase
      .from("meetings")
      .update({
        mom_generated: true,
        mom_content: finalContent,
        mom_template_id: templateId || null,
      })
      .eq("id", meetingId);

    return new Response(
      JSON.stringify({ success: true, content: finalContent }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("Error generating MoM:", error);
    const errorMessage = error instanceof Error ? error.message : "Internal server error";
    return new Response(
      JSON.stringify({ error: errorMessage }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

function generateMoMContent(meeting: any, template: any): string {
  const sections: string[] = [];

  const dateStr = new Date(meeting.date).toLocaleDateString("en-US", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  // Header
  sections.push(`# Minutes of Meeting\n`);
  sections.push(`## ${meeting.title}\n`);
  sections.push(`**Date:** ${dateStr}`);
  sections.push(`**Time:** ${meeting.start_time}${meeting.end_time ? ` - ${meeting.end_time}` : ""}`);
  sections.push(`**Type:** ${meeting.purpose_type?.replace("-", " ").toUpperCase()}`);
  if (meeting.location) sections.push(`**Location:** ${meeting.location}`);
  if (meeting.meeting_link) sections.push(`**Meeting Link:** ${meeting.meeting_link}`);
  sections.push("");

  // Purpose
  if (meeting.purpose_description) {
    sections.push(`## Meeting Purpose\n`);
    sections.push(meeting.purpose_description);
    sections.push("");
  }

  // Attendees
  if (meeting.meeting_participants?.length > 0) {
    sections.push(`## Attendees\n`);
    const attendees = meeting.meeting_participants;

    const decisionMakers = attendees.filter((p: any) => p.role === "decision-maker");
    const others = attendees.filter((p: any) => p.role !== "decision-maker");

    if (decisionMakers.length > 0) {
      sections.push("**Decision Makers:**");
      decisionMakers.forEach((p: any) => {
        const status = p.attended ? "✓ Attended" : p.attendance_status;
        sections.push(`- ${p.name} (${p.role}) - ${status}`);
      });
    }

    if (others.length > 0) {
      sections.push("\n**Participants:**");
      others.forEach((p: any) => {
        const status = p.attended ? "✓ Attended" : p.attendance_status;
        sections.push(`- ${p.name} (${p.role}) - ${status}`);
      });
    }
    sections.push("");
  }

  // Agenda
  if (meeting.meeting_agenda_items?.length > 0) {
    sections.push(`## Agenda\n`);
    meeting.meeting_agenda_items
      .sort((a: any, b: any) => a.sort_order - b.sort_order)
      .forEach((item: any, i: number) => {
        const duration = item.duration_minutes ? ` (${item.duration_minutes} min)` : "";
        const presenter = item.presenter_name ? ` - Presenter: ${item.presenter_name}` : "";
        sections.push(`${i + 1}. ${item.title}${duration}${presenter}`);
        if (item.description) sections.push(`   ${item.description}`);
      });
    sections.push("");
  }

  // AI Summary
  if (meeting.ai_summary) {
    sections.push(`## Executive Summary\n`);
    sections.push(meeting.ai_summary);
    sections.push("");
  }

  // Decisions
  if (meeting.meeting_decisions?.length > 0) {
    sections.push(`## Decisions Made\n`);
    meeting.meeting_decisions.forEach((d: any, i: number) => {
      const impactBadge = d.impact === "high" ? "🔴" : d.impact === "medium" ? "🟡" : "🟢";
      const typeBadge = d.decision_type === "irreversible" ? "⚠️ IRREVERSIBLE" : d.decision_type === "temporary" ? "⏳ TEMPORARY" : "";
      sections.push(`### Decision ${i + 1} ${impactBadge} ${typeBadge}`);
      sections.push(d.description);
      if (d.made_by) sections.push(`**Made by:** ${d.made_by}`);
      if (d.timestamp_in_meeting) sections.push(`**Time:** ${d.timestamp_in_meeting}`);
      sections.push("");
    });
  }

  // Action Items
  if (meeting.meeting_action_items?.length > 0) {
    sections.push(`## Action Items\n`);
    sections.push("| # | Action | Owner | Due Date | Priority | Status |");
    sections.push("|---|--------|-------|----------|----------|--------|");
    meeting.meeting_action_items.forEach((a: any, i: number) => {
      const dueDate = a.due_date ? new Date(a.due_date).toLocaleDateString() : "TBD";
      const priority = a.priority?.toUpperCase() || "MEDIUM";
      const status = a.status?.replace("-", " ").toUpperCase() || "PENDING";
      sections.push(`| ${i + 1} | ${a.title} | ${a.owner_name} | ${dueDate} | ${priority} | ${status} |`);
    });
    sections.push("");
  }

  // Risks Identified
  if (meeting.meeting_risks?.length > 0) {
    sections.push(`## Risks Identified\n`);
    meeting.meeting_risks.forEach((r: any, i: number) => {
      sections.push(`### Risk ${i + 1}: ${r.title}`);
      if (r.description) sections.push(r.description);
      sections.push(`- **Probability:** ${r.probability?.toUpperCase()}`);
      sections.push(`- **Impact:** ${r.impact?.toUpperCase()}`);
      if (r.category) sections.push(`- **Category:** ${r.category}`);
      if (r.suggested_mitigation) sections.push(`- **Suggested Mitigation:** ${r.suggested_mitigation}`);
      sections.push("");
    });
  }

  // Next Steps
  if (meeting.ai_next_steps?.length > 0) {
    sections.push(`## Next Steps\n`);
    meeting.ai_next_steps.forEach((step: string) => {
      sections.push(`- ${step}`);
    });
    sections.push("");
  }

  // Footer
  sections.push("---");
  sections.push(`*Minutes generated on ${new Date().toLocaleDateString("en-US", { 
    year: "numeric", 
    month: "long", 
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit"
  })}*`);

  if (meeting.ai_confidence) {
    sections.push(`*AI Confidence: ${Math.round(meeting.ai_confidence * 100)}%*`);
  }

  return sections.join("\n");
}

import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

interface OAuthRequest {
  action: "get_auth_url" | "exchange_code" | "refresh_token";
  accountId?: string;
  clientId: string;
  clientSecret: string;
  redirectUri: string;
  tenantId?: string;
  code?: string;
  refreshToken?: string;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(supabaseUrl, supabaseKey);

  try {
    const request: OAuthRequest = await req.json();
    const tenantId = request.tenantId || "common";

    if (request.action === "get_auth_url") {
      const scopes = [
        "https://graph.microsoft.com/Mail.Read",
        "https://graph.microsoft.com/Mail.Send",
        "https://graph.microsoft.com/Mail.ReadWrite",
        "https://graph.microsoft.com/User.Read",
        "offline_access",
      ];

      const authUrl = new URL(
        `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/authorize`
      );
      authUrl.searchParams.set("client_id", request.clientId);
      authUrl.searchParams.set("redirect_uri", request.redirectUri);
      authUrl.searchParams.set("response_type", "code");
      authUrl.searchParams.set("scope", scopes.join(" "));
      authUrl.searchParams.set("response_mode", "query");

      return new Response(
        JSON.stringify({ url: authUrl.toString() }),
        {
          status: 200,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    if (request.action === "exchange_code") {
      if (!request.code) {
        throw new Error("Authorization code is required");
      }

      const tokenResponse = await fetch(
        `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`,
        {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            client_id: request.clientId,
            client_secret: request.clientSecret,
            code: request.code,
            grant_type: "authorization_code",
            redirect_uri: request.redirectUri,
            scope: "https://graph.microsoft.com/.default offline_access",
          }),
        }
      );

      const tokenData = await tokenResponse.json();

      if (!tokenResponse.ok) {
        throw new Error(tokenData.error_description || "Token exchange failed");
      }

      // Get user email from Graph API
      const userInfoResponse = await fetch(
        "https://graph.microsoft.com/v1.0/me",
        {
          headers: { Authorization: `Bearer ${tokenData.access_token}` },
        }
      );

      const userInfo = await userInfoResponse.json();

      return new Response(
        JSON.stringify({
          access_token: tokenData.access_token,
          refresh_token: tokenData.refresh_token,
          expires_in: tokenData.expires_in,
          email: userInfo.mail || userInfo.userPrincipalName,
        }),
        {
          status: 200,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    if (request.action === "refresh_token") {
      if (!request.refreshToken) {
        throw new Error("Refresh token is required");
      }

      const tokenResponse = await fetch(
        `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`,
        {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            client_id: request.clientId,
            client_secret: request.clientSecret,
            refresh_token: request.refreshToken,
            grant_type: "refresh_token",
            scope: "https://graph.microsoft.com/.default offline_access",
          }),
        }
      );

      const tokenData = await tokenResponse.json();

      if (!tokenResponse.ok) {
        throw new Error(tokenData.error_description || "Token refresh failed");
      }

      // Update the account with new token
      if (request.accountId) {
        const expiresAt = new Date(Date.now() + tokenData.expires_in * 1000);
        await supabase
          .from("email_accounts")
          .update({
            oauth_access_token: tokenData.access_token,
            oauth_refresh_token: tokenData.refresh_token || request.refreshToken,
            oauth_token_expires_at: expiresAt.toISOString(),
          })
          .eq("id", request.accountId);
      }

      return new Response(
        JSON.stringify({
          access_token: tokenData.access_token,
          refresh_token: tokenData.refresh_token,
          expires_in: tokenData.expires_in,
        }),
        {
          status: 200,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    throw new Error("Invalid action");
  } catch (error: any) {
    console.error("Microsoft OAuth error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "OAuth failed" }),
      {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

interface SyncRequest {
  accountId: string;
  maxResults?: number;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(supabaseUrl, supabaseKey);

  try {
    const { accountId, maxResults = 50 }: SyncRequest = await req.json();

    if (!accountId) {
      throw new Error("Account ID is required");
    }

    // Get account details
    const { data: account, error: accountError } = await supabase
      .from("email_accounts")
      .select("*")
      .eq("id", accountId)
      .single();

    if (accountError || !account) {
      throw new Error("Email account not found");
    }

    if (account.provider_type !== "microsoft") {
      throw new Error("Account is not a Microsoft account");
    }

    // Check if token needs refresh
    let accessToken = account.oauth_access_token;
    const tokenExpires = new Date(account.oauth_token_expires_at);

    if (tokenExpires < new Date()) {
      const refreshResponse = await supabase.functions.invoke("microsoft-oauth", {
        body: {
          action: "refresh_token",
          accountId,
          clientId: account.oauth_client_id,
          clientSecret: account.oauth_client_secret,
          refreshToken: account.oauth_refresh_token,
        },
      });

      if (refreshResponse.error) {
        throw new Error("Failed to refresh token");
      }

      accessToken = refreshResponse.data.access_token;
    }

    // Update sync status
    await supabase
      .from("email_accounts")
      .update({ sync_status: "syncing" })
      .eq("id", accountId);

    // Create folders if they don't exist
    const folderMap: Record<string, string> = {};

    // Fetch mail folders from Graph API
    const foldersResponse = await fetch(
      "https://graph.microsoft.com/v1.0/me/mailFolders",
      {
        headers: { Authorization: `Bearer ${accessToken}` },
      }
    );

    const foldersData = await foldersResponse.json();

    const folderTypeMap: Record<string, string> = {
      inbox: "inbox",
      sentitems: "sent",
      drafts: "drafts",
      deleteditems: "trash",
      junkemail: "spam",
      archive: "archive",
    };

    for (const folder of foldersData.value || []) {
      const folderType = folderTypeMap[folder.displayName.toLowerCase().replace(/\s/g, "")] || "custom";

      const { data: existingFolder } = await supabase
        .from("email_folders")
        .select("id")
        .eq("account_id", accountId)
        .eq("remote_name", folder.id)
        .single();

      if (!existingFolder) {
        const { data: newFolder } = await supabase
          .from("email_folders")
          .insert({
            account_id: accountId,
            name: folder.displayName,
            remote_name: folder.id,
            folder_type: folderType,
            unread_count: folder.unreadItemCount,
            total_count: folder.totalItemCount,
          })
          .select("id")
          .single();
        folderMap[folder.id] = newFolder?.id;
      } else {
        folderMap[folder.id] = existingFolder.id;
        // Update counts
        await supabase
          .from("email_folders")
          .update({
            unread_count: folder.unreadItemCount,
            total_count: folder.totalItemCount,
          })
          .eq("id", existingFolder.id);
      }
    }

    // Fetch messages from inbox
    const inboxFolderId = Object.keys(folderMap).find(
      (id) => foldersData.value?.find((f: any) => f.id === id)?.displayName.toLowerCase() === "inbox"
    );

    if (!inboxFolderId) {
      throw new Error("Could not find inbox folder");
    }

    const messagesResponse = await fetch(
      `https://graph.microsoft.com/v1.0/me/mailFolders/${inboxFolderId}/messages?$top=${maxResults}&$orderby=receivedDateTime desc`,
      {
        headers: { Authorization: `Bearer ${accessToken}` },
      }
    );

    const messagesData = await messagesResponse.json();

    if (!messagesResponse.ok) {
      throw new Error(messagesData.error?.message || "Failed to fetch messages");
    }

    let syncedCount = 0;

    for (const msg of messagesData.value || []) {
      try {
        // Check if already exists
        const { data: existing } = await supabase
          .from("emails")
          .select("id")
          .eq("message_id", msg.id)
          .eq("account_id", accountId)
          .single();

        if (existing) continue;

        // Parse addresses
        const toAddresses = (msg.toRecipients || []).map((r: any) => ({
          email: r.emailAddress.address,
          name: r.emailAddress.name,
        }));

        const ccAddresses = (msg.ccRecipients || []).map((r: any) => ({
          email: r.emailAddress.address,
          name: r.emailAddress.name,
        }));

        // Insert email
        await supabase.from("emails").insert({
          account_id: accountId,
          folder_id: folderMap[inboxFolderId],
          message_id: msg.id,
          thread_id: msg.conversationId,
          in_reply_to: msg.conversationIndex,
          subject: msg.subject,
          from_address: msg.from?.emailAddress?.address || "",
          from_name: msg.from?.emailAddress?.name,
          to_addresses: toAddresses,
          cc_addresses: ccAddresses,
          bcc_addresses: [],
          body_text: msg.body?.contentType === "text" ? msg.body.content : null,
          body_html: msg.body?.contentType === "html" ? msg.body.content : null,
          snippet: msg.bodyPreview,
          has_attachments: msg.hasAttachments,
          is_read: msg.isRead,
          is_starred: msg.flag?.flagStatus === "flagged",
          is_flagged: msg.importance === "high",
          received_at: msg.receivedDateTime,
          sent_at: msg.sentDateTime,
        });

        syncedCount++;
      } catch (err) {
        console.error(`Error syncing message ${msg.id}:`, err);
      }
    }

    // Update sync status
    await supabase
      .from("email_accounts")
      .update({
        sync_status: "success",
        last_sync_at: new Date().toISOString(),
        sync_error: null,
      })
      .eq("id", accountId);

    return new Response(
      JSON.stringify({
        success: true,
        synced: syncedCount,
        total: (messagesData.value || []).length,
      }),
      {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (error: any) {
    console.error("Microsoft sync error:", error);

    const { accountId } = await req.json().catch(() => ({}));
    if (accountId) {
      await supabase
        .from("email_accounts")
        .update({ sync_status: "error", sync_error: error.message })
        .eq("id", accountId);
    }

    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

